-- >>> supabase/migrations/0009_stock_views.sql
-- =============================================================================
-- 0009_stock_views.sql — derived stock + low-stock views (AceStock)
--
-- On-hand is always derived from the append-only inventory_txns ledger, never
-- stored. These views expose it conveniently, plus a low-stock flag using the
-- effective reorder point (variant's own, falling back to the product's).
-- =============================================================================

-- Per-variant on-hand + low-stock flag.
create or replace view variant_stock_detail as
select
  v.id                                              as variant_id,
  v.product_id                                      as product_id,
  coalesce(sum(t.qty), 0)::numeric                  as on_hand,
  coalesce(v.reorder_point, p.reorder_point)        as reorder_point,
  (
    coalesce(v.reorder_point, p.reorder_point) is not null
    and coalesce(sum(t.qty), 0) <= coalesce(v.reorder_point, p.reorder_point)
  )                                                 as is_low
from variants v
join products p on p.id = v.product_id
left join inventory_txns t on t.variant_id = v.id
group by v.id, v.product_id, v.reorder_point, p.reorder_point;

-- Per-product roll-up: total on-hand, variant count, any low-stock variant.
create or replace view product_stock as
select
  p.id                                              as product_id,
  coalesce(sum(vsd.on_hand), 0)::numeric            as on_hand,
  count(v.id)                                       as variant_count,
  coalesce(bool_or(vsd.is_low), false)              as has_low_stock
from products p
left join variants v on v.product_id = p.id
left join variant_stock_detail vsd on vsd.variant_id = v.id
group by p.id;

grant select on variant_stock_detail to authenticated;
grant select on product_stock to authenticated;

-- >>> supabase/migrations/0010_variant_upc.sql
-- =============================================================================
-- 0010_variant_upc.sql — unique UPC per variant (AceStock)
--
-- A UPC (stored in variants.barcode) identifies a specific scannable item, so it
-- must be unique across all variants. This enables a scanned/typed UPC to resolve
-- to exactly one variant (groundwork for the home-screen search / scan-to-find
-- feature). Uniqueness is required at the app layer too (the add-variant form
-- requires a UPC); this index makes it a hard guarantee.
--
-- Partial index (where barcode is not null) so legacy variants without a UPC are
-- unaffected.
-- =============================================================================

create unique index if not exists uq_variants_barcode
  on variants (barcode)
  where barcode is not null;

-- >>> supabase/migrations/0011_fix_attribute_flags.sql
-- =============================================================================
-- 0011_fix_attribute_flags.sql — repair attribute_defs to the canonical set
--
-- Symptom this fixes: every variant shows "Default" and the add-item form shows
-- no dimension fields — because the live attribute_defs are missing the
-- is_variant_dimension flags (0008's seed used ON CONFLICT DO NOTHING, so if
-- rows already existed with wrong flags they were never corrected).
--
-- This re-asserts the canonical tennis attribute definitions with an UPSERT that
-- UPDATES existing rows (unlike the original DO NOTHING). Idempotent and safe to
-- run on a correct database (it's a no-op there).
--
-- NOTE: this overwrites attribute_defs to the standard set. If you've customized
-- attribute definitions by hand, review before running.
-- =============================================================================

insert into attribute_defs (category_id, name, value_type, unit, required, is_variant_dimension, enum_values, sort_order)
select c.id, a.name, a.value_type, a.unit, a.required, a.is_variant, a.enum_values, a.sort_order
from categories c
join (values
  -- Rackets
  ('Rackets','grip_size','enum',   null, true,  true,  '["4 1/8","4 1/4","4 3/8","4 1/2","4 5/8"]'::jsonb, 1),
  ('Rackets','head_size','number', 'in²',false, false, null::jsonb, 2),
  ('Rackets','weight',   'number', 'g',  false, false, null::jsonb, 3),
  ('Rackets','string_pattern','text', null, false, false, null::jsonb, 4),
  -- Strings
  ('Strings','gauge','enum', null, false, true,  '["15","15L","16","16L","17","18"]'::jsonb, 1),
  ('Strings','color','text', null, false, true,  null::jsonb, 2),
  ('Strings','material','text', null, false, false, null::jsonb, 3),
  ('Strings','length','number','ft', false, false, null::jsonb, 4),
  -- Grips
  ('Grips','type','enum', null, false, true, '["overgrip","replacement"]'::jsonb, 1),
  ('Grips','color','text', null, false, true, null::jsonb, 2),
  -- Balls
  ('Balls','type','enum', null, false, true, '["regular duty","extra duty","high altitude"]'::jsonb, 1),
  ('Balls','pack_size','number','count', false, true, null::jsonb, 2),
  -- Shoes
  ('Shoes','size','text', null, true, true, null::jsonb, 1),
  ('Shoes','width','enum', null, false, true, '["narrow","standard","wide"]'::jsonb, 2),
  ('Shoes','color','text', null, false, true, null::jsonb, 3),
  ('Shoes','gender','enum', null, false, false, '["men","women","junior","unisex"]'::jsonb, 4),
  -- Apparel
  ('Apparel','size','enum', null, true, true, '["XS","S","M","L","XL","XXL"]'::jsonb, 1),
  ('Apparel','color','text', null, false, true, null::jsonb, 2),
  ('Apparel','gender','enum', null, false, false, '["men","women","junior","unisex"]'::jsonb, 3),
  -- Bags
  ('Bags','capacity','text', null, false, true, null::jsonb, 1),
  ('Bags','color','text', null, false, true, null::jsonb, 2),
  -- Accessories
  ('Accessories','type','text', null, false, false, null::jsonb, 1)
) as a(cat, name, value_type, unit, required, is_variant, enum_values, sort_order)
  on a.cat = c.name
on conflict (category_id, name) do update
  set value_type           = excluded.value_type,
      unit                 = excluded.unit,
      required             = excluded.required,
      is_variant_dimension = excluded.is_variant_dimension,
      enum_values          = excluded.enum_values,
      sort_order           = excluded.sort_order;

-- >>> supabase/migrations/0012_customers.sql
-- =============================================================================
-- 0012_customers.sql — customers + link sales to a customer (AceStock)
--
-- Lets a sale be recorded under a customer and builds purchase history
-- (customer → sales → sale_lines → variants → products). Walk-in sales leave
-- customer_id null.
--
-- NOT safe to re-run on a database with data: it drops and recreates the
-- customers table and sales.customer_id, deleting every customer and every
-- sale's customer link (code review #22). For a fresh database only.
-- =============================================================================

-- Reset (removes the column's FK dependency first). Destructive on live data.
alter table sales drop column if exists customer_id;
drop table if exists customers cascade;

create table customers (
  id            uuid primary key default gen_random_uuid(),
  first_name    text not null,
  last_name     text not null,
  phone_number  text,
  email         text,
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index idx_customers_last_first on customers (lower(last_name), lower(first_name));

create trigger trg_customers_updated_at
  before update on customers
  for each row execute function set_updated_at();

-- Link sales to an optional customer.
alter table sales
  add column customer_id uuid references customers (id);
create index idx_sales_customer on sales (customer_id);

-- -----------------------------------------------------------------------------
-- RLS + grants
-- -----------------------------------------------------------------------------
alter table customers enable row level security;
create policy customers_authenticated_all
  on customers for all to authenticated using (true) with check (true);
grant select, insert, update, delete on customers to authenticated;

-- -----------------------------------------------------------------------------
-- record_sale — accepts an optional customer_id. Atomic: sale header (+ customer)
-- + lines + one sell inventory_txn per line.
-- -----------------------------------------------------------------------------
drop function if exists record_sale(jsonb, text);
drop function if exists record_sale(jsonb, uuid, text);

create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_note        text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id   uuid := gen_random_uuid();
  v_line      jsonb;
  v_variant   uuid;
  v_qty       integer;
  v_price     numeric;
  v_subtotal  numeric := 0;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_variant := (v_line->>'variant_id')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_variant is null or not exists (select 1 from variants where id = v_variant) then
      raise exception 'Unknown variant_id % in sale line', v_variant;
    end if;
    if v_qty is null or v_qty <= 0 then
      raise exception 'Sale line quantity must be positive';
    end if;
    if v_price is null or v_price < 0 then
      raise exception 'Sale line price must be >= 0';
    end if;

    insert into sale_lines (sale_id, variant_id, qty, unit_price)
    values (v_sale_id, v_variant, v_qty, v_price);

    insert into inventory_txns (txn_type, variant_id, qty, sale_id)
    values ('sell', v_variant, -v_qty, v_sale_id);

    v_subtotal := v_subtotal + (v_qty * v_price);
  end loop;

  update sales set subtotal = v_subtotal where id = v_sale_id;
  return v_sale_id;
end;
$$;

grant execute on function record_sale(jsonb, uuid, text) to authenticated;

-- >>> supabase/migrations/0013_customer_rackets.sql
-- =============================================================================
-- 0013_customer_rackets.sql — rackets a customer owns (AceStock)
--
-- The physical rackets a customer owns. Each may optionally link to a catalog
-- racket (products) if it's a model the shop sells, or be free-form for a racket
-- bought elsewhere. This is the anchor for re-stringing history (a future
-- feature: each stringing event references a customer_racket).
-- =============================================================================

create table customer_rackets (
  id           uuid primary key default gen_random_uuid(),
  customer_id  uuid not null references customers (id) on delete cascade,
  product_id   uuid references products (id),   -- optional link to a catalog racket
  brand        text,
  model        text not null,                   -- racket name/model (identifies it)
  grip_size    text,
  label        text,                            -- nickname to tell multiple rackets apart
  notes        text,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index idx_customer_rackets_customer on customer_rackets (customer_id);
create index idx_customer_rackets_product on customer_rackets (product_id);

create trigger trg_customer_rackets_updated_at
  before update on customer_rackets
  for each row execute function set_updated_at();

-- RLS + grants
alter table customer_rackets enable row level security;
create policy customer_rackets_authenticated_all
  on customer_rackets for all to authenticated using (true) with check (true);
grant select, insert, update, delete on customer_rackets to authenticated;

-- >>> supabase/migrations/0014_racket_stringings.sql
-- =============================================================================
-- 0014_racket_stringings.sql — restringing events for a customer's racket
--
-- Records each time a customer's racket is strung: the string used (optionally a
-- catalog string variant so it can be deducted from stock), tension(s), price
-- charged, who strung it, and when. These rows are also the re-stringing history
-- (to be surfaced on the customer screen later).
-- =============================================================================

create table racket_stringings (
  id                 uuid primary key default gen_random_uuid(),
  customer_racket_id uuid not null references customer_rackets (id) on delete cascade,
  string_variant_id  uuid references variants (id),   -- optional: catalog string used
  string_label       text,                            -- string name (denormalized / free-form)
  tension_main       numeric(5, 1) check (tension_main > 0),
  tension_cross      numeric(5, 1) check (tension_cross > 0),   -- for hybrids / different cross
  price              numeric(12, 2) check (price >= 0),
  strung_by          text,
  strung_at          timestamptz not null default now(),
  notes              text,
  created_at         timestamptz not null default now()
);
create index idx_racket_stringings_racket on racket_stringings (customer_racket_id);
create index idx_racket_stringings_variant on racket_stringings (string_variant_id);

-- RLS + grants
alter table racket_stringings enable row level security;
create policy racket_stringings_authenticated_all
  on racket_stringings for all to authenticated using (true) with check (true);
grant select, insert, update, delete on racket_stringings to authenticated;

-- -----------------------------------------------------------------------------
-- record_stringing — record a restring; if p_deduct_stock and a catalog string
-- variant is given, atomically post an adjust -1 inventory_txn (one set used).
-- Returns the new stringing id.
-- -----------------------------------------------------------------------------
create or replace function record_stringing(
  p_customer_racket_id uuid,
  p_string_variant_id  uuid,
  p_string_label       text,
  p_tension_main       numeric,
  p_tension_cross      numeric,
  p_price              numeric,
  p_strung_by          text,
  p_deduct_stock       boolean,
  p_notes              text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_id uuid := gen_random_uuid();
begin
  if not exists (select 1 from customer_rackets where id = p_customer_racket_id) then
    raise exception 'Unknown customer_racket_id %', p_customer_racket_id;
  end if;

  insert into racket_stringings (
    id, customer_racket_id, string_variant_id, string_label,
    tension_main, tension_cross, price, strung_by, notes
  )
  values (
    v_id, p_customer_racket_id, p_string_variant_id, nullif(trim(p_string_label), ''),
    p_tension_main, p_tension_cross, p_price, nullif(trim(p_strung_by), ''),
    nullif(trim(p_notes), '')
  );

  -- Optionally consume one set of the chosen catalog string from stock.
  if coalesce(p_deduct_stock, false) and p_string_variant_id is not null then
    if not exists (select 1 from variants where id = p_string_variant_id) then
      raise exception 'Unknown string_variant_id %', p_string_variant_id;
    end if;
    insert into inventory_txns (txn_type, variant_id, qty, note)
    values ('adjust', p_string_variant_id, -1, 'restring');
  end if;

  return v_id;
end;
$$;

grant execute on function
  record_stringing(uuid, uuid, text, numeric, numeric, numeric, text, boolean, text)
  to authenticated;

-- >>> supabase/migrations/0015_string_jobs.sql
-- =============================================================================
-- 0015_string_jobs.sql — string jobs with mains/crosses + lifecycle (AceStock)
--
-- Replaces the simpler racket_stringings (0014) with a string_jobs record that
-- captures the mains and crosses separately (brand, string, color, gauge,
-- tension each) and a lifecycle: entered → complete → delivered. A job becomes
-- part of a racket's re-stringing history once delivered.
--
-- NOT safe to re-run on a database with data: it drops and recreates
-- string_jobs, deleting every string job (code review #22). For a fresh
-- database only.
-- =============================================================================

drop function if exists record_stringing(uuid, uuid, text, numeric, numeric, numeric, text, boolean, text);
drop function if exists advance_string_job(uuid, text);
drop table if exists racket_stringings cascade;
drop table if exists string_jobs cascade;

create table string_jobs (
  id                 uuid primary key default gen_random_uuid(),
  customer_racket_id uuid not null references customer_rackets (id) on delete cascade,
  status             text not null default 'entered'
                       check (status in ('entered', 'complete', 'delivered')),

  -- Mains
  main_variant_id    uuid references variants (id),   -- optional catalog string
  main_brand         text,
  main_string        text,
  main_color         text,
  main_gauge         text,
  main_tension       numeric(5, 1) check (main_tension > 0),

  -- Crosses (may differ from mains for a hybrid)
  cross_variant_id   uuid references variants (id),
  cross_brand        text,
  cross_string       text,
  cross_color        text,
  cross_gauge        text,
  cross_tension      numeric(5, 1) check (cross_tension > 0),

  price              numeric(12, 2) check (price >= 0),
  strung_by          text,
  notes              text,

  entered_at         timestamptz not null default now(),
  completed_at       timestamptz,
  delivered_at       timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index idx_string_jobs_racket on string_jobs (customer_racket_id);
create index idx_string_jobs_status on string_jobs (status);

create trigger trg_string_jobs_updated_at
  before update on string_jobs
  for each row execute function set_updated_at();

-- RLS + grants
alter table string_jobs enable row level security;
create policy string_jobs_authenticated_all
  on string_jobs for all to authenticated using (true) with check (true);
grant select, insert, update, delete on string_jobs to authenticated;

-- -----------------------------------------------------------------------------
-- advance_string_job — move a job exactly one step forward
--   (entered → complete → delivered) and stamp the corresponding timestamp.
--   Returns the new status.
-- -----------------------------------------------------------------------------
create or replace function advance_string_job(
  p_job_id        uuid,
  p_target_status text
)
returns text
language plpgsql
security invoker
as $$
declare
  v_current text;
  v_rank    integer;
  v_target  integer;
begin
  select status into v_current from string_jobs where id = p_job_id;
  if v_current is null then
    raise exception 'Unknown string job %', p_job_id;
  end if;

  v_rank   := case v_current       when 'entered' then 0 when 'complete' then 1 when 'delivered' then 2 else -1 end;
  v_target := case p_target_status when 'entered' then 0 when 'complete' then 1 when 'delivered' then 2 else -1 end;

  if v_target < 0 then
    raise exception 'Invalid status "%"', p_target_status;
  end if;
  if v_target <> v_rank + 1 then
    raise exception 'Cannot move a string job from "%" to "%"', v_current, p_target_status;
  end if;

  update string_jobs
    set status       = p_target_status,
        completed_at = case when p_target_status = 'complete'  then now() else completed_at end,
        delivered_at = case when p_target_status = 'delivered' then now() else delivered_at end
  where id = p_job_id;

  return p_target_status;
end;
$$;

grant execute on function advance_string_job(uuid, text) to authenticated;

-- >>> supabase/migrations/0016_string_job_specs.sql
-- =============================================================================
-- 0016_string_job_specs.sql — generalize string-job dimensions (AceStock)
--
-- The mains/crosses gauge & color were fixed columns, but the Strings category's
-- variant dimensions can be named anything (custom attributes). Replace the
-- fixed gauge/color columns with main_specs / cross_specs JSONB that hold the
-- picked variant-dimension values keyed by their real attribute names
-- (e.g. {"gauge":"16","color":"Black"}). brand/string/tension/variant_id stay.
--
-- Re-runnable.
-- =============================================================================

alter table string_jobs
  drop column if exists main_gauge,
  drop column if exists main_color,
  drop column if exists cross_gauge,
  drop column if exists cross_color,
  add column if not exists main_specs  jsonb not null default '{}'::jsonb,
  add column if not exists cross_specs jsonb not null default '{}'::jsonb;

-- >>> supabase/migrations/0017_products_only.sql
-- =============================================================================
-- 0017_products_only.sql — collapse the variant layer (AceStock)
--
-- Simplifies the model: each PRODUCT is now the unique, sellable, stock-tracked
-- item under a category. The separate `variants` table is removed. Stock ledger,
-- sale lines, and string-job catalog links all point at products directly, and a
-- product's attributes JSONB holds every field (including what used to be
-- variant dimensions like gauge/color).
--
-- CLEAN CUTOVER: stock + sales history is wiped and rebuilt against products
-- (there was no real sales/stock data yet). NOT safe to re-run on a database
-- with data: it empties the sales and stock history (code review #22).
-- =============================================================================

-- 1. Drop variant-dependent RPCs (recreated below, keyed on product_id).
drop function if exists receive_stock(uuid, numeric, numeric, text, text);
drop function if exists adjust_stock(uuid, numeric, text);
drop function if exists record_sale(jsonb, text);

-- 2. Drop variant-dependent views.
drop view if exists product_stock;
drop view if exists variant_stock_detail;
drop view if exists variant_stock;

-- 3. Wipe stock + sales history (clean cutover; rebuilt against products).
truncate inventory_txns, sale_lines, sales cascade;

-- 4. Repoint the stock ledger at products.
drop index if exists idx_inventory_txns_variant;
alter table inventory_txns drop column if exists variant_id;
alter table inventory_txns
  add column if not exists product_id uuid not null references products (id);
create index if not exists idx_inventory_txns_product on inventory_txns (product_id);

-- 5. Repoint sale lines at products.
drop index if exists idx_sale_lines_variant;
alter table sale_lines drop column if exists variant_id;
alter table sale_lines
  add column if not exists product_id uuid not null references products (id);
create index if not exists idx_sale_lines_product on sale_lines (product_id);

-- 6. Repoint string-job catalog links at products.
alter table string_jobs drop column if exists main_variant_id;
alter table string_jobs drop column if exists cross_variant_id;
alter table string_jobs
  add column if not exists main_product_id  uuid references products (id),
  add column if not exists cross_product_id uuid references products (id);

-- 7. Drop the variants table itself.
drop table if exists variants cascade;

-- 8. Attributes are all plain product fields now — the variant-dimension flag is
--    obsolete.
alter table attribute_defs drop column if exists is_variant_dimension;

-- 9. A UPC now identifies a product (was per-variant). Enforce uniqueness here.
create unique index if not exists uq_products_barcode
  on products (barcode)
  where barcode is not null;

-- 10. Per-product stock view: on-hand from the ledger + a low-stock flag against
--     the product's own reorder point.
create or replace view product_stock as
select
  p.id                                      as product_id,
  coalesce(sum(t.qty), 0)::numeric          as on_hand,
  p.reorder_point                           as reorder_point,
  (
    p.reorder_point is not null
    and coalesce(sum(t.qty), 0) <= p.reorder_point
  )                                         as is_low
from products p
left join inventory_txns t on t.product_id = p.id
group by p.id, p.reorder_point;

grant select on product_stock to authenticated;

-- =============================================================================
-- 11. RPCs (product-keyed)
-- =============================================================================

-- receive_stock — post a positive receive txn for a product. Returns txn id.
create or replace function receive_stock(
  p_product_id uuid,
  p_qty        numeric,
  p_unit_cost  numeric,
  p_location   text,
  p_note       text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_id uuid := gen_random_uuid();
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'Receive quantity must be positive';
  end if;
  if not exists (select 1 from products where id = p_product_id) then
    raise exception 'Unknown product_id %', p_product_id;
  end if;
  insert into inventory_txns (id, txn_type, product_id, qty, unit_cost, location, note)
  values (v_id, 'receive', p_product_id, p_qty, p_unit_cost, nullif(trim(p_location),''), nullif(trim(p_note),''));
  return v_id;
end;
$$;
grant execute on function receive_stock(uuid, numeric, numeric, text, text) to authenticated;

-- adjust_stock — post a signed adjustment (shrinkage, count correction).
create or replace function adjust_stock(
  p_product_id uuid,
  p_qty        numeric,
  p_note       text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_id uuid := gen_random_uuid();
begin
  if p_qty is null or p_qty = 0 then
    raise exception 'Adjustment quantity must be non-zero';
  end if;
  if not exists (select 1 from products where id = p_product_id) then
    raise exception 'Unknown product_id %', p_product_id;
  end if;
  insert into inventory_txns (id, txn_type, product_id, qty, note)
  values (v_id, 'adjust', p_product_id, p_qty, nullif(trim(p_note),''));
  return v_id;
end;
$$;
grant execute on function adjust_stock(uuid, numeric, text) to authenticated;

-- record_sale — atomic POS write: a sale header + its lines + one negative
-- 'sell' inventory_txn per line. Input lines: [{product_id, qty, unit_price}].
create or replace function record_sale(
  p_lines jsonb,
  p_note  text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id   uuid := gen_random_uuid();
  v_line      jsonb;
  v_product   uuid;
  v_qty       integer;
  v_price     numeric;
  v_subtotal  numeric := 0;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;

  insert into sales (id, subtotal, note) values (v_sale_id, 0, nullif(trim(p_note),''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_product := (v_line->>'product_id')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_product is null or not exists (select 1 from products where id = v_product) then
      raise exception 'Unknown product_id % in sale line', v_product;
    end if;
    if v_qty is null or v_qty <= 0 then
      raise exception 'Sale line quantity must be positive';
    end if;
    if v_price is null or v_price < 0 then
      raise exception 'Sale line price must be >= 0';
    end if;

    insert into sale_lines (sale_id, product_id, qty, unit_price)
    values (v_sale_id, v_product, v_qty, v_price);

    insert into inventory_txns (txn_type, product_id, qty, sale_id)
    values ('sell', v_product, -v_qty, v_sale_id);

    v_subtotal := v_subtotal + (v_qty * v_price);
  end loop;

  update sales set subtotal = v_subtotal where id = v_sale_id;
  return v_sale_id;
end;
$$;
grant execute on function record_sale(jsonb, text) to authenticated;

-- >>> supabase/migrations/0018_customer_racket_barcode.sql
-- =============================================================================
-- 0018_customer_racket_barcode.sql — barcode on customer rackets (AceStock)
--
-- Each customer racket now carries a scannable barcode instead of a free-text
-- nickname. Rename the old `label` column to `barcode` and make it uniquely
-- searchable so a scan resolves to exactly one racket (used by the home-screen
-- scan-to-find, which jumps straight into a new string job for that racket).
--
-- Re-runnable.
-- =============================================================================

do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_name = 'customer_rackets' and column_name = 'label'
  ) and not exists (
    select 1 from information_schema.columns
    where table_name = 'customer_rackets' and column_name = 'barcode'
  ) then
    alter table customer_rackets rename column label to barcode;
  end if;
end $$;

-- A scanned barcode must resolve to one racket (partial: rackets without a
-- barcode are unaffected).
create unique index if not exists uq_customer_rackets_barcode
  on customer_rackets (barcode)
  where barcode is not null;

-- >>> supabase/migrations/0019_string_commit.sql
-- =============================================================================
-- 0019_string_commit.sql — reserve/consume string stock for jobs (AceStock)
--
-- A string job reserves the string(s) it uses the moment it's entered, so other
-- jobs see it as unavailable ("set aside"). Nothing physically leaves inventory
-- until the job is marked complete, at which point the string is consumed.
--
--   committed(product)  = 1 per distinct catalog string on each *entered* job
--   available(product)  = on_hand − committed
--   complete a job      → post a 'consume' ledger txn (−1) per distinct string
--
-- Committed is derived from job status, so deleting an entered job releases its
-- reservation automatically. Re-runnable.
-- =============================================================================

-- 1. Allow a 'consume' inventory txn (string physically used on completion).
alter table inventory_txns drop constraint if exists inventory_txns_txn_type_check;
alter table inventory_txns
  add constraint inventory_txns_txn_type_check
  check (txn_type in ('receive', 'adjust', 'sell', 'transfer', 'consume'));

-- 2. Committed units per product: one per distinct catalog string on each job
--    that is still in the 'entered' state (union de-dups a single-string job
--    whose mains and crosses are the same product).
create or replace view string_committed as
select product_id, count(*)::int as committed
from (
  select id as job_id, main_product_id as product_id
    from string_jobs where status = 'entered' and main_product_id is not null
  union
  select id as job_id, cross_product_id as product_id
    from string_jobs where status = 'entered' and cross_product_id is not null
) x
group by product_id;

-- 3. Availability per product: on-hand minus committed.
create or replace view product_available as
select
  ps.product_id,
  ps.on_hand,
  coalesce(sc.committed, 0)              as committed,
  ps.on_hand - coalesce(sc.committed, 0) as available
from product_stock ps
left join string_committed sc on sc.product_id = ps.product_id;

grant select on string_committed to authenticated;
grant select on product_available to authenticated;

-- 4. On entered → complete, consume one unit of each distinct catalog string.
create or replace function advance_string_job(
  p_job_id        uuid,
  p_target_status text
)
returns text
language plpgsql
security invoker
as $$
declare
  v_current text;
  v_rank    integer;
  v_target  integer;
  v_main    uuid;
  v_cross   uuid;
begin
  select status, main_product_id, cross_product_id
    into v_current, v_main, v_cross
    from string_jobs where id = p_job_id;
  if v_current is null then
    raise exception 'Unknown string job %', p_job_id;
  end if;

  v_rank   := case v_current       when 'entered' then 0 when 'complete' then 1 when 'delivered' then 2 else -1 end;
  v_target := case p_target_status when 'entered' then 0 when 'complete' then 1 when 'delivered' then 2 else -1 end;

  if v_target < 0 then
    raise exception 'Invalid status "%"', p_target_status;
  end if;
  if v_target <> v_rank + 1 then
    raise exception 'Cannot move a string job from "%" to "%"', v_current, p_target_status;
  end if;

  update string_jobs
    set status       = p_target_status,
        completed_at = case when p_target_status = 'complete'  then now() else completed_at end,
        delivered_at = case when p_target_status = 'delivered' then now() else delivered_at end
  where id = p_job_id;

  -- Consume one unit of each distinct catalog string the job used.
  if p_target_status = 'complete' then
    insert into inventory_txns (txn_type, product_id, qty, note)
    select 'consume', pid, -1, 'String job completed'
    from (
      select distinct pid
      from (values (v_main), (v_cross)) as t(pid)
      where pid is not null
    ) d;
  end if;

  return p_target_status;
end;
$$;
grant execute on function advance_string_job(uuid, text) to authenticated;

-- >>> supabase/migrations/0020_string_job_cancel.sql
-- =============================================================================
-- 0020_string_job_cancel.sql — cancel a string job (AceStock)
--
-- Adds a 'cancelled' state so an entered job can be voided (e.g. the customer
-- changes their mind before it's strung). Cancelling releases the job's stock
-- reservation automatically, since committed stock is derived from jobs still in
-- the 'entered' state. Only an entered job may be cancelled — once it's strung
-- (complete) the string has been consumed.
--
-- Re-runnable.
-- =============================================================================

alter table string_jobs drop constraint if exists string_jobs_status_check;
alter table string_jobs
  add constraint string_jobs_status_check
  check (status in ('entered', 'complete', 'delivered', 'cancelled'));

create or replace function cancel_string_job(p_job_id uuid)
returns text
language plpgsql
security invoker
as $$
declare
  v_current text;
begin
  select status into v_current from string_jobs where id = p_job_id;
  if v_current is null then
    raise exception 'Unknown string job %', p_job_id;
  end if;
  if v_current <> 'entered' then
    raise exception 'Only an entered job can be cancelled (this one is "%")', v_current;
  end if;
  update string_jobs set status = 'cancelled' where id = p_job_id;
  return 'cancelled';
end;
$$;
grant execute on function cancel_string_job(uuid) to authenticated;

