      insert into gift_card_txns (gift_card_id, amount, reason, sale_id)
      values (v_gc, v_qty * v_price, 'load', v_sale_id);
    end if;

    v_subtotal := v_subtotal + (v_qty * v_price);
  end loop;

  -- Payments (split tender)
  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;

      if v_amount is null or v_amount <= 0 then
        raise exception 'Payment amount must be positive';
      end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then
        raise exception 'Invalid payment method "%"', v_method;
      end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card payment needs a gift_card_id'; end if;
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal < v_amount then
          raise exception 'Gift card balance % is less than %', v_bal, v_amount;
        end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id)
        values (v_gc, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount, gift_card_id)
        values (v_sale_id, 'gift_card', v_amount, v_gc);
      elsif v_method = 'store_credit' then
        if p_customer_id is null then raise exception 'Store credit needs a customer on the sale'; end if;
        select coalesce(sum(amount), 0) into v_bal from store_credit_txns where customer_id = p_customer_id;
        if v_bal < v_amount then
          raise exception 'Store credit balance % is less than %', v_bal, v_amount;
        end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id)
        values (p_customer_id, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount)
        values (v_sale_id, 'store_credit', v_amount);
      else
        insert into sale_payments (sale_id, method, amount)
        values (v_sale_id, v_method, v_amount);
      end if;

      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - v_subtotal) > 0.005 then
    raise exception 'Payments (%) must equal the sale total (%)', v_paid, v_subtotal;
  end if;

  select count(*) into v_count from sale_payments where sale_id = v_sale_id;
  update sales
      set subtotal = v_subtotal,
          payment_method = case
            when v_count = 0 then null
            when v_count = 1 then (select method from sale_payments where sale_id = v_sale_id limit 1)
            else 'split'
          end
    where id = v_sale_id;

  return v_sale_id;
end;
$$;
grant execute on function record_sale(jsonb, uuid, jsonb, text) to authenticated;

-- >>> supabase/migrations/0025_gift_card_ownership.sql
-- =============================================================================
-- 0025_gift_card_ownership.sql — gift card ownership follows the balance
--
-- A gift card is only "owned" by a customer while it holds value:
--   • redeeming a card to $0 clears its customer (it becomes anonymous)
--   • loading value onto an EMPTY card (re)assigns it to that sale's customer
--     (null when sold to an unidentified customer)
-- A card with an existing balance keeps its owner when topped up.
--
-- Only record_sale changes. Re-runnable.
-- =============================================================================

create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_payments    jsonb,
  p_note        text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id   uuid := gen_random_uuid();
  v_line      jsonb;
  v_pay       jsonb;
  v_product   uuid;
  v_job       uuid;
  v_gc        uuid;
  v_qty       integer;
  v_price     numeric;
  v_subtotal  numeric := 0;
  v_paid      numeric := 0;
  v_method    text;
  v_amount    numeric;
  v_bal       numeric;
  v_prev      numeric;
  v_count     integer;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  -- Lines
  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_product := nullif(v_line->>'product_id', '')::uuid;
    v_job     := nullif(v_line->>'string_job_id', '')::uuid;
    v_gc      := nullif(v_line->>'gift_card_id', '')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_qty is null or v_qty <= 0 then
      raise exception 'Sale line quantity must be positive';
    end if;
    if v_price is null or v_price < 0 then
      raise exception 'Sale line price must be >= 0';
    end if;
    if (case when v_product is null then 0 else 1 end)
     + (case when v_job is null then 0 else 1 end)
     + (case when v_gc is null then 0 else 1 end) <> 1 then
      raise exception 'A sale line must reference exactly one of product, string job, or gift card';
    end if;

    if v_product is not null then
      if not exists (select 1 from products where id = v_product) then
        raise exception 'Unknown product_id % in sale line', v_product;
      end if;
      insert into sale_lines (sale_id, product_id, qty, unit_price)
      values (v_sale_id, v_product, v_qty, v_price);
      insert into inventory_txns (txn_type, product_id, qty, sale_id)
      values ('sell', v_product, -v_qty, v_sale_id);
    elsif v_job is not null then
      if not exists (select 1 from string_jobs where id = v_job) then
        raise exception 'Unknown string_job_id % in sale line', v_job;
      end if;
      insert into sale_lines (sale_id, string_job_id, qty, unit_price)
      values (v_sale_id, v_job, v_qty, v_price);
      update string_jobs set paid_sale_id = v_sale_id where id = v_job;
    else
      if not exists (select 1 from gift_cards where id = v_gc) then
        raise exception 'Unknown gift_card_id % in sale line', v_gc;
      end if;
      -- Balance before this load decides whether ownership is (re)assigned.
      select coalesce(sum(amount), 0) into v_prev from gift_card_txns where gift_card_id = v_gc;
      insert into sale_lines (sale_id, gift_card_id, qty, unit_price)
      values (v_sale_id, v_gc, v_qty, v_price);
      insert into gift_card_txns (gift_card_id, amount, reason, sale_id)
      values (v_gc, v_qty * v_price, 'load', v_sale_id);
      -- Loading an empty card assigns it to this sale's customer (null = anon).
      if v_prev <= 0 then
        update gift_cards set customer_id = p_customer_id where id = v_gc;
      end if;
    end if;

    v_subtotal := v_subtotal + (v_qty * v_price);
  end loop;

  -- Payments (split tender)
  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;

      if v_amount is null or v_amount <= 0 then
        raise exception 'Payment amount must be positive';
      end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then
        raise exception 'Invalid payment method "%"', v_method;
      end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card payment needs a gift_card_id'; end if;
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal < v_amount then
          raise exception 'Gift card balance % is less than %', v_bal, v_amount;
        end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id)
        values (v_gc, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount, gift_card_id)
        values (v_sale_id, 'gift_card', v_amount, v_gc);
        -- Fully-redeemed card is no longer owned by anyone.
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal <= 0 then
          update gift_cards set customer_id = null where id = v_gc;
        end if;
      elsif v_method = 'store_credit' then
        if p_customer_id is null then raise exception 'Store credit needs a customer on the sale'; end if;
        select coalesce(sum(amount), 0) into v_bal from store_credit_txns where customer_id = p_customer_id;
        if v_bal < v_amount then
          raise exception 'Store credit balance % is less than %', v_bal, v_amount;
        end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id)
        values (p_customer_id, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount)
        values (v_sale_id, 'store_credit', v_amount);
      else
        insert into sale_payments (sale_id, method, amount)
        values (v_sale_id, v_method, v_amount);
      end if;

      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - v_subtotal) > 0.005 then
    raise exception 'Payments (%) must equal the sale total (%)', v_paid, v_subtotal;
  end if;

  select count(*) into v_count from sale_payments where sale_id = v_sale_id;
  update sales
     set subtotal = v_subtotal,
         payment_method = case
           when v_count = 0 then null
           when v_count = 1 then (select method from sale_payments where sale_id = v_sale_id limit 1)
           else 'split'
         end
   where id = v_sale_id;

  return v_sale_id;
end;
$$;
grant execute on function record_sale(jsonb, uuid, jsonb, text) to authenticated;

-- >>> supabase/migrations/0026_gift_card_adjust.sql
-- =============================================================================
-- 0026_gift_card_adjust.sql — manual gift card balance adjustment (AceStock)
--
-- Correct a card's balance without a sale: a signed ledger entry with a reason
-- (e.g. mistaken load, goodwill, zero-out). Cannot push the balance negative;
-- if the adjustment empties the card, its owner is cleared (consistent with
-- redemption). Re-runnable.
-- =============================================================================

create or replace function adjust_gift_card(p_gift_card_id uuid, p_amount numeric, p_reason text)
returns numeric
language plpgsql
security invoker
as $$
declare
  v_bal numeric;
begin
  if p_amount is null or p_amount = 0 then
    raise exception 'Adjustment amount must be non-zero';
  end if;
  if not exists (select 1 from gift_cards where id = p_gift_card_id) then
    raise exception 'Unknown gift card %', p_gift_card_id;
  end if;

  select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = p_gift_card_id;
  if v_bal + p_amount < 0 then
    raise exception 'Adjustment would make the balance negative (balance %, adjustment %)', v_bal, p_amount;
  end if;

  insert into gift_card_txns (gift_card_id, amount, reason)
  values (p_gift_card_id, p_amount, coalesce(nullif(trim(p_reason), ''), 'adjust'));

  v_bal := v_bal + p_amount;
  if v_bal <= 0 then
    update gift_cards set customer_id = null where id = p_gift_card_id;
  end if;
  return v_bal;
end;
$$;
grant execute on function adjust_gift_card(uuid, numeric, text) to authenticated;

-- >>> supabase/migrations/0027_sales_summary.sql
-- =============================================================================
-- 0027_sales_summary.sql — sales report totals for a period (AceStock)
--
-- Aggregates sales in [p_from, p_to) into the figures shown on the sales report
-- screen. Refunds and check tenders are 0 for now (returns / check payments are
-- not yet implemented) but are surfaced so the report is complete.
--
-- Re-runnable.
-- =============================================================================

create or replace function sales_summary(p_from timestamptz, p_to timestamptz)
returns table (
  gross         numeric,
  refunds       numeric,
  net           numeric,
  card          numeric,
  cash          numeric,
  check_amt     numeric,
  store_credit  numeric,
  gift_card     numeric,
  num_customers integer,
  num_tickets   integer,
  num_items     integer
)
language sql
security invoker
as $$
  with s as (
    select id, subtotal, customer_id
    from sales
    where sold_at >= p_from and sold_at < p_to
  ),
  pay as (
    select sp.method, sp.amount
    from sale_payments sp
    join s on s.id = sp.sale_id
  )
  select
    coalesce((select sum(subtotal) from s), 0)                                             as gross,
    0::numeric                                                                             as refunds,
    coalesce((select sum(subtotal) from s), 0)                                             as net,
    coalesce((select sum(amount) from pay where method = 'credit'), 0)                     as card,
    coalesce((select sum(amount) from pay where method = 'cash'), 0)                       as cash,
    0::numeric                                                                             as check_amt,
    coalesce((select sum(amount) from pay where method = 'store_credit'), 0)               as store_credit,
    coalesce((select sum(amount) from pay where method = 'gift_card'), 0)                  as gift_card,
    (select count(distinct customer_id) from s where customer_id is not null)::int         as num_customers,
    (select count(*) from s)::int                                                          as num_tickets,
    coalesce((select sum(sl.qty) from sale_lines sl join s on s.id = sl.sale_id
              where sl.product_id is not null), 0)::int                                    as num_items;
$$;
grant execute on function sales_summary(timestamptz, timestamptz) to authenticated;

-- >>> supabase/migrations/0028_profiles_roles.sql
-- =============================================================================
-- 0028_profiles_roles.sql — account roles (admin / staff) (AceStock)
--
-- Each auth user gets a profile with a role. Admins reach admin-only screens
-- (Categories, Settings, user management); staff run the register and service
-- flows. Access is gated in the UI; roles are managed in-app by admins via
-- set_user_role (which is admin-guarded so staff can't self-promote).
--
-- Re-runnable.
-- =============================================================================

create table if not exists profiles (
  id         uuid primary key references auth.users (id) on delete cascade,
  email      text,
  role       text not null default 'staff' check (role in ('admin', 'staff')),
  created_at timestamptz not null default now()
);

alter table profiles enable row level security;
drop policy if exists profiles_authenticated_select on profiles;
create policy profiles_authenticated_select on profiles for select to authenticated using (true);
grant select on profiles to authenticated;

-- Create a profile automatically when an auth user is created.
create or replace function handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, email)
  values (new.id, new.email)
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists trg_auth_user_created on auth.users;
create trigger trg_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_user();

-- Backfill profiles for any users that already exist.
insert into profiles (id, email)
select id, email from auth.users
on conflict (id) do nothing;

-- is_admin — is the current user an admin? SECURITY DEFINER so it reads profiles
-- regardless of RLS (and avoids recursive policy evaluation).
create or replace function is_admin()
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select exists (select 1 from profiles where id = auth.uid() and role = 'admin');
$$;
grant execute on function is_admin() to authenticated;

-- set_user_role — admin-only role change, guarded so the last admin can't be
-- demoted (which would lock everyone out of admin screens).
create or replace function set_user_role(p_user_id uuid, p_role text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not is_admin() then
    raise exception 'Only an admin can change roles';
  end if;
  if p_role not in ('admin', 'staff') then
    raise exception 'Invalid role "%"', p_role;
  end if;
  if not exists (select 1 from profiles where id = p_user_id) then
    raise exception 'Unknown user %', p_user_id;
  end if;
  if p_role = 'staff'
     and exists (select 1 from profiles where id = p_user_id and role = 'admin')
     and (select count(*) from profiles where role = 'admin') <= 1 then
    raise exception 'Cannot demote the last admin';
  end if;
  update profiles set role = p_role where id = p_user_id;
end;
$$;
grant execute on function set_user_role(uuid, text) to authenticated;

-- >>> supabase/migrations/0029_settings.sql
-- =============================================================================
-- 0029_settings.sql — shop settings: tax, stringing labor, inventory, reports
--
-- A single-row settings table drives checkout tax, the stringing base labor
-- charge, inventory defaults/oversell, and the report week start. record_sale
-- now charges tax on taxable lines (products always; stringing optionally; gift
-- card loads never) and can block selling below zero stock.
--
-- Re-runnable.
-- =============================================================================

create table if not exists settings (
  id                    boolean primary key default true check (id),
  tax_rate              numeric(6, 3) not null default 0,     -- percent, e.g. 8.25
  tax_stringing         boolean not null default false,       -- is stringing labor/service taxed?
  stringing_labor       numeric(12, 2) not null default 0,    -- base labor added to string price
  default_reorder_point integer,                              -- prefill for new products (null = none)
  block_oversell        boolean not null default false,       -- refuse selling below 0 on hand
  week_starts_monday    boolean not null default false,       -- report "week to date" boundary
  updated_at            timestamptz not null default now()
);
insert into settings (id) values (true) on conflict (id) do nothing;

alter table settings enable row level security;
drop policy if exists settings_authenticated_select on settings;
drop policy if exists settings_authenticated_update on settings;
create policy settings_authenticated_select on settings for select to authenticated using (true);
create policy settings_authenticated_update on settings for update to authenticated using (true) with check (true);
grant select, update on settings to authenticated;

-- Sale tax amount (total charged = subtotal + tax).
alter table sales add column if not exists tax numeric(12, 2) not null default 0;

-- ----------------------------------------------------------------------------
-- record_sale — now applies tax and (optionally) blocks overselling.
-- ----------------------------------------------------------------------------
create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_payments    jsonb,
  p_note        text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id     uuid := gen_random_uuid();
  v_line        jsonb;
  v_pay         jsonb;
  v_product     uuid;
  v_job         uuid;
  v_gc          uuid;
  v_qty         integer;
  v_price       numeric;
  v_line_total  numeric;
  v_subtotal    numeric := 0;
  v_taxable     numeric := 0;
  v_paid        numeric := 0;
  v_method      text;
  v_amount      numeric;
  v_bal         numeric;
  v_prev        numeric;
  v_onhand      numeric;
  v_count       integer;
  v_rate        numeric := 0;
  v_tax_string  boolean := false;
  v_block       boolean := false;
  v_tax         numeric := 0;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  select tax_rate, tax_stringing, block_oversell
    into v_rate, v_tax_string, v_block
    from settings where id = true;
  v_rate := coalesce(v_rate, 0);

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  -- Lines
  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_product := nullif(v_line->>'product_id', '')::uuid;
    v_job     := nullif(v_line->>'string_job_id', '')::uuid;
    v_gc      := nullif(v_line->>'gift_card_id', '')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_qty is null or v_qty <= 0 then
      raise exception 'Sale line quantity must be positive';
    end if;
    if v_price is null or v_price < 0 then
      raise exception 'Sale line price must be >= 0';
    end if;
    if (case when v_product is null then 0 else 1 end)
     + (case when v_job is null then 0 else 1 end)
     + (case when v_gc is null then 0 else 1 end) <> 1 then
      raise exception 'A sale line must reference exactly one of product, string job, or gift card';
    end if;

    v_line_total := v_qty * v_price;

    if v_product is not null then
      if not exists (select 1 from products where id = v_product) then
        raise exception 'Unknown product_id % in sale line', v_product;
      end if;
      if v_block then
        select coalesce(sum(qty), 0) into v_onhand from inventory_txns where product_id = v_product;
        if v_onhand < v_qty then
          raise exception 'Not enough stock for product % (% on hand, % requested)', v_product, v_onhand, v_qty;
        end if;
      end if;
      insert into sale_lines (sale_id, product_id, qty, unit_price)
      values (v_sale_id, v_product, v_qty, v_price);
      insert into inventory_txns (txn_type, product_id, qty, sale_id)
      values ('sell', v_product, -v_qty, v_sale_id);
      v_taxable := v_taxable + v_line_total;              -- products are taxable
    elsif v_job is not null then
      if not exists (select 1 from string_jobs where id = v_job) then
        raise exception 'Unknown string_job_id % in sale line', v_job;
      end if;
      insert into sale_lines (sale_id, string_job_id, qty, unit_price)
      values (v_sale_id, v_job, v_qty, v_price);
      update string_jobs set paid_sale_id = v_sale_id where id = v_job;
      if v_tax_string then v_taxable := v_taxable + v_line_total; end if;
    else
      if not exists (select 1 from gift_cards where id = v_gc) then
        raise exception 'Unknown gift_card_id % in sale line', v_gc;
      end if;
      select coalesce(sum(amount), 0) into v_prev from gift_card_txns where gift_card_id = v_gc;
      insert into sale_lines (sale_id, gift_card_id, qty, unit_price)
      values (v_sale_id, v_gc, v_qty, v_price);
      insert into gift_card_txns (gift_card_id, amount, reason, sale_id)
      values (v_gc, v_line_total, 'load', v_sale_id);
      if v_prev <= 0 then
        update gift_cards set customer_id = p_customer_id where id = v_gc;
      end if;
      -- gift card loads are never taxed
    end if;

    v_subtotal := v_subtotal + v_line_total;
  end loop;

  v_tax := round(v_taxable * v_rate / 100.0, 2);

  -- Payments (split tender) must cover subtotal + tax.
  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;

      if v_amount is null or v_amount <= 0 then
        raise exception 'Payment amount must be positive';
      end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then
        raise exception 'Invalid payment method "%"', v_method;
      end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card payment needs a gift_card_id'; end if;
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal < v_amount then
          raise exception 'Gift card balance % is less than %', v_bal, v_amount;
        end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id)
        values (v_gc, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount, gift_card_id)
        values (v_sale_id, 'gift_card', v_amount, v_gc);
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal <= 0 then
          update gift_cards set customer_id = null where id = v_gc;
        end if;
      elsif v_method = 'store_credit' then
        if p_customer_id is null then raise exception 'Store credit needs a customer on the sale'; end if;
        select coalesce(sum(amount), 0) into v_bal from store_credit_txns where customer_id = p_customer_id;
        if v_bal < v_amount then
          raise exception 'Store credit balance % is less than %', v_bal, v_amount;
        end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id)
        values (p_customer_id, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount)
        values (v_sale_id, 'store_credit', v_amount);
      else
        insert into sale_payments (sale_id, method, amount)
        values (v_sale_id, v_method, v_amount);
      end if;

      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - (v_subtotal + v_tax)) > 0.005 then
    raise exception 'Payments (%) must equal the sale total (%)', v_paid, v_subtotal + v_tax;
  end if;

  select count(*) into v_count from sale_payments where sale_id = v_sale_id;
  update sales
     set subtotal = v_subtotal,
         tax = v_tax,
         payment_method = case
           when v_count = 0 then null
           when v_count = 1 then (select method from sale_payments where sale_id = v_sale_id limit 1)
           else 'split'
         end
   where id = v_sale_id;

  return v_sale_id;
end;
$$;
grant execute on function record_sale(jsonb, uuid, jsonb, text) to authenticated;

-- ----------------------------------------------------------------------------
-- sales_summary — include tax; net receipts = gross + tax − refunds.
-- ----------------------------------------------------------------------------
drop function if exists sales_summary(timestamptz, timestamptz);
create or replace function sales_summary(p_from timestamptz, p_to timestamptz)
returns table (
  gross         numeric,
  tax           numeric,
  refunds       numeric,
  net           numeric,
  card          numeric,
  cash          numeric,
  check_amt     numeric,
  store_credit  numeric,
  gift_card     numeric,
  num_customers integer,
  num_tickets   integer,
  num_items     integer
)
language sql
security invoker
as $$
  with s as (
    select id, subtotal, tax, customer_id
    from sales
    where sold_at >= p_from and sold_at < p_to
  ),
  pay as (
    select sp.method, sp.amount from sale_payments sp join s on s.id = sp.sale_id
  )
  select
    coalesce((select sum(subtotal) from s), 0)                                             as gross,
    coalesce((select sum(tax) from s), 0)                                                  as tax,
    0::numeric                                                                             as refunds,
    coalesce((select sum(subtotal) from s), 0) + coalesce((select sum(tax) from s), 0)     as net,
    coalesce((select sum(amount) from pay where method = 'credit'), 0)                     as card,
    coalesce((select sum(amount) from pay where method = 'cash'), 0)                       as cash,
    0::numeric                                                                             as check_amt,
    coalesce((select sum(amount) from pay where method = 'store_credit'), 0)               as store_credit,
    coalesce((select sum(amount) from pay where method = 'gift_card'), 0)                  as gift_card,
    (select count(distinct customer_id) from s where customer_id is not null)::int         as num_customers,
    (select count(*) from s)::int                                                          as num_tickets,
    coalesce((select sum(sl.qty) from sale_lines sl join s on s.id = sl.sale_id
              where sl.product_id is not null), 0)::int                                    as num_items;
$$;
grant execute on function sales_summary(timestamptz, timestamptz) to authenticated;

-- >>> supabase/migrations/0030_refunds.sql
-- =============================================================================
-- 0030_refunds.sql — returns, refunds, and voids (AceStock)
--
-- A refund reverses part or all of a sale: return chosen product lines (which
-- restock inventory) and give the money back via a tender — cash/credit, issued
-- store credit, or value loaded onto a gift card. A "void" is just a full refund
-- of everything to the original tenders. Refunds flow into the sales report so
-- net receipts reflect money actually kept.
--
-- v1 scope: only product lines are returnable (services / gift-card sales are
-- not). Re-runnable.
-- =============================================================================

-- Allow a 'return' inventory txn (returned stock goes back on hand).
alter table inventory_txns drop constraint if exists inventory_txns_txn_type_check;
alter table inventory_txns
  add constraint inventory_txns_txn_type_check
  check (txn_type in ('receive', 'adjust', 'sell', 'transfer', 'consume', 'return'));

-- Record the tax rate applied to a sale, so a later refund taxes returned lines
-- at the original rate regardless of settings changes.
alter table sales add column if not exists tax_rate numeric(6, 3) not null default 0;

-- ----------------------------------------------------------------------------
-- Refund tables
-- ----------------------------------------------------------------------------
create table if not exists refunds (
  id          uuid primary key default gen_random_uuid(),
  sale_id     uuid not null references sales (id),
  subtotal    numeric(12, 2) not null default 0,
  tax         numeric(12, 2) not null default 0,
  reason      text,
  note        text,
  refunded_at timestamptz not null default now(),
  created_at  timestamptz not null default now()
);
create index if not exists idx_refunds_sale on refunds (sale_id);

create table if not exists refund_lines (
  id           uuid primary key default gen_random_uuid(),
  refund_id    uuid not null references refunds (id) on delete cascade,
  sale_line_id uuid not null references sale_lines (id),
  qty          integer not null check (qty > 0),
  unit_price   numeric(12, 2) not null
);
create index if not exists idx_refund_lines_refund on refund_lines (refund_id);
create index if not exists idx_refund_lines_saleline on refund_lines (sale_line_id);

create table if not exists refund_payments (
  id           uuid primary key default gen_random_uuid(),
  refund_id    uuid not null references refunds (id) on delete cascade,
  method       text not null check (method in ('cash', 'credit', 'gift_card', 'store_credit')),
  amount       numeric(12, 2) not null check (amount > 0),
  gift_card_id uuid references gift_cards (id),
  created_at   timestamptz not null default now()
);
create index if not exists idx_refund_payments_refund on refund_payments (refund_id);

alter table refunds         enable row level security;
alter table refund_lines    enable row level security;
alter table refund_payments enable row level security;
do $$
declare tbl text;
begin
  foreach tbl in array array['refunds','refund_lines','refund_payments'] loop
    execute format('drop policy if exists %I on %I', tbl||'_authenticated_all', tbl);
    execute format('create policy %I on %I for all to authenticated using (true) with check (true)', tbl||'_authenticated_all', tbl);
  end loop;
end $$;
grant select, insert, update, delete on refunds, refund_lines, refund_payments to authenticated;

-- ----------------------------------------------------------------------------
-- record_sale — unchanged behavior, now also stores the applied tax_rate.
-- ----------------------------------------------------------------------------
create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_payments    jsonb,
  p_note        text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id     uuid := gen_random_uuid();
  v_line        jsonb;
  v_pay         jsonb;
  v_product     uuid;
  v_job         uuid;
  v_gc          uuid;
  v_qty         integer;
  v_price       numeric;
  v_line_total  numeric;
  v_subtotal    numeric := 0;
  v_taxable     numeric := 0;
  v_paid        numeric := 0;
  v_method      text;
  v_amount      numeric;
  v_bal         numeric;
  v_prev        numeric;
  v_onhand      numeric;
  v_count       integer;
  v_rate        numeric := 0;
  v_tax_string  boolean := false;
  v_block       boolean := false;
  v_tax         numeric := 0;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  select tax_rate, tax_stringing, block_oversell
    into v_rate, v_tax_string, v_block
    from settings where id = true;
  v_rate := coalesce(v_rate, 0);

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_product := nullif(v_line->>'product_id', '')::uuid;
    v_job     := nullif(v_line->>'string_job_id', '')::uuid;
    v_gc      := nullif(v_line->>'gift_card_id', '')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_qty is null or v_qty <= 0 then raise exception 'Sale line quantity must be positive'; end if;
    if v_price is null or v_price < 0 then raise exception 'Sale line price must be >= 0'; end if;
    if (case when v_product is null then 0 else 1 end)
     + (case when v_job is null then 0 else 1 end)
     + (case when v_gc is null then 0 else 1 end) <> 1 then
      raise exception 'A sale line must reference exactly one of product, string job, or gift card';
    end if;

    v_line_total := v_qty * v_price;

    if v_product is not null then
      if not exists (select 1 from products where id = v_product) then
        raise exception 'Unknown product_id % in sale line', v_product;
      end if;
      if v_block then
        select coalesce(sum(qty), 0) into v_onhand from inventory_txns where product_id = v_product;
        if v_onhand < v_qty then
          raise exception 'Not enough stock for product % (% on hand, % requested)', v_product, v_onhand, v_qty;
        end if;
      end if;
      insert into sale_lines (sale_id, product_id, qty, unit_price) values (v_sale_id, v_product, v_qty, v_price);
      insert into inventory_txns (txn_type, product_id, qty, sale_id) values ('sell', v_product, -v_qty, v_sale_id);
      v_taxable := v_taxable + v_line_total;
    elsif v_job is not null then
      if not exists (select 1 from string_jobs where id = v_job) then
        raise exception 'Unknown string_job_id % in sale line', v_job;
      end if;
      insert into sale_lines (sale_id, string_job_id, qty, unit_price) values (v_sale_id, v_job, v_qty, v_price);
      update string_jobs set paid_sale_id = v_sale_id where id = v_job;
      if v_tax_string then v_taxable := v_taxable + v_line_total; end if;
    else
      if not exists (select 1 from gift_cards where id = v_gc) then
        raise exception 'Unknown gift_card_id % in sale line', v_gc;
      end if;
      select coalesce(sum(amount), 0) into v_prev from gift_card_txns where gift_card_id = v_gc;
      insert into sale_lines (sale_id, gift_card_id, qty, unit_price) values (v_sale_id, v_gc, v_qty, v_price);
      insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_line_total, 'load', v_sale_id);
      if v_prev <= 0 then update gift_cards set customer_id = p_customer_id where id = v_gc; end if;
    end if;

    v_subtotal := v_subtotal + v_line_total;
  end loop;

  v_tax := round(v_taxable * v_rate / 100.0, 2);

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;
      if v_amount is null or v_amount <= 0 then raise exception 'Payment amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid payment method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card payment needs a gift_card_id'; end if;
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal < v_amount then raise exception 'Gift card balance % is less than %', v_bal, v_amount; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount, gift_card_id) values (v_sale_id, 'gift_card', v_amount, v_gc);
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal <= 0 then update gift_cards set customer_id = null where id = v_gc; end if;
      elsif v_method = 'store_credit' then
        if p_customer_id is null then raise exception 'Store credit needs a customer on the sale'; end if;
        select coalesce(sum(amount), 0) into v_bal from store_credit_txns where customer_id = p_customer_id;
        if v_bal < v_amount then raise exception 'Store credit balance % is less than %', v_bal, v_amount; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (p_customer_id, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, 'store_credit', v_amount);
      else
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, v_method, v_amount);
      end if;
      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - (v_subtotal + v_tax)) > 0.005 then
    raise exception 'Payments (%) must equal the sale total (%)', v_paid, v_subtotal + v_tax;
  end if;

  select count(*) into v_count from sale_payments where sale_id = v_sale_id;
  update sales
     set subtotal = v_subtotal,
         tax = v_tax,
         tax_rate = v_rate,
         payment_method = case
           when v_count = 0 then null
           when v_count = 1 then (select method from sale_payments where sale_id = v_sale_id limit 1)
           else 'split'
         end
   where id = v_sale_id;
  return v_sale_id;
end;
$$;
grant execute on function record_sale(jsonb, uuid, jsonb, text) to authenticated;

-- ----------------------------------------------------------------------------
-- record_refund — return product lines from a sale + give money back.
--   p_lines:    [{sale_line_id, qty}]  (product lines only)
--   p_payments: [{method, amount, gift_card_id?}]  summing to refund total
-- ----------------------------------------------------------------------------
create or replace function record_refund(
  p_sale_id  uuid,
  p_lines    jsonb,
  p_payments jsonb,
  p_reason   text,
  p_note     text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_refund_id uuid := gen_random_uuid();
  v_customer  uuid;
  v_rate      numeric := 0;
  v_line      jsonb;
  v_pay       jsonb;
  v_sl_id     uuid;
  v_qty       integer;
  v_sl        record;
  v_returned  integer;
  v_sub       numeric := 0;
  v_tax       numeric := 0;
  v_total     numeric := 0;
  v_paid      numeric := 0;
  v_method    text;
  v_amount    numeric;
  v_gc        uuid;
begin
  select customer_id, coalesce(tax_rate, 0) into v_customer, v_rate from sales where id = p_sale_id;
  if not found then raise exception 'Unknown sale %', p_sale_id; end if;
  if p_lines is null or jsonb_array_length(p_lines) = 0 then raise exception 'A refund needs at least one line'; end if;

  insert into refunds (id, sale_id, reason, note)
  values (v_refund_id, p_sale_id, nullif(trim(p_reason), ''), nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_sl_id := (v_line->>'sale_line_id')::uuid;
    v_qty   := (v_line->>'qty')::integer;
    if v_qty is null or v_qty <= 0 then raise exception 'Return quantity must be positive'; end if;

    select * into v_sl from sale_lines where id = v_sl_id and sale_id = p_sale_id;
    if not found then raise exception 'Line % is not part of sale %', v_sl_id, p_sale_id; end if;
    if v_sl.product_id is null then raise exception 'Only product lines can be returned'; end if;

    select coalesce(sum(rl.qty), 0) into v_returned from refund_lines rl where rl.sale_line_id = v_sl_id;
    if v_qty > v_sl.qty - v_returned then
      raise exception 'Cannot return % of line (only % remaining)', v_qty, v_sl.qty - v_returned;
    end if;

    insert into refund_lines (refund_id, sale_line_id, qty, unit_price)
    values (v_refund_id, v_sl_id, v_qty, v_sl.unit_price);
    -- Returned stock goes back on hand.
    insert into inventory_txns (txn_type, product_id, qty, sale_id)
    values ('return', v_sl.product_id, v_qty, p_sale_id);

    v_sub := v_sub + v_qty * v_sl.unit_price;
  end loop;

  v_tax   := round(v_sub * v_rate / 100.0, 2);
  v_total := v_sub + v_tax;
  update refunds set subtotal = v_sub, tax = v_tax where id = v_refund_id;

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;
      if v_amount is null or v_amount <= 0 then raise exception 'Refund amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid refund method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card refund needs a gift_card_id'; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_amount, 'refund', p_sale_id);
      elsif v_method = 'store_credit' then
        if v_customer is null then raise exception 'Store credit refund needs a customer on the sale'; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (v_customer, v_amount, 'refund', p_sale_id);
      end if;
      insert into refund_payments (refund_id, method, amount, gift_card_id) values (v_refund_id, v_method, v_amount, v_gc);
      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - v_total) > 0.005 then
    raise exception 'Refund payments (%) must equal the refund total (%)', v_paid, v_total;
  end if;

  return v_refund_id;
end;
$$;
grant execute on function record_refund(uuid, jsonb, jsonb, text, text) to authenticated;

-- ----------------------------------------------------------------------------
-- sales_summary — net refunds out of receipts and per-tender totals.
-- ----------------------------------------------------------------------------
create or replace function sales_summary(p_from timestamptz, p_to timestamptz)
returns table (
  gross         numeric,
  tax           numeric,
  refunds       numeric,
  net           numeric,
  card          numeric,
  cash          numeric,
  check_amt     numeric,
  store_credit  numeric,
  gift_card     numeric,
  num_customers integer,
  num_tickets   integer,
  num_items     integer
)
language sql
security invoker
as $$
  with s as (
    select id, subtotal, tax, customer_id from sales where sold_at >= p_from and sold_at < p_to
  ),
  pay as (select sp.method, sp.amount from sale_payments sp join s on s.id = sp.sale_id),
  r as (select id, subtotal, tax from refunds where refunded_at >= p_from and refunded_at < p_to),
  rpay as (select rp.method, rp.amount from refund_payments rp join r on r.id = rp.refund_id)
  select
    coalesce((select sum(subtotal) from s), 0)                                                  as gross,
    coalesce((select sum(tax) from s), 0)                                                       as tax,
    coalesce((select sum(subtotal + tax) from r), 0)                                            as refunds,
    coalesce((select sum(subtotal) from s), 0) + coalesce((select sum(tax) from s), 0)
      - coalesce((select sum(subtotal + tax) from r), 0)                                        as net,
    coalesce((select sum(amount) from pay where method = 'credit'), 0)
      - coalesce((select sum(amount) from rpay where method = 'credit'), 0)                     as card,
    coalesce((select sum(amount) from pay where method = 'cash'), 0)
      - coalesce((select sum(amount) from rpay where method = 'cash'), 0)                       as cash,
    0::numeric                                                                                  as check_amt,
    coalesce((select sum(amount) from pay where method = 'store_credit'), 0)
      - coalesce((select sum(amount) from rpay where method = 'store_credit'), 0)               as store_credit,
    coalesce((select sum(amount) from pay where method = 'gift_card'), 0)
      - coalesce((select sum(amount) from rpay where method = 'gift_card'), 0)                  as gift_card,
    (select count(distinct customer_id) from s where customer_id is not null)::int              as num_customers,
    (select count(*) from s)::int                                                               as num_tickets,
    coalesce((select sum(sl.qty) from sale_lines sl join s on s.id = sl.sale_id
              where sl.product_id is not null), 0)::int                                         as num_items;
$$;
grant execute on function sales_summary(timestamptz, timestamptz) to authenticated;

-- >>> supabase/migrations/0031_resolve_barcode.sql
-- =============================================================================
-- 0031_resolve_barcode.sql — one-shot barcode resolution (AceStock)
--
-- A scanned code may be an inventory product, a customer's racket, or a gift
-- card. The home screen and the POS each used to run their own chain of
-- queries to work that out; this RPC is the single definition of "what does
-- this barcode mean" so both screens (and later the iOS app) share it.
--
-- Resolution order: product → customer racket → gift card → none.
--
-- Normalization: whitespace is stripped. A 13-digit EAN that starts with a
-- zero is the same item as its 12-digit UPC-A form (scanners set to EAN mode
-- emit the leading zero), so both forms are tried against every barcode
-- column. Codes are otherwise matched exactly (gift-card and racket codes may
-- be alphanumeric).
--
-- Returns exactly one row. `kind` is one of 'product' | 'racket' |
-- 'gift_card' | 'none'. Product columns are filled for products so the POS can
-- add the line without a second round-trip; racket rows carry the owning
-- customer and the racket's open string job (entered/complete), if any.
--
-- Security invoker: it only reads tables the caller can already read, so the
-- existing RLS policies apply unchanged.
--
-- Re-runnable.
-- =============================================================================

create or replace function resolve_barcode(p_code text)
returns table (
  kind         text,
  code         text,
  id           uuid,
  customer_id  uuid,
  open_job_id  uuid,
  brand        text,
  name         text,
  attributes   jsonb,
  sell_price   numeric
)
language plpgsql
security invoker
stable
as $$
declare
  v_code       text := regexp_replace(coalesce(p_code, ''), '\s+', '', 'g');
  v_candidates text[];
  v_product    products%rowtype;
  v_racket     customer_rackets%rowtype;
  v_gift_card  gift_cards%rowtype;
begin
  if v_code = '' then
    return query select 'none', v_code, null::uuid, null::uuid, null::uuid,
                        null::text, null::text, null::jsonb, null::numeric;
    return;
  end if;

  -- EAN-13 with a leading zero <-> UPC-A.
  v_candidates := array[v_code];
  if v_code ~ '^0[0-9]{12}$' then
    v_candidates := v_candidates || substr(v_code, 2);
  elsif v_code ~ '^[0-9]{12}$' then
    v_candidates := v_candidates || ('0' || v_code);
  end if;

  select * into v_product
  from products p
  where p.barcode = any (v_candidates)
  limit 1;
  if found then
    return query select 'product', v_product.barcode, v_product.id, null::uuid, null::uuid,
                        v_product.brand, v_product.name, v_product.attributes, v_product.sell_price;
    return;
  end if;

  select * into v_racket
  from customer_rackets r
  where r.barcode = any (v_candidates)
  limit 1;
  if found then
    return query select 'racket', v_racket.barcode, v_racket.id, v_racket.customer_id,
                        (select j.id
                         from string_jobs j
                         where j.customer_racket_id = v_racket.id
                           and j.status in ('entered', 'complete')
                         order by j.entered_at desc
                         limit 1),
                        null::text, null::text, null::jsonb, null::numeric;
    return;
  end if;

  select * into v_gift_card
  from gift_cards g
  where g.code = any (v_candidates)
  limit 1;
  if found then
    return query select 'gift_card', v_gift_card.code, v_gift_card.id, v_gift_card.customer_id, null::uuid,
                        null::text, null::text, null::jsonb, null::numeric;
    return;
  end if;

  return query select 'none', v_code, null::uuid, null::uuid, null::uuid,
                      null::text, null::text, null::jsonb, null::numeric;
end;
$$;

grant execute on function resolve_barcode(text) to authenticated;

-- >>> supabase/migrations/0032_serialized_units.sql
-- =============================================================================
-- 0032_serialized_units.sql — serialized inventory (individual rackets) (AceStock)
--
-- Adds a second inventory level for items tracked as individual physical units
-- (rackets/paddles). Level 1 stays the catalog product (one row per model+grip,
-- carrying the UPC in products.barcode and the shared price). Level 2 is a new
-- product_units table: each physical unit has its own personal shop barcode and a
-- status, and can be attached to a customer (sold-to or demo loan, later).
--
-- Stock split: for a serialized product, on-hand is the count of in_stock units;
-- for everything else it stays the inventory_txns quantity sum. record_sale sells
-- a specific unit (by product_unit_id) instead of writing a 'sell' ledger txn.
--
-- Re-runnable.
-- =============================================================================

-- 1. Flag: which products are tracked as individual serialized units.
alter table products
  add column if not exists is_serialized boolean not null default false;

-- 2. Serialized units. One row per physical item, keyed to its catalog product.
create table if not exists product_units (
  id           uuid primary key default gen_random_uuid(),
  product_id   uuid not null references products (id),
  barcode      text,                             -- personal shop barcode (per unit; optional)
  status       text not null default 'in_stock'
                 check (status in ('in_stock', 'sold', 'demo', 'assigned', 'retired')),
  customer_id  uuid references customers (id),   -- sold-to or demo borrower (nullable)
  sale_id      uuid references sales (id),       -- the sale that sold this unit (nullable)
  note         text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- Personal barcode is optional, but unique when present.
create unique index if not exists uq_product_units_barcode
  on product_units (barcode) where barcode is not null;
create index if not exists idx_product_units_product on product_units (product_id);
create index if not exists idx_product_units_status on product_units (status);

alter table product_units enable row level security;
drop policy if exists product_units_authenticated_all on product_units;
create policy product_units_authenticated_all on product_units
  for all to authenticated using (true) with check (true);
grant select, insert, update, delete on product_units to authenticated;

-- 3. Sale lines can reference the exact physical unit sold.
alter table sale_lines
  add column if not exists product_unit_id uuid references product_units (id);

-- =============================================================================
-- 4. product_stock — serialized products count in_stock units; others sum ledger.
-- =============================================================================
create or replace view product_stock as
select
  p.id as product_id,
  case
    when p.is_serialized then (
      select count(*) from product_units u
      where u.product_id = p.id and u.status = 'in_stock'
    )::numeric
    else coalesce((select sum(t.qty) from inventory_txns t where t.product_id = p.id), 0)::numeric
  end as on_hand,
  p.reorder_point,
  (
    p.reorder_point is not null
    and (
      case
        when p.is_serialized then (
          select count(*) from product_units u
          where u.product_id = p.id and u.status = 'in_stock'
        )
        else coalesce((select sum(t.qty) from inventory_txns t where t.product_id = p.id), 0)
      end
    ) <= p.reorder_point
  ) as is_low
from products p;

grant select on product_stock to authenticated;

-- =============================================================================
-- 5. record_sale — a serialized product line consumes a specific unit.
--    Same signature as 0030; product lines may now carry "product_unit_id".
-- =============================================================================
create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_payments    jsonb,
  p_note        text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id     uuid := gen_random_uuid();
  v_line        jsonb;
  v_pay         jsonb;
  v_product     uuid;
  v_unit        uuid;
  v_serialized  boolean;
  v_job         uuid;
  v_gc          uuid;
  v_qty         integer;
  v_price       numeric;
  v_line_total  numeric;
  v_subtotal    numeric := 0;
  v_taxable     numeric := 0;
  v_paid        numeric := 0;
  v_method      text;
  v_amount      numeric;
  v_bal         numeric;
  v_prev        numeric;
  v_onhand      numeric;
  v_count       integer;
  v_rate        numeric := 0;
  v_tax_string  boolean := false;
  v_block       boolean := false;
  v_tax         numeric := 0;
  v_unit_status text;
  v_unit_prod   uuid;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  select tax_rate, tax_stringing, block_oversell
    into v_rate, v_tax_string, v_block
    from settings where id = true;
  v_rate := coalesce(v_rate, 0);

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_product := nullif(v_line->>'product_id', '')::uuid;
    v_unit    := nullif(v_line->>'product_unit_id', '')::uuid;
    v_job     := nullif(v_line->>'string_job_id', '')::uuid;
    v_gc      := nullif(v_line->>'gift_card_id', '')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_qty is null or v_qty <= 0 then raise exception 'Sale line quantity must be positive'; end if;
    if v_price is null or v_price < 0 then raise exception 'Sale line price must be >= 0'; end if;
    if (case when v_product is null then 0 else 1 end)
     + (case when v_job is null then 0 else 1 end)
     + (case when v_gc is null then 0 else 1 end) <> 1 then
      raise exception 'A sale line must reference exactly one of product, string job, or gift card';
    end if;

    v_line_total := v_qty * v_price;

    if v_product is not null then
      select is_serialized into v_serialized from products where id = v_product;
      if v_serialized is null then
        raise exception 'Unknown product_id % in sale line', v_product;
      end if;

      if v_serialized then
        -- Serialized: sell one specific physical unit; no stock ledger txn.
        if v_unit is null then
          raise exception 'Product % is serialized; a product_unit_id is required', v_product;
        end if;
        if v_qty <> 1 then
          raise exception 'Serialized items sell one unit per line (qty must be 1)';
        end if;
        select status, product_id into v_unit_status, v_unit_prod
          from product_units where id = v_unit for update;
        if v_unit_status is null then raise exception 'Unknown product_unit_id %', v_unit; end if;
        if v_unit_prod <> v_product then raise exception 'Unit % does not belong to product %', v_unit, v_product; end if;
        if v_unit_status <> 'in_stock' then raise exception 'Unit % is not in stock (status %)', v_unit, v_unit_status; end if;

        insert into sale_lines (sale_id, product_id, product_unit_id, qty, unit_price)
        values (v_sale_id, v_product, v_unit, v_qty, v_price);
        update product_units
           set status = 'sold', sale_id = v_sale_id, customer_id = p_customer_id, updated_at = now()
         where id = v_unit;
      else
        -- Fungible: quantity ledger, optional oversell block (unchanged behavior).
        if v_block then
          select coalesce(sum(qty), 0) into v_onhand from inventory_txns where product_id = v_product;
          if v_onhand < v_qty then
            raise exception 'Not enough stock for product % (% on hand, % requested)', v_product, v_onhand, v_qty;
          end if;
        end if;
        insert into sale_lines (sale_id, product_id, qty, unit_price) values (v_sale_id, v_product, v_qty, v_price);
        insert into inventory_txns (txn_type, product_id, qty, sale_id) values ('sell', v_product, -v_qty, v_sale_id);
      end if;

      v_taxable := v_taxable + v_line_total;
    elsif v_job is not null then
      if not exists (select 1 from string_jobs where id = v_job) then
        raise exception 'Unknown string_job_id % in sale line', v_job;
      end if;
      insert into sale_lines (sale_id, string_job_id, qty, unit_price) values (v_sale_id, v_job, v_qty, v_price);
      update string_jobs set paid_sale_id = v_sale_id where id = v_job;
      if v_tax_string then v_taxable := v_taxable + v_line_total; end if;
    else
      if not exists (select 1 from gift_cards where id = v_gc) then
        raise exception 'Unknown gift_card_id % in sale line', v_gc;
      end if;
      select coalesce(sum(amount), 0) into v_prev from gift_card_txns where gift_card_id = v_gc;
      insert into sale_lines (sale_id, gift_card_id, qty, unit_price) values (v_sale_id, v_gc, v_qty, v_price);
      insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_line_total, 'load', v_sale_id);
      if v_prev <= 0 then update gift_cards set customer_id = p_customer_id where id = v_gc; end if;
    end if;

    v_subtotal := v_subtotal + v_line_total;
  end loop;

  v_tax := round(v_taxable * v_rate / 100.0, 2);

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;
      if v_amount is null or v_amount <= 0 then raise exception 'Payment amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid payment method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card payment needs a gift_card_id'; end if;
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal < v_amount then raise exception 'Gift card balance % is less than %', v_bal, v_amount; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount, gift_card_id) values (v_sale_id, 'gift_card', v_amount, v_gc);
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal <= 0 then update gift_cards set customer_id = null where id = v_gc; end if;
      elsif v_method = 'store_credit' then
        if p_customer_id is null then raise exception 'Store credit needs a customer on the sale'; end if;
        select coalesce(sum(amount), 0) into v_bal from store_credit_txns where customer_id = p_customer_id;
        if v_bal < v_amount then raise exception 'Store credit balance % is less than %', v_bal, v_amount; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (p_customer_id, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, 'store_credit', v_amount);
      else
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, v_method, v_amount);
      end if;
      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - (v_subtotal + v_tax)) > 0.005 then
    raise exception 'Payments (%) must equal the sale total (%)', v_paid, v_subtotal + v_tax;
  end if;

  select count(*) into v_count from sale_payments where sale_id = v_sale_id;
  update sales
     set subtotal = v_subtotal,
         tax = v_tax,
         tax_rate = v_rate,
         payment_method = case
           when v_count = 0 then null
           when v_count = 1 then (select method from sale_payments where sale_id = v_sale_id limit 1)
           else 'split'
         end
   where id = v_sale_id;
  return v_sale_id;
end;
$$;
grant execute on function record_sale(jsonb, uuid, jsonb, text) to authenticated;

-- =============================================================================
-- 6. record_refund — guard: serialized (unit) lines can't be returned yet.
--    Returning a physical racket must flip its unit back to in_stock; that flow
--    is a planned follow-up, so block it here to protect data integrity rather
--    than post a meaningless stock txn. Same signature as 0030.
-- =============================================================================
create or replace function record_refund(
  p_sale_id  uuid,
  p_lines    jsonb,
  p_payments jsonb,
  p_reason   text,
  p_note     text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_refund_id uuid := gen_random_uuid();
  v_customer  uuid;
  v_rate      numeric := 0;
  v_line      jsonb;
  v_pay       jsonb;
  v_sl_id     uuid;
  v_qty       integer;
  v_sl        record;
  v_returned  integer;
  v_sub       numeric := 0;
  v_tax       numeric := 0;
  v_total     numeric := 0;
  v_paid      numeric := 0;
  v_method    text;
  v_amount    numeric;
  v_gc        uuid;
begin
  select customer_id, coalesce(tax_rate, 0) into v_customer, v_rate from sales where id = p_sale_id;
  if not found then raise exception 'Unknown sale %', p_sale_id; end if;
  if p_lines is null or jsonb_array_length(p_lines) = 0 then raise exception 'A refund needs at least one line'; end if;

  insert into refunds (id, sale_id, reason, note)
  values (v_refund_id, p_sale_id, nullif(trim(p_reason), ''), nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_sl_id := (v_line->>'sale_line_id')::uuid;
    v_qty   := (v_line->>'qty')::integer;
    if v_qty is null or v_qty <= 0 then raise exception 'Return quantity must be positive'; end if;

    select * into v_sl from sale_lines where id = v_sl_id and sale_id = p_sale_id;
    if not found then raise exception 'Line % is not part of sale %', v_sl_id, p_sale_id; end if;
    if v_sl.product_id is null then raise exception 'Only product lines can be returned'; end if;
    if v_sl.product_unit_id is not null then
      raise exception 'Returning individual (serialized) items is not supported yet';
    end if;

    select coalesce(sum(rl.qty), 0) into v_returned from refund_lines rl where rl.sale_line_id = v_sl_id;
    if v_qty > v_sl.qty - v_returned then
      raise exception 'Cannot return % of line (only % remaining)', v_qty, v_sl.qty - v_returned;
    end if;

    insert into refund_lines (refund_id, sale_line_id, qty, unit_price)
    values (v_refund_id, v_sl_id, v_qty, v_sl.unit_price);
    -- Returned stock goes back on hand.
    insert into inventory_txns (txn_type, product_id, qty, sale_id)
    values ('return', v_sl.product_id, v_qty, p_sale_id);

    v_sub := v_sub + v_qty * v_sl.unit_price;
  end loop;

  v_tax   := round(v_sub * v_rate / 100.0, 2);
  v_total := v_sub + v_tax;
  update refunds set subtotal = v_sub, tax = v_tax where id = v_refund_id;

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;
      if v_amount is null or v_amount <= 0 then raise exception 'Refund amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid refund method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card refund needs a gift_card_id'; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_amount, 'refund', p_sale_id);
      elsif v_method = 'store_credit' then
        if v_customer is null then raise exception 'Store credit refund needs a customer on the sale'; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (v_customer, v_amount, 'refund', p_sale_id);
      end if;
      insert into refund_payments (refund_id, method, amount, gift_card_id) values (v_refund_id, v_method, v_amount, v_gc);
      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - v_total) > 0.005 then
    raise exception 'Refund payments (%) must equal the refund total (%)', v_paid, v_total;
  end if;

  return v_refund_id;
end;
$$;
grant execute on function record_refund(uuid, jsonb, jsonb, text, text) to authenticated;

-- =============================================================================
-- 7. receive_units — add physical units to a serialized product.
--    p_barcodes is a JSON array with one element per unit received; each element
--    is the unit's personal barcode, or null/"" for a unit with no barcode yet
--    (barcode is optional). Rejects a barcode already used by another unit.
--    Returns the number of units created.
-- =============================================================================
create or replace function receive_units(
  p_product_id uuid,
  p_barcodes   jsonb
)
returns integer
language plpgsql
security invoker
as $$
declare
  v_serialized boolean;
  v_el         jsonb;
  v_code       text;
  v_count      integer := 0;
begin
  select is_serialized into v_serialized from products where id = p_product_id;
  if v_serialized is null then raise exception 'Unknown product_id %', p_product_id; end if;
  if not v_serialized then raise exception 'Product % is not serialized', p_product_id; end if;
  if p_barcodes is null or jsonb_array_length(p_barcodes) = 0 then
    raise exception 'Receive at least one unit';
  end if;

  for v_el in select * from jsonb_array_elements(p_barcodes)
  loop
    -- '#>> {}' pulls the scalar text out of a jsonb element (string or null).
    v_code := nullif(btrim(coalesce(v_el #>> '{}', '')), '');
    if v_code is not null and exists (select 1 from product_units where barcode = v_code) then
      raise exception 'Barcode % is already in use', v_code;
    end if;
    insert into product_units (product_id, barcode) values (p_product_id, v_code);
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;
grant execute on function receive_units(uuid, jsonb) to authenticated;

-- =============================================================================
-- 8. resolve_barcode — now also resolves a serialized unit's personal barcode
--    and reports whether a matched product is serialized. Resolution order:
--    product UPC -> product unit -> customer racket -> gift card -> none. Return
--    type changes (new product_id + unit_status columns), so drop and recreate.
-- =============================================================================
drop function if exists resolve_barcode(text);
create or replace function resolve_barcode(p_code text)
returns table (
  kind          text,
  code          text,
  id            uuid,      -- the matched thing's id (product / unit / racket / gift card)
  product_id    uuid,      -- for a unit: its catalog product; else null
  customer_id   uuid,
  open_job_id   uuid,
  brand         text,
  name          text,
  attributes    jsonb,
  sell_price    numeric,
  is_serialized boolean,
  unit_status   text       -- for a unit: its status; else null
)
language plpgsql
security invoker
stable
as $$
declare
  v_code       text := regexp_replace(coalesce(p_code, ''), '\s+', '', 'g');
  v_candidates text[];
  v_product    products%rowtype;
  v_unit       product_units%rowtype;
  v_racket     customer_rackets%rowtype;
  v_gift_card  gift_cards%rowtype;
begin
  if v_code = '' then
    return query select 'none', v_code, null::uuid, null::uuid, null::uuid, null::uuid,
                        null::text, null::text, null::jsonb, null::numeric, false, null::text;
    return;
  end if;

  v_candidates := array[v_code];
  if v_code ~ '^0[0-9]{12}$' then
    v_candidates := v_candidates || substr(v_code, 2);
  elsif v_code ~ '^[0-9]{12}$' then
    v_candidates := v_candidates || ('0' || v_code);
  end if;

  -- Product UPC.
  select * into v_product from products p where p.barcode = any (v_candidates) limit 1;
  if found then
    return query select 'product', v_product.barcode, v_product.id, null::uuid, null::uuid, null::uuid,
                        v_product.brand, v_product.name, v_product.attributes, v_product.sell_price,
                        v_product.is_serialized, null::text;
    return;
  end if;

  -- Individual unit's personal barcode.
  select * into v_unit from product_units u where u.barcode = any (v_candidates) limit 1;
  if found then
    select * into v_product from products p where p.id = v_unit.product_id;
    return query select 'unit', v_unit.barcode, v_unit.id, v_unit.product_id, null::uuid, null::uuid,
                        v_product.brand, v_product.name, v_product.attributes, v_product.sell_price,
                        true, v_unit.status;
    return;
  end if;

  select * into v_racket from customer_rackets r where r.barcode = any (v_candidates) limit 1;
  if found then
    return query select 'racket', v_racket.barcode, v_racket.id, null::uuid, v_racket.customer_id,
                        (select j.id from string_jobs j
                          where j.customer_racket_id = v_racket.id
                            and j.status in ('entered', 'complete')
                          order by j.entered_at desc limit 1),
                        null::text, null::text, null::jsonb, null::numeric, false, null::text;
    return;
  end if;

  select * into v_gift_card from gift_cards g where g.code = any (v_candidates) limit 1;
  if found then
    return query select 'gift_card', v_gift_card.code, v_gift_card.id, null::uuid, v_gift_card.customer_id, null::uuid,
                        null::text, null::text, null::jsonb, null::numeric, false, null::text;
    return;
  end if;

  return query select 'none', v_code, null::uuid, null::uuid, null::uuid, null::uuid,
                      null::text, null::text, null::jsonb, null::numeric, false, null::text;
end;
$$;
grant execute on function resolve_barcode(text) to authenticated;

-- >>> supabase/migrations/0033_racquets_serialized_default.sql
-- =============================================================================
-- 0033_racquets_serialized_default.sql — rackets are always serialized (AceStock)
--
-- Serialization is a property of the category, not something to toggle per
-- product: every product under a "serialized" category (Racquets) is tracked as
-- individual units. This adds a categories.serialized_default flag, turns it on
-- for Racquets, backfills existing racket products, and enforces it on insert so
-- new rackets are serialized no matter how they're created.
--
-- Re-runnable.
-- =============================================================================

-- 1. Category-level flag: products in this category are serialized (unit-tracked).
alter table categories
  add column if not exists serialized_default boolean not null default false;

-- 2. Racquets is serialized. (Match common spellings to be safe.)
update categories set serialized_default = true
  where lower(name) in ('racquets', 'rackets');

-- 3. Backfill: existing products in a serialized category become serialized.
update products p
   set is_serialized = true
  from categories c
 where c.id = p.category_id
   and c.serialized_default
   and p.is_serialized = false;

-- 4. Enforce on insert (and on a category change): a product in a serialized
--    category is always serialized, regardless of what the client sent.
create or replace function apply_serialized_default()
returns trigger
language plpgsql
as $$
begin
  if exists (
    select 1 from categories c
    where c.id = new.category_id and c.serialized_default
  ) then
    new.is_serialized := true;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_apply_serialized_default on products;
create trigger trg_apply_serialized_default
  before insert or update of category_id on products
  for each row execute function apply_serialized_default();

-- >>> supabase/migrations/0034_product_units_barcode_nullable.sql
-- =============================================================================
-- 0034_product_units_barcode_nullable.sql — make the unit barcode optional
--
-- product_units.barcode is optional (a racket may be received before its
-- personal barcode is assigned). Earlier copies of 0032 created the column as
-- NOT NULL; this brings any such database in line: drop NOT NULL and ensure the
-- uniqueness constraint only applies when a barcode is present.
--
-- Re-runnable.
-- =============================================================================

alter table product_units alter column barcode drop not null;

drop index if exists uq_product_units_barcode;
create unique index if not exists uq_product_units_barcode
  on product_units (barcode) where barcode is not null;

-- >>> supabase/migrations/0035_staff_attribution.sql
-- =============================================================================
-- 0035_staff_attribution.sql — record who did it (AceStock, Phase 1A)
--
-- Every money and stock record now carries the signed-in staff member who
-- created it. Columns default to auth.uid(), so the existing server functions
-- (record_sale, record_refund, receive_stock, ...) fill them in without being
-- rewritten, and so does any future client insert.
--
--   sales.user_id, inventory_txns.user_id   existed but were never set → default
--   refunds / gift_card_txns / store_credit_txns.user_id                → new
--   product_units.created_by                (who received the unit)     → new
--   string_jobs.entered_by / completed_by / delivered_by / cancelled_by → new
--   string_jobs.cancelled_at                                            → new
--
-- All attribution columns reference profiles (one row per staff account) so
-- the API can embed the staff member's email, and fall back to null if a staff
-- account is ever deleted. advance_string_job and cancel_string_job are
-- redefined to stamp the status-change columns. Behavior is otherwise unchanged.
--
-- Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Attribution columns: add (where missing), default to the signed-in user,
--    and point at profiles.
-- ----------------------------------------------------------------------------
alter table sales             add column if not exists user_id uuid;
alter table inventory_txns    add column if not exists user_id uuid;
alter table refunds           add column if not exists user_id uuid;
alter table gift_card_txns    add column if not exists user_id uuid;
alter table store_credit_txns add column if not exists user_id uuid;
alter table product_units     add column if not exists created_by uuid;
alter table string_jobs
  add column if not exists entered_by   uuid,
  add column if not exists completed_by uuid,
  add column if not exists delivered_by uuid,
  add column if not exists cancelled_by uuid,
  add column if not exists cancelled_at timestamptz;

do $$
declare
  -- {table, column, stamped on insert?}
  attribution_columns text[][] := array[
    array['sales',             'user_id',      'yes'],
    array['inventory_txns',    'user_id',      'yes'],
    array['refunds',           'user_id',      'yes'],
    array['gift_card_txns',    'user_id',      'yes'],
    array['store_credit_txns', 'user_id',      'yes'],
    array['product_units',     'created_by',   'yes'],
    array['string_jobs',       'entered_by',   'yes'],
    array['string_jobs',       'completed_by', 'no'],
    array['string_jobs',       'delivered_by', 'no'],
    array['string_jobs',       'cancelled_by', 'no']
  ];
  entry text[];
  table_name text;
  column_name text;
  constraint_name text;
begin
  foreach entry slice 1 in array attribution_columns loop
    table_name := entry[1];
    column_name := entry[2];
    constraint_name := format('%s_%s_fkey', table_name, column_name);

    if entry[3] = 'yes' then
      execute format('alter table %I alter column %I set default auth.uid()', table_name, column_name);
    end if;

    -- Any stray value that isn't a staff profile can't satisfy the foreign key.
    -- (Before this migration these columns were never written, so this is a
    -- no-op on real data; it only guards hand-edited test databases.)
    execute format(
      'update %I set %I = null where %I is not null and not exists (select 1 from profiles p where p.id = %I.%I)',
      table_name, column_name, column_name, table_name, column_name);

    execute format('alter table %I drop constraint if exists %I', table_name, constraint_name);
    execute format(
      'alter table %I add constraint %I foreign key (%I) references profiles (id) on delete set null',
      table_name, constraint_name, column_name);
  end loop;
end $$;

create index if not exists idx_sales_user   on sales (user_id);
create index if not exists idx_refunds_user on refunds (user_id);

-- ----------------------------------------------------------------------------
-- 2. advance_string_job — same rules as 0019, now records who completed /
--    delivered the job.
-- ----------------------------------------------------------------------------
create or replace function advance_string_job(
  p_job_id        uuid,
  p_target_status text
)
returns text
language plpgsql
security invoker
as $$
declare
  v_current text;
  v_rank    integer;
  v_target  integer;
  v_main    uuid;
  v_cross   uuid;
begin
  select status, main_product_id, cross_product_id
    into v_current, v_main, v_cross
    from string_jobs where id = p_job_id;
  if v_current is null then
    raise exception 'Unknown string job %', p_job_id;
  end if;

  v_rank   := case v_current       when 'entered' then 0 when 'complete' then 1 when 'delivered' then 2 else -1 end;
  v_target := case p_target_status when 'entered' then 0 when 'complete' then 1 when 'delivered' then 2 else -1 end;

  if v_target < 0 then
    raise exception 'Invalid status "%"', p_target_status;
  end if;
  if v_target <> v_rank + 1 then
    raise exception 'Cannot move a string job from "%" to "%"', v_current, p_target_status;
  end if;

  update string_jobs
    set status       = p_target_status,
        completed_at = case when p_target_status = 'complete'  then now()      else completed_at end,
        completed_by = case when p_target_status = 'complete'  then auth.uid() else completed_by end,
        delivered_at = case when p_target_status = 'delivered' then now()      else delivered_at end,
        delivered_by = case when p_target_status = 'delivered' then auth.uid() else delivered_by end
  where id = p_job_id;

  -- Consume one unit of each distinct catalog string the job used.
  if p_target_status = 'complete' then
    insert into inventory_txns (txn_type, product_id, qty, note)
    select 'consume', pid, -1, 'String job completed'
    from (
      select distinct pid
      from (values (v_main), (v_cross)) as t(pid)
      where pid is not null
    ) d;
  end if;

  return p_target_status;
end;
$$;

grant execute on function advance_string_job(uuid, text) to authenticated;

-- ----------------------------------------------------------------------------
-- 3. cancel_string_job — same rules as 0020, now records who cancelled and when.
-- ----------------------------------------------------------------------------
create or replace function cancel_string_job(p_job_id uuid)
returns text
language plpgsql
security invoker
as $$
declare
  v_current text;
begin
  select status into v_current from string_jobs where id = p_job_id;
  if v_current is null then
    raise exception 'Unknown string job %', p_job_id;
  end if;
  if v_current <> 'entered' then
    raise exception 'Only an entered job can be cancelled (this one is "%")', v_current;
  end if;

  update string_jobs
     set status       = 'cancelled',
         cancelled_at = now(),
         cancelled_by = auth.uid()
   where id = p_job_id;
  return 'cancelled';
end;
$$;

grant execute on function cancel_string_job(uuid) to authenticated;

-- >>> supabase/migrations/0036_customer_racket_soft_delete.sql
-- =============================================================================
-- 0036_customer_racket_soft_delete.sql — keep stringing history (AceStock, 1A)
--
-- Removing a customer's racket used to DELETE the row, which cascaded to every
-- string job on it (or failed outright once a job had been paid, because the
-- sale line still referenced the job). Rackets are now retired by setting
-- is_active = false, and the database refuses to delete a racket that has
-- string jobs, so history can't be lost by accident.
--
-- A retired racket's tag barcode is freed for reuse: uniqueness and barcode
-- lookup only consider active rackets.
--
-- Re-runnable.
-- =============================================================================

-- 1. A racket with string jobs can no longer be deleted (was: on delete cascade).
alter table string_jobs drop constraint if exists string_jobs_customer_racket_id_fkey;
alter table string_jobs
  add constraint string_jobs_customer_racket_id_fkey
  foreign key (customer_racket_id) references customer_rackets (id) on delete restrict;

-- 2. Tag barcodes are unique among active rackets only.
drop index if exists uq_customer_rackets_barcode;
create unique index if not exists uq_customer_rackets_barcode
  on customer_rackets (barcode)
  where barcode is not null and is_active;

-- 3. resolve_barcode — same as 0032, except a retired racket's tag no longer
--    resolves (so a reused tag finds the new racket, not the old one).
create or replace function resolve_barcode(p_code text)
returns table (
  kind          text,
  code          text,
  id            uuid,      -- the matched thing's id (product / unit / racket / gift card)
  product_id    uuid,      -- for a unit: its catalog product; else null
  customer_id   uuid,
  open_job_id   uuid,
  brand         text,
  name          text,
  attributes    jsonb,
  sell_price    numeric,
  is_serialized boolean,
  unit_status   text       -- for a unit: its status; else null
)
language plpgsql
security invoker
stable
as $$
declare
  v_code       text := regexp_replace(coalesce(p_code, ''), '\s+', '', 'g');
  v_candidates text[];
  v_product    products%rowtype;
  v_unit       product_units%rowtype;
  v_racket     customer_rackets%rowtype;
  v_gift_card  gift_cards%rowtype;
begin
  if v_code = '' then
    return query select 'none', v_code, null::uuid, null::uuid, null::uuid, null::uuid,
                        null::text, null::text, null::jsonb, null::numeric, false, null::text;
    return;
  end if;

  -- EAN-13 with a leading zero <-> UPC-A.
  v_candidates := array[v_code];
  if v_code ~ '^0[0-9]{12}$' then
    v_candidates := v_candidates || substr(v_code, 2);
  elsif v_code ~ '^[0-9]{12}$' then
    v_candidates := v_candidates || ('0' || v_code);
  end if;

  -- Product UPC.
  select * into v_product from products p where p.barcode = any (v_candidates) limit 1;
  if found then
    return query select 'product', v_product.barcode, v_product.id, null::uuid, null::uuid, null::uuid,
                        v_product.brand, v_product.name, v_product.attributes, v_product.sell_price,
                        v_product.is_serialized, null::text;
    return;
  end if;

  -- Individual unit's personal barcode.
  select * into v_unit from product_units u where u.barcode = any (v_candidates) limit 1;
  if found then
    select * into v_product from products p where p.id = v_unit.product_id;
    return query select 'unit', v_unit.barcode, v_unit.id, v_unit.product_id, null::uuid, null::uuid,
                        v_product.brand, v_product.name, v_product.attributes, v_product.sell_price,
                        true, v_unit.status;
    return;
  end if;

  -- Customer racket tag (active rackets only).
  select * into v_racket
  from customer_rackets r
  where r.barcode = any (v_candidates) and r.is_active
  limit 1;
  if found then
    return query select 'racket', v_racket.barcode, v_racket.id, null::uuid, v_racket.customer_id,
                        (select j.id from string_jobs j
                          where j.customer_racket_id = v_racket.id
                            and j.status in ('entered', 'complete')
                          order by j.entered_at desc limit 1),
                        null::text, null::text, null::jsonb, null::numeric, false, null::text;
    return;
  end if;

  select * into v_gift_card from gift_cards g where g.code = any (v_candidates) limit 1;
  if found then
    return query select 'gift_card', v_gift_card.code, v_gift_card.id, null::uuid, v_gift_card.customer_id, null::uuid,
                        null::text, null::text, null::jsonb, null::numeric, false, null::text;
    return;
  end if;

  return query select 'none', v_code, null::uuid, null::uuid, null::uuid, null::uuid,
                      null::text, null::text, null::jsonb, null::numeric, false, null::text;
end;
$$;

grant execute on function resolve_barcode(text) to authenticated;

-- >>> supabase/migrations/0037_search_customers.sql
-- =============================================================================
-- 0037_search_customers.sql — server-side customer search (AceStock, Phase 1A)
--
-- The home screen and the register used to build a PostgREST `or=(...)` filter
-- by pasting the typed text into it, so a name containing a comma or a
-- parenthesis broke the query, and only first/last name were searched. This
-- function is the single definition of customer search:
--
--   • first name, last name, "first last", "last, first", or email — a
--     case-insensitive substring match, with % _ \ in the input treated as
--     literal characters
--   • phone number — when the input looks like a phone number (only digits,
--     spaces and ( ) - . +, with 3+ digits), matched against the phone's digits
--     only, so "225-555", "(225) 555" and "225555" all find (225)555-1234
--
-- Ordered last name, first name; at most p_limit rows (1–50, default 8).
-- Security invoker: reads customers under the caller's existing RLS.
--
-- Re-runnable.
-- =============================================================================

create or replace function search_customers(p_term text, p_limit integer default 8)
returns setof customers
language sql
security invoker
stable
as $$
  with input as (
    select
      btrim(coalesce(p_term, ''))                              as term,
      regexp_replace(coalesce(p_term, ''), '\D', '', 'g')      as digits
  ),
  pattern as (
    select
      term,
      digits,
      -- Escape LIKE wildcards so the typed text is matched literally.
      '%' || replace(replace(replace(term, '\', '\\'), '%', '\%'), '_', '\_') || '%' as contains
    from input
  )
  select c.*
  from customers c, pattern p
  where p.term <> ''
    and (
         c.first_name ilike p.contains
      or c.last_name  ilike p.contains
      or (c.first_name || ' '  || c.last_name)  ilike p.contains
      or (c.last_name  || ', ' || c.first_name) ilike p.contains
      or c.email ilike p.contains
      or (
           p.term ~ '^[0-9()+.\s-]+$'
           and length(p.digits) >= 3
           and regexp_replace(coalesce(c.phone_number, ''), '\D', '', 'g') like '%' || p.digits || '%'
         )
    )
  order by lower(c.last_name), lower(c.first_name)
  limit least(greatest(coalesce(p_limit, 8), 1), 50);
$$;

grant execute on function search_customers(text, integer) to authenticated;

-- >>> supabase/migrations/0038_sale_refund_guards.sql
-- =============================================================================
-- 0038_sale_refund_guards.sql — money-path correctness (AceStock, Phase 1B)
--
-- 1. Concurrency. record_sale, record_refund and adjust_gift_card used to read
--    a balance (gift card, store credit, stock, returnable quantity) and then
--    act on it, so two registers working at the same moment could both pass
--    the check. Each now locks the rows it depends on first (`for update`, in
--    a fixed order: products → product_units → string_jobs → gift_cards →
--    customers, ids ascending) so the second register waits for the first and
--    then sees its result. record_refund locks the sale, which serializes all
--    refunds of that sale.
--
-- 2. String jobs can't be charged twice. record_sale rejects a job that is
--    already paid, cancelled, or on the same ticket twice; a trigger keeps a
--    paid job's price and paying sale from being changed afterwards.
--
-- 3. Refund payment types. Each payment type can give back up to what the sale
--    took that way (net of earlier refunds). Sending more to a type than that —
--    e.g. refunding a gift-card purchase as cash — is a payment-type change: any
--    staff member may do it, but must give a reason, which is stored on the
--    refund (refunds.method_change_reason) alongside who made it (user_id).
--
-- 4. Refund tax. Each refund used to round its own tax, so returning items in
--    separate refunds could give back a cent more tax than the sale charged
--    (2 × $5.05 at 8.25%: charged $0.83, refunded 0.42 + 0.42). Tax is now
--    computed on the cumulative refunded subtotal and never exceeds the tax the
--    sale charged.
--
-- record_refund gains an optional p_method_change_reason argument (default
-- null), so the old 5-argument version is dropped. Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Where a payment-type change is explained.
-- ----------------------------------------------------------------------------
alter table refunds add column if not exists method_change_reason text;

-- ----------------------------------------------------------------------------
-- 2. A paid string job keeps its price and its paying sale.
-- ----------------------------------------------------------------------------
create or replace function guard_paid_string_job()
returns trigger
language plpgsql
as $$
begin
  if old.paid_sale_id is not null then
    if new.paid_sale_id is distinct from old.paid_sale_id then
      raise exception 'String job % is already paid by sale %', old.id, old.paid_sale_id;
    end if;
    if new.price is distinct from old.price then
      raise exception 'The price of a paid string job can''t be changed';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_guard_paid_string_job on string_jobs;
create trigger trg_guard_paid_string_job
  before update of paid_sale_id, price on string_jobs
  for each row execute function guard_paid_string_job();

-- ----------------------------------------------------------------------------
-- 3. record_sale — same behavior as 0032, plus row locks and the string-job
--    payment guard.
-- ----------------------------------------------------------------------------
create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_payments    jsonb,
  p_note        text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id     uuid := gen_random_uuid();
  v_line        jsonb;
  v_pay         jsonb;
  v_product     uuid;
  v_unit        uuid;
  v_serialized  boolean;
  v_job         uuid;
  v_job_status  text;
  v_job_paid    uuid;
  v_gc          uuid;
  v_qty         integer;
  v_price       numeric;
  v_line_total  numeric;
  v_subtotal    numeric := 0;
  v_taxable     numeric := 0;
  v_paid        numeric := 0;
  v_method      text;
  v_amount      numeric;
  v_bal         numeric;
  v_prev        numeric;
  v_onhand      numeric;
  v_count       integer;
  v_rate        numeric := 0;
  v_tax_string  boolean := false;
  v_block       boolean := false;
  v_tax         numeric := 0;
  v_unit_status text;
  v_unit_prod   uuid;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  select tax_rate, tax_stringing, block_oversell
    into v_rate, v_tax_string, v_block
    from settings where id = true;
  v_rate := coalesce(v_rate, 0);

  -- Lock everything whose balance or state this sale checks, in a fixed order,
  -- so a concurrent sale waits here and then sees this sale's effects.
  if v_block then
    perform 1 from products
     where id in (select nullif(l->>'product_id', '')::uuid from jsonb_array_elements(p_lines) l)
     order by id for update;
  end if;
  perform 1 from product_units
   where id in (select nullif(l->>'product_unit_id', '')::uuid from jsonb_array_elements(p_lines) l)
   order by id for update;
  perform 1 from string_jobs
   where id in (select nullif(l->>'string_job_id', '')::uuid from jsonb_array_elements(p_lines) l)
   order by id for update;
  perform 1 from gift_cards
   where id in (
     select nullif(l->>'gift_card_id', '')::uuid from jsonb_array_elements(p_lines) l
     union
     select nullif(p->>'gift_card_id', '')::uuid from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) p)
   order by id for update;
  if p_customer_id is not null and exists (
       select 1 from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) p
       where p->>'method' = 'store_credit') then
    perform 1 from customers where id = p_customer_id for update;
  end if;

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_product := nullif(v_line->>'product_id', '')::uuid;
    v_unit    := nullif(v_line->>'product_unit_id', '')::uuid;
    v_job     := nullif(v_line->>'string_job_id', '')::uuid;
    v_gc      := nullif(v_line->>'gift_card_id', '')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_qty is null or v_qty <= 0 then raise exception 'Sale line quantity must be positive'; end if;
    if v_price is null or v_price < 0 then raise exception 'Sale line price must be >= 0'; end if;
    if (case when v_product is null then 0 else 1 end)
     + (case when v_job is null then 0 else 1 end)
     + (case when v_gc is null then 0 else 1 end) <> 1 then
      raise exception 'A sale line must reference exactly one of product, string job, or gift card';
    end if;

    v_line_total := v_qty * v_price;

    if v_product is not null then
      select is_serialized into v_serialized from products where id = v_product;
      if v_serialized is null then
        raise exception 'Unknown product_id % in sale line', v_product;
      end if;

      if v_serialized then
        -- Serialized: sell one specific physical unit; no stock ledger txn.
        if v_unit is null then
          raise exception 'Product % is serialized; a product_unit_id is required', v_product;
        end if;
        if v_qty <> 1 then
          raise exception 'Serialized items sell one unit per line (qty must be 1)';
        end if;
        select status, product_id into v_unit_status, v_unit_prod
          from product_units where id = v_unit;
        if v_unit_status is null then raise exception 'Unknown product_unit_id %', v_unit; end if;
        if v_unit_prod <> v_product then raise exception 'Unit % does not belong to product %', v_unit, v_product; end if;
        if v_unit_status <> 'in_stock' then raise exception 'Unit % is not in stock (status %)', v_unit, v_unit_status; end if;

        insert into sale_lines (sale_id, product_id, product_unit_id, qty, unit_price)
        values (v_sale_id, v_product, v_unit, v_qty, v_price);
        update product_units
           set status = 'sold', sale_id = v_sale_id, customer_id = p_customer_id, updated_at = now()
         where id = v_unit;
      else
        -- Fungible: quantity ledger, optional oversell block.
        if v_block then
          select coalesce(sum(qty), 0) into v_onhand from inventory_txns where product_id = v_product;
          if v_onhand < v_qty then
            raise exception 'Not enough stock for product % (% on hand, % requested)', v_product, v_onhand, v_qty;
          end if;
        end if;
        insert into sale_lines (sale_id, product_id, qty, unit_price) values (v_sale_id, v_product, v_qty, v_price);
        insert into inventory_txns (txn_type, product_id, qty, sale_id) values ('sell', v_product, -v_qty, v_sale_id);
      end if;
      v_taxable := v_taxable + v_line_total;

    elsif v_job is not null then
      select status, paid_sale_id into v_job_status, v_job_paid from string_jobs where id = v_job;
      if not found then
        raise exception 'Unknown string_job_id % in sale line', v_job;
      end if;
      if v_job_status = 'cancelled' then
        raise exception 'String job % was cancelled and can''t be charged', v_job;
      end if;
      if v_job_paid = v_sale_id then
        raise exception 'String job % is on this ticket more than once', v_job;
      end if;
      if v_job_paid is not null then
        raise exception 'String job % is already paid (sale %)', v_job, v_job_paid;
      end if;
      insert into sale_lines (sale_id, string_job_id, qty, unit_price) values (v_sale_id, v_job, v_qty, v_price);
      update string_jobs set paid_sale_id = v_sale_id where id = v_job;
      if v_tax_string then v_taxable := v_taxable + v_line_total; end if;

    else
      if not exists (select 1 from gift_cards where id = v_gc) then
        raise exception 'Unknown gift_card_id % in sale line', v_gc;
      end if;
      select coalesce(sum(amount), 0) into v_prev from gift_card_txns where gift_card_id = v_gc;
      insert into sale_lines (sale_id, gift_card_id, qty, unit_price) values (v_sale_id, v_gc, v_qty, v_price);
      insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_line_total, 'load', v_sale_id);
      if v_prev <= 0 then update gift_cards set customer_id = p_customer_id where id = v_gc; end if;
    end if;

    v_subtotal := v_subtotal + v_line_total;
  end loop;

  v_tax := round(v_taxable * v_rate / 100.0, 2);

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;

      if v_amount is null or v_amount <= 0 then raise exception 'Payment amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid payment method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card payment needs a gift_card_id'; end if;
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal < v_amount then raise exception 'Gift card balance % is less than %', v_bal, v_amount; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount, gift_card_id) values (v_sale_id, 'gift_card', v_amount, v_gc);
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal <= 0 then update gift_cards set customer_id = null where id = v_gc; end if;
      elsif v_method = 'store_credit' then
        if p_customer_id is null then raise exception 'Store credit needs a customer on the sale'; end if;
        select coalesce(sum(amount), 0) into v_bal from store_credit_txns where customer_id = p_customer_id;
        if v_bal < v_amount then raise exception 'Store credit balance % is less than %', v_bal, v_amount; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (p_customer_id, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, 'store_credit', v_amount);
      else
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, v_method, v_amount);
      end if;

      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - (v_subtotal + v_tax)) > 0.005 then
    raise exception 'Payments (%) must equal the sale total (%)', v_paid, v_subtotal + v_tax;
  end if;

  select count(*) into v_count from sale_payments where sale_id = v_sale_id;
  update sales
     set subtotal = v_subtotal,
         tax = v_tax,
         tax_rate = v_rate,
         payment_method = case
           when v_count = 0 then null
           when v_count = 1 then (select method from sale_payments where sale_id = v_sale_id limit 1)
           else 'split'
         end
   where id = v_sale_id;

  return v_sale_id;
end;
$$;

grant execute on function record_sale(jsonb, uuid, jsonb, text) to authenticated;

-- ----------------------------------------------------------------------------
-- 4. record_refund — same as 0032, plus: the sale is locked (refunds of one
--    sale run one at a time), tax is cumulative and capped at the sale's tax,
--    and payment-type changes need a reason.
-- ----------------------------------------------------------------------------
drop function if exists record_refund(uuid, jsonb, jsonb, text, text);

create or replace function record_refund(
  p_sale_id              uuid,
  p_lines                jsonb,
  p_payments             jsonb,
  p_reason               text,
  p_note                 text,
  p_method_change_reason text default null
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_refund_id  uuid := gen_random_uuid();
  v_customer   uuid;
  v_rate       numeric := 0;
  v_sale_tax   numeric := 0;
  v_prev_sub   numeric := 0;
  v_prev_tax   numeric := 0;
  v_line       jsonb;
  v_pay        jsonb;
  v_sl_id      uuid;
  v_qty        integer;
  v_sl         record;
  v_returned   integer;
  v_sub        numeric := 0;
  v_tax        numeric := 0;
  v_total      numeric := 0;
  v_paid       numeric := 0;
  v_method     text;
  v_amount     numeric;
  v_gc         uuid;
  v_by_method  record;
  v_changed    text[] := '{}';
begin
  -- Locking the sale serializes refunds of the same sale, so remaining
  -- quantities, tax and per-method amounts below can't be raced.
  select customer_id, coalesce(tax_rate, 0), coalesce(tax, 0)
    into v_customer, v_rate, v_sale_tax
    from sales where id = p_sale_id
    for update;
  if not found then raise exception 'Unknown sale %', p_sale_id; end if;
  if p_lines is null or jsonb_array_length(p_lines) = 0 then raise exception 'A refund needs at least one line'; end if;

  select coalesce(sum(subtotal), 0), coalesce(sum(tax), 0)
    into v_prev_sub, v_prev_tax
    from refunds where sale_id = p_sale_id;

  insert into refunds (id, sale_id, reason, note)
  values (v_refund_id, p_sale_id, nullif(trim(p_reason), ''), nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_sl_id := (v_line->>'sale_line_id')::uuid;
    v_qty   := (v_line->>'qty')::integer;
    if v_qty is null or v_qty <= 0 then raise exception 'Return quantity must be positive'; end if;

    select * into v_sl from sale_lines where id = v_sl_id and sale_id = p_sale_id;
    if not found then raise exception 'Line % is not part of sale %', v_sl_id, p_sale_id; end if;
    if v_sl.product_id is null then raise exception 'Only product lines can be returned'; end if;
    if v_sl.product_unit_id is not null then
      raise exception 'Returning individual (serialized) items is not supported yet';
    end if;

    select coalesce(sum(rl.qty), 0) into v_returned from refund_lines rl where rl.sale_line_id = v_sl_id;
    if v_qty > v_sl.qty - v_returned then
      raise exception 'Cannot return % of line (only % remaining)', v_qty, v_sl.qty - v_returned;
    end if;

    insert into refund_lines (refund_id, sale_line_id, qty, unit_price)
    values (v_refund_id, v_sl_id, v_qty, v_sl.unit_price);

    -- Returned stock goes back on hand.
    insert into inventory_txns (txn_type, product_id, qty, sale_id)
    values ('return', v_sl.product_id, v_qty, p_sale_id);

    v_sub := v_sub + v_qty * v_sl.unit_price;
  end loop;

  -- Tax on everything refunded so far (rounded once), minus tax already
  -- refunded, never beyond what the sale charged.
  v_tax   := greatest(0, least(round((v_prev_sub + v_sub) * v_rate / 100.0, 2), v_sale_tax) - v_prev_tax);
  v_total := v_sub + v_tax;
  update refunds set subtotal = v_sub, tax = v_tax where id = v_refund_id;

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;
      if v_amount is null or v_amount <= 0 then raise exception 'Refund amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid refund method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card refund needs a gift_card_id'; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_amount, 'refund', p_sale_id);
      elsif v_method = 'store_credit' then
        if v_customer is null then raise exception 'Store credit refund needs a customer on the sale'; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (v_customer, v_amount, 'refund', p_sale_id);
      end if;

      insert into refund_payments (refund_id, method, amount, gift_card_id) values (v_refund_id, v_method, v_amount, v_gc);
      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - v_total) > 0.005 then
    raise exception 'Refund payments (%) must equal the refund total (%)', v_paid, v_total;
  end if;

  -- Each payment type can give back what the sale took that way, net of earlier
  -- refunds. A type this refund sends more to than that is a payment-type
  -- change and needs a reason. (Only types this refund pays out to count, so an
  -- earlier, already-explained change doesn't follow later refunds around.)
  for v_by_method in
    select m.method,
           coalesce((select sum(sp.amount) from sale_payments sp
                      where sp.sale_id = p_sale_id and sp.method = m.method), 0) as taken,
           coalesce((select sum(rp.amount) from refund_payments rp join refunds r on r.id = rp.refund_id
                      where r.sale_id = p_sale_id and r.id <> v_refund_id and rp.method = m.method), 0) as given_back_before,
           coalesce((select sum(rp.amount) from refund_payments rp
                      where rp.refund_id = v_refund_id and rp.method = m.method), 0) as this_refund
    from (values ('cash'), ('credit'), ('gift_card'), ('store_credit')) as m(method)
  loop
    if v_by_method.this_refund > 0
       and v_by_method.this_refund > greatest(v_by_method.taken - v_by_method.given_back_before, 0) + 0.005 then
      v_changed := v_changed || v_by_method.method;
    end if;
  end loop;

  if cardinality(v_changed) > 0 then
    if coalesce(trim(p_method_change_reason), '') = '' then
      raise exception 'Refunding more to % than the sale took that way is a payment-type change; give a reason',
        array_to_string(v_changed, ', ');
    end if;
    update refunds set method_change_reason = trim(p_method_change_reason) where id = v_refund_id;
  end if;

  return v_refund_id;
end;
$$;

grant execute on function record_refund(uuid, jsonb, jsonb, text, text, text) to authenticated;

-- ----------------------------------------------------------------------------
-- 5. adjust_gift_card — same as 0026, but locks the card so a concurrent
--    redemption can't slip between the balance check and the adjustment.
-- ----------------------------------------------------------------------------
create or replace function adjust_gift_card(p_gift_card_id uuid, p_amount numeric, p_reason text)
returns numeric
language plpgsql
security invoker
as $$
declare
  v_bal numeric;
begin
  if p_amount is null or p_amount = 0 then
    raise exception 'Adjustment amount must be non-zero';
  end if;
  perform 1 from gift_cards where id = p_gift_card_id for update;
  if not found then
    raise exception 'Unknown gift card %', p_gift_card_id;
  end if;

  select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = p_gift_card_id;
  if v_bal + p_amount < 0 then
    raise exception 'Adjustment would make the balance negative (balance %, adjustment %)', v_bal, p_amount;
  end if;

  insert into gift_card_txns (gift_card_id, amount, reason)
  values (p_gift_card_id, p_amount, coalesce(nullif(trim(p_reason), ''), 'adjust'));

  v_bal := v_bal + p_amount;
  if v_bal <= 0 then
    update gift_cards set customer_id = null where id = p_gift_card_id;
  end if;
  return v_bal;
end;
$$;

grant execute on function adjust_gift_card(uuid, numeric, text) to authenticated;

-- >>> supabase/migrations/0039_admin_write_policies.sql
-- =============================================================================
-- 0039_admin_write_policies.sql — admin-only shop configuration (AceStock, 1C)
--
-- Settings, categories and attribute definitions were writable by every
-- signed-in user; only the web app's screens kept staff out. The database now
-- enforces it: everyone signed in can read them, only admins (is_admin()) can
-- change them. A staff account calling the API directly gets an error on
-- insert and changes nothing on update/delete.
--
-- Roles were already protected (profiles is read-only to clients; role changes
-- go through set_user_role, which checks is_admin()).
--
-- Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. settings (single row): read for all, update for admins only.
-- ----------------------------------------------------------------------------
drop policy if exists settings_authenticated_update on settings;
drop policy if exists settings_admin_update on settings;
create policy settings_admin_update on settings
  for update to authenticated
  using (is_admin())
  with check (is_admin());

-- ----------------------------------------------------------------------------
-- 2. categories and attribute_defs: read for all, write for admins only.
-- ----------------------------------------------------------------------------
do $$
declare
  tbl text;
begin
  foreach tbl in array array['categories', 'attribute_defs'] loop
    execute format('drop policy if exists %I on %I', tbl || '_authenticated_all', tbl);
    execute format('drop policy if exists %I on %I', tbl || '_authenticated_select', tbl);
    execute format('drop policy if exists %I on %I', tbl || '_admin_insert', tbl);
    execute format('drop policy if exists %I on %I', tbl || '_admin_update', tbl);
    execute format('drop policy if exists %I on %I', tbl || '_admin_delete', tbl);

    execute format(
      'create policy %I on %I for select to authenticated using (true)',
      tbl || '_authenticated_select', tbl);
    execute format(
      'create policy %I on %I for insert to authenticated with check (is_admin())',
      tbl || '_admin_insert', tbl);
    execute format(
      'create policy %I on %I for update to authenticated using (is_admin()) with check (is_admin())',
      tbl || '_admin_update', tbl);
    execute format(
      'create policy %I on %I for delete to authenticated using (is_admin())',
      tbl || '_admin_delete', tbl);
  end loop;
end $$;

-- >>> supabase/migrations/0040_ledger_lockdown.sql
-- =============================================================================
-- 0040_ledger_lockdown.sql — money history is write-only via server functions
--                            (AceStock, Phase 1C)
--
-- 1. Money and stock history can't be written directly. Sales, their lines,
--    payments, refunds, gift cards and their history, store credit history,
--    stock movements and racquet units are read-only to clients; every write
--    goes through a server function (record_sale, record_refund, receive_stock,
--    adjust_stock, receive_units, advance_string_job, cancel_string_job,
--    ensure_gift_card, add_store_credit, adjust_gift_card). Those functions now
--    run with the owner's rights (SECURITY DEFINER) so they can still write,
--    and only signed-in users may call them. Corrections are always new rows.
--
-- 2. String jobs: staff still create jobs and edit their strings, price, notes
--    and stringer directly, but status, payment, timestamps and attribution
--    only change through the server functions. New jobs must start "entered"
--    and are always attributed to the signed-in user who entered them.
--
-- 3. Views run with the reader's rights (security_invoker). They used to run
--    with the owner's, which bypassed row-level security: anyone with the
--    public anon key could list every gift card code and balance without
--    signing in. Signed-out users now have no access to tables, views or
--    functions at all (the app requires sign-in for everything).
--
-- 4. Every function pins search_path (public, then pg_temp last), so a caller
--    can't shadow a table the function uses.
--
-- Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Money and stock history: read-only to clients.
-- ----------------------------------------------------------------------------
do $$
declare
  tbl text;
  pol record;
begin
  foreach tbl in array array[
    'sales', 'sale_lines', 'sale_payments',
    'refunds', 'refund_lines', 'refund_payments',
    'gift_cards', 'gift_card_txns', 'store_credit_txns',
    'inventory_txns', 'product_units'
  ] loop
    execute format('revoke insert, update, delete, truncate on %I from authenticated, anon', tbl);

    -- Replace the old catch-all / insert policies with a single read policy.
    for pol in select policyname from pg_policies where schemaname = 'public' and tablename = tbl loop
      execute format('drop policy %I on %I', pol.policyname, tbl);
    end loop;
    execute format('create policy %I on %I for select to authenticated using (true)',
                   tbl || '_authenticated_select', tbl);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 2. String jobs: clients edit the job's content, never its lifecycle.
-- ----------------------------------------------------------------------------
revoke update, delete, truncate on string_jobs from authenticated, anon;
grant update (
  main_product_id, main_brand, main_string, main_specs, main_tension,
  cross_product_id, cross_brand, cross_string, cross_specs, cross_tension,
  price, notes, strung_by
) on string_jobs to authenticated;

-- A job entered directly by a client starts fresh and belongs to the caller.
-- (Server functions and maintenance run as the owner and aren't constrained.)
create or replace function guard_new_string_job()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if current_user in ('authenticated', 'anon') then
    if new.status <> 'entered'
       or new.paid_sale_id is not null
       or new.completed_at is not null or new.completed_by is not null
       or new.delivered_at is not null or new.delivered_by is not null
       or new.cancelled_at is not null or new.cancelled_by is not null then
      raise exception 'A new string job starts as entered and unpaid';
    end if;
    new.entered_by := auth.uid();
    new.entered_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists trg_guard_new_string_job on string_jobs;
create trigger trg_guard_new_string_job
  before insert on string_jobs
  for each row execute function guard_new_string_job();

-- ----------------------------------------------------------------------------
-- 3. Views use the reader's permissions and row-level security.
-- ----------------------------------------------------------------------------
do $$
declare
  v text;
begin
  foreach v in array array[
    'product_stock', 'product_available', 'string_committed',
    'gift_card_balance', 'customer_store_credit'
  ] loop
    execute format('alter view %I set (security_invoker = true)', v);
    execute format('revoke all on %I from anon', v);
    execute format('grant select on %I to authenticated', v);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 4. Functions: server functions that write money/stock history run as the
--    owner; every function pins search_path; signed-out users can call none.
-- ----------------------------------------------------------------------------
alter function record_sale(jsonb, uuid, jsonb, text)                 security definer;
alter function record_refund(uuid, jsonb, jsonb, text, text, text)   security definer;
alter function receive_stock(uuid, numeric, numeric, text, text)     security definer;
alter function adjust_stock(uuid, numeric, text)                     security definer;
alter function receive_units(uuid, jsonb)                            security definer;
alter function advance_string_job(uuid, text)                        security definer;
alter function cancel_string_job(uuid)                               security definer;
alter function ensure_gift_card(text, uuid)                          security definer;
alter function add_store_credit(uuid, numeric, text)                 security definer;
alter function adjust_gift_card(uuid, numeric, text)                 security definer;

do $$
declare
  fn record;
begin
  for fn in
    select p.oid::regprocedure as signature, p.prorettype = 'trigger'::regtype as is_trigger
    from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and p.prokind = 'f'
  loop
    execute format('alter function %s set search_path = public, pg_temp', fn.signature);
    execute format('revoke all on function %s from public, anon', fn.signature);
    if fn.is_trigger then
      -- Trigger functions only run as triggers, never as API calls.
      execute format('revoke all on function %s from authenticated', fn.signature);
    else
      execute format('grant execute on function %s to authenticated', fn.signature);
    end if;
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 5. Signed-out users get nothing, now and for objects created later.
--    (Row-level security already returned no rows to anon; this removes the
--    underlying grants too.)
-- ----------------------------------------------------------------------------
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;
alter default privileges in schema public revoke execute on functions from anon, public;

-- >>> supabase/migrations/0041_staff_only_access.sql
-- =============================================================================
-- 0041_staff_only_access.sql — only approved staff can use the shop's data
--                              (AceStock, foundation code review #1, #32)
--
-- Before: every new auth account got a 'staff' profile, every row-level
-- policy allowed any signed-in user, and the hosted projects allowed public
-- sign-up with no email confirmation. So anyone could create an account with
-- the public key and read customers, sales and gift cards or call the server
-- functions.
--
-- Now:
--   • New accounts start as 'pending', which has no access to anything except
--     its own profile row (so the app can say "waiting for approval").
--     Admins approve them (set_user_role → 'staff'), and can also remove an
--     account's access by setting it back to 'pending'.
--   • is_staff() — signed in AND role is staff or admin — replaces `true` in
--     every row-level policy. Admin-only policies keep is_admin().
--   • Server functions run with owner rights (0040), so row-level security
--     doesn't apply inside them. A statement-level trigger on every table
--     refuses writes by a signed-in account that isn't approved staff. That
--     covers every server function (and any added later) because each one
--     writes before it returns anything. Writes with no signed-in user
--     (migrations, the service role used by the create-staff Edge Function,
--     tests) are unaffected.
--   • set_user_role accepts 'pending' and locks the admin rows before the
--     last-admin check, so two admins can't demote each other at once (#32).
--
-- Staff accounts are now created by the admin-only create-staff Edge Function
-- (supabase/functions/create-staff); turn off public sign-up in each hosted
-- project (Authentication → Sign In / Providers).
--
-- Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Roles: 'pending' is the default and has no access.
-- ----------------------------------------------------------------------------
alter table profiles drop constraint if exists profiles_role_check;
alter table profiles
  add constraint profiles_role_check check (role in ('admin', 'staff', 'pending'));
alter table profiles alter column role set default 'pending';

-- ----------------------------------------------------------------------------
-- 2. is_staff() / require_staff()
-- ----------------------------------------------------------------------------
create or replace function is_staff()
returns boolean
language sql
security definer
stable
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from profiles where id = auth.uid() and role in ('staff', 'admin')
  );
$$;

-- Raise unless the caller is approved staff. No signed-in user (owner,
-- service role, migrations) passes.
create or replace function require_staff()
returns void
language plpgsql
security definer
stable
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is not null and not is_staff() then
    raise exception 'This account hasn''t been approved for staff access yet'
      using errcode = '42501';
  end if;
end;
$$;

revoke all on function is_staff() from public, anon;
revoke all on function require_staff() from public, anon;
grant execute on function is_staff() to authenticated;
grant execute on function require_staff() to authenticated;

-- ----------------------------------------------------------------------------
-- 3. Row-level policies: `true` becomes is_staff().
-- ----------------------------------------------------------------------------
do $$
declare
  pol record;
begin
  for pol in
    select tablename, policyname, qual, with_check
    from pg_policies
    where schemaname = 'public'
  loop
    if pol.qual = 'true' then
      execute format('alter policy %I on %I using (is_staff())', pol.policyname, pol.tablename);
    end if;
    if pol.with_check = 'true' then
      execute format('alter policy %I on %I with check (is_staff())', pol.policyname, pol.tablename);
    end if;
  end loop;
end $$;

-- A pending account can read only its own profile (to learn it's pending).
drop policy if exists profiles_authenticated_select on profiles;
create policy profiles_authenticated_select on profiles
  for select to authenticated
  using (is_staff() or id = auth.uid());

-- ----------------------------------------------------------------------------
-- 4. Writes by signed-in, non-staff accounts are refused on every table,
--    including writes made inside server functions.
-- ----------------------------------------------------------------------------
create or replace function enforce_staff_writer()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  perform require_staff();
  return null;  -- statement-level: the return value is ignored
end;
$$;

revoke all on function enforce_staff_writer() from public, anon, authenticated;

do $$
declare
  tbl text;
begin
  for tbl in select tablename from pg_tables where schemaname = 'public' loop
    execute format('drop trigger if exists trg_enforce_staff_writer on %I', tbl);
    execute format(
      'create trigger trg_enforce_staff_writer before insert or update or delete on %I '
      'for each statement execute function enforce_staff_writer()', tbl);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 5. set_user_role — same as 0028, plus 'pending' and a lock for the
--    last-admin check.
-- ----------------------------------------------------------------------------
create or replace function set_user_role(p_user_id uuid, p_role text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not is_admin() then
    raise exception 'Only an admin can change roles';
  end if;
  if p_role not in ('admin', 'staff', 'pending') then
    raise exception 'Invalid role "%"', p_role;
  end if;
  if not exists (select 1 from profiles where id = p_user_id) then
    raise exception 'Unknown user %', p_user_id;
  end if;

  -- Lock every admin row first, so two admins demoting each other at the
  -- same moment are serialized and the second sees the first's change.
  perform 1 from profiles where role = 'admin' order by id for update;

  if p_role <> 'admin'
     and exists (select 1 from profiles where id = p_user_id and role = 'admin')
     and (select count(*) from profiles where role = 'admin') <= 1 then
    raise exception 'Cannot demote the last admin';
  end if;

  update profiles set role = p_role where id = p_user_id;
end;
$$;

revoke all on function set_user_role(uuid, text) from public, anon;
grant execute on function set_user_role(uuid, text) to authenticated;

-- >>> supabase/migrations/0042_string_job_rules.sql
-- =============================================================================
-- 0042_string_job_rules.sql — the string-job lifecycle, enforced by the server
--                             (AceStock, foundation code review #2, #3, #10,
--                              #19 for strings, #20)
--
-- Before, several rules lived only in the screens:
--   • A paid job could be cancelled (#2). Refunds only cover product lines, so
--     the customer's payment had nowhere to go.
--   • advance_string_job ranked statuses entered 0 → complete 1 → delivered 2
--     and allowed "one step forward". A cancelled job ranked -1, so moving it
--     to 'entered' passed and revived it (#3).
--   • Neither function locked the job, so two "Complete" clicks at the same
--     moment both passed the status check and used up string twice (#3).
--   • A job could be delivered without being paid, its strings edited after
--     it was strung, and a job entered on a retired racquet or as a second
--     open job on the same racquet (#20).
--   • A string-job line on a sale could have qty > 1 (#10).
--   • A job could be entered with a partly chosen string (no color or gauge)
--     or no tension, so no catalog string was set aside or used up, and a
--     string with nothing available could be picked even with "block
--     overselling" on (#19).
--
-- Now:
--   1. advance_string_job allows only entered → complete and complete →
--      delivered, locks the job first, and refuses delivery until it's paid.
--   2. cancel_string_job locks the job and refuses a paid one.
--   3. A job's strings can't change once it's no longer 'entered' (price,
--      notes and stringer still can; a paid job's price stays locked by 0038).
--   4. A new job needs an active racquet with no other open (entered or
--      complete) job. A unique index backs this up.
--   5. Strings have two default attributes, color and gauge (material and
--      length are removed).
--   6. A job entered or edited by a signed-in user needs a catalog string for
--      mains and crosses, with every string attribute set, both active, and
--      both tensions. The job's brand, string name and attribute values are
--      copied from the catalog string. With "block overselling" on, a newly
--      chosen string must have at least one unit available (on hand minus
--      what other entered jobs have set aside); the string's row is locked
--      first so two registers can't both take the last unit.
--   7. record_sale charges a string job with qty 1 only.
--
-- The job's own price isn't forced onto the sale line yet: any line's price
-- can be changed at the register until recorded price overrides (Phase 2A).
--
-- Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. advance_string_job — explicit transitions, row lock, paid before delivery.
-- ----------------------------------------------------------------------------
create or replace function advance_string_job(
  p_job_id        uuid,
  p_target_status text
)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_current text;
  v_main    uuid;
  v_cross   uuid;
  v_paid    uuid;
begin
  perform require_staff();

  if p_target_status is null
     or p_target_status not in ('entered', 'complete', 'delivered', 'cancelled') then
    raise exception 'Invalid status "%"', p_target_status;
  end if;

  -- Lock the job so a second click (or register) waits, then sees this one's result.
  select status, main_product_id, cross_product_id, paid_sale_id
    into v_current, v_main, v_cross, v_paid
    from string_jobs where id = p_job_id
    for update;
  if not found then
    raise exception 'Unknown string job %', p_job_id;
  end if;

  if (v_current, p_target_status) not in (('entered', 'complete'), ('complete', 'delivered')) then
    raise exception 'Cannot move a string job from "%" to "%"', v_current, p_target_status;
  end if;
  if p_target_status = 'delivered' and v_paid is null then
    raise exception 'Take payment for this string job before marking it delivered';
  end if;

  update string_jobs
    set status       = p_target_status,
        completed_at = case when p_target_status = 'complete'  then now()      else completed_at end,
        completed_by = case when p_target_status = 'complete'  then auth.uid() else completed_by end,
        delivered_at = case when p_target_status = 'delivered' then now()      else delivered_at end,
        delivered_by = case when p_target_status = 'delivered' then auth.uid() else delivered_by end
  where id = p_job_id
    and status = v_current;

  -- Consume one unit of each distinct catalog string the job used.
  if p_target_status = 'complete' then
    insert into inventory_txns (txn_type, product_id, qty, note)
    select 'consume', pid, -1, 'String job completed'
    from (
      select distinct pid
      from (values (v_main), (v_cross)) as t(pid)
      where pid is not null
    ) d;
  end if;

  return p_target_status;
end;
$$;

-- ----------------------------------------------------------------------------
-- 2. cancel_string_job — row lock; a paid job can't be cancelled.
-- ----------------------------------------------------------------------------
create or replace function cancel_string_job(p_job_id uuid)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_current text;
  v_paid    uuid;
begin
  perform require_staff();

  select status, paid_sale_id into v_current, v_paid
    from string_jobs where id = p_job_id
    for update;
  if not found then
    raise exception 'Unknown string job %', p_job_id;
  end if;
  if v_current <> 'entered' then
    raise exception 'Only an entered job can be cancelled (this one is "%")', v_current;
  end if;
  if v_paid is not null then
    -- Refunds return product lines only, so cancelling would strand the payment.
    raise exception 'This string job has been paid, so it can''t be cancelled';
  end if;

  update string_jobs
     set status       = 'cancelled',
         cancelled_at = now(),
         cancelled_by = auth.uid()
   where id = p_job_id
     and status = 'entered';
  return 'cancelled';
end;
$$;

-- ----------------------------------------------------------------------------
-- 3. Strings are fixed once the job has been strung.
-- ----------------------------------------------------------------------------
create or replace function guard_strung_job_strings()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if old.status <> 'entered'
     and (new.main_product_id, new.main_brand, new.main_string, new.main_specs, new.main_tension,
          new.cross_product_id, new.cross_brand, new.cross_string, new.cross_specs, new.cross_tension)
         is distinct from
         (old.main_product_id, old.main_brand, old.main_string, old.main_specs, old.main_tension,
          old.cross_product_id, old.cross_brand, old.cross_string, old.cross_specs, old.cross_tension) then
    raise exception 'The strings on a % string job can''t be changed', old.status;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_guard_strung_job_strings on string_jobs;
create trigger trg_guard_strung_job_strings
  before update of main_product_id, main_brand, main_string, main_specs, main_tension,
                   cross_product_id, cross_brand, cross_string, cross_specs, cross_tension
  on string_jobs
  for each row execute function guard_strung_job_strings();

-- ----------------------------------------------------------------------------
-- 4. A new job needs an active racquet with no other open job.
--    Owner rights so the racquet row can be locked: two registers entering a
--    job for the same racquet at once are serialized and the second gets the
--    message below. The unique index is the backstop.
-- ----------------------------------------------------------------------------
create or replace function guard_string_job_racket()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_active boolean;
begin
  select is_active into v_active
    from customer_rackets where id = new.customer_racket_id
    for update;
  if not found then
    return new;  -- the foreign key reports an unknown racquet
  end if;
  if not v_active then
    raise exception 'This racquet has been retired, so it can''t get a new string job';
  end if;
  if new.status in ('entered', 'complete') and exists (
       select 1 from string_jobs
        where customer_racket_id = new.customer_racket_id
          and status in ('entered', 'complete')) then
    raise exception 'This racquet already has an open string job';
  end if;
  return new;
end;
$$;

revoke all on function guard_strung_job_strings() from public, anon, authenticated;
revoke all on function guard_string_job_racket() from public, anon, authenticated;

drop trigger if exists trg_guard_string_job_racket on string_jobs;
create trigger trg_guard_string_job_racket
  before insert on string_jobs
  for each row execute function guard_string_job_racket();

create unique index if not exists uq_string_jobs_one_open_per_racket
  on string_jobs (customer_racket_id)
  where status in ('entered', 'complete');

-- ----------------------------------------------------------------------------
-- 5. Default string attributes: color and gauge.
--    (Products keep any stored material / length values; they're just no
--    longer attributes, so they aren't shown or required.)
-- ----------------------------------------------------------------------------
delete from attribute_defs a
 using categories c
 where a.category_id = c.id
   and c.name = 'Strings'
   and a.name in ('material', 'length');

-- ----------------------------------------------------------------------------
-- 6. A job's strings are specific catalog strings, with tensions.
--    Applies to writes by a signed-in user (the app, and server functions they
--    call). Writes with no signed-in user (migrations, maintenance) skip it.
-- ----------------------------------------------------------------------------

-- One side of a job: check the catalog string, lock it, check availability,
-- and return the values to copy onto the job.
create or replace function string_job_side(
  p_product_id      uuid,
  p_job_id          uuid,
  p_check_available boolean,
  p_side            text
)
returns table (brand text, name text, specs jsonb)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_product   products%rowtype;
  v_category  text;
  v_label     text;
  v_missing   text;
  v_on_hand   numeric;
  v_committed integer;
begin
  perform require_staff();

  select p.* into v_product from products p where p.id = p_product_id for update;
  if not found then
    raise exception 'Unknown string %', p_product_id;
  end if;
  select c.name into v_category from categories c where c.id = v_product.category_id;
  v_label := trim(coalesce(v_product.brand || ' ', '') || v_product.name);

  if v_category is distinct from 'Strings' then
    raise exception 'The % (%) isn''t a string', p_side, v_label;
  end if;
  if not v_product.is_active then
    raise exception '% is no longer active, so it can''t be used for a string job', v_label;
  end if;

  -- Every string attribute (color, gauge, …) must be set on the catalog string.
  select string_agg(a.name, ', ' order by a.sort_order) into v_missing
    from attribute_defs a
    join categories c on c.id = a.category_id and c.name = 'Strings'
   where coalesce(v_product.attributes->>a.name, '') = '';
  if v_missing is not null then
    raise exception '% has no % set in the catalog', v_label, v_missing;
  end if;

  select coalesce(jsonb_object_agg(a.name, v_product.attributes->a.name), '{}'::jsonb) into specs
    from attribute_defs a
    join categories c on c.id = a.category_id and c.name = 'Strings';

  if p_check_available and coalesce((select block_oversell from settings where id), false) then
    select coalesce(sum(t.qty), 0) into v_on_hand from inventory_txns t where t.product_id = p_product_id;
    select count(*) into v_committed
      from string_jobs j
     where j.status = 'entered'
       and j.id is distinct from p_job_id
       and (j.main_product_id = p_product_id or j.cross_product_id = p_product_id);
    if v_on_hand - v_committed < 1 then
      raise exception '% (%) has none available', v_label,
        (select string_agg(value, ' ' order by key) from jsonb_each_text(specs));
    end if;
  end if;

  brand := v_product.brand;
  name  := v_product.name;
  return next;
end;
$$;

revoke all on function string_job_side(uuid, uuid, boolean, text) from public, anon;
grant execute on function string_job_side(uuid, uuid, boolean, text) to authenticated;

create or replace function guard_string_job_strings()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_main        record;
  v_cross       record;
  v_check_main  boolean;
  v_check_cross boolean;
begin
  -- Only entered jobs, and only writes by a signed-in user. A strung job's
  -- strings are refused by trg_guard_strung_job_strings.
  if auth.uid() is null or new.status <> 'entered' then
    return new;
  end if;

  if new.main_product_id is null or new.cross_product_id is null then
    raise exception 'Choose the mains and crosses strings from the catalog';
  end if;
  if new.main_tension is null or new.cross_tension is null then
    raise exception 'Enter the mains and crosses tension';
  end if;

  -- Availability is checked for strings the job doesn't already hold.
  v_check_main := tg_op = 'INSERT'
    or (new.main_product_id is distinct from old.main_product_id
        and new.main_product_id is distinct from old.cross_product_id);
  v_check_cross := new.cross_product_id <> new.main_product_id
    and (tg_op = 'INSERT'
         or (new.cross_product_id is distinct from old.main_product_id
             and new.cross_product_id is distinct from old.cross_product_id));

  -- Each call locks its string; take them in id order so two registers
  -- choosing the same pair of strings can't deadlock.
  if new.cross_product_id < new.main_product_id then
    select * into v_cross from string_job_side(new.cross_product_id, new.id, v_check_cross, 'crosses');
    select * into v_main  from string_job_side(new.main_product_id,  new.id, v_check_main,  'mains');
  else
    select * into v_main  from string_job_side(new.main_product_id,  new.id, v_check_main,  'mains');
    select * into v_cross from string_job_side(new.cross_product_id, new.id, v_check_cross, 'crosses');
  end if;

  new.main_brand   := v_main.brand;
  new.main_string  := v_main.name;
  new.main_specs   := v_main.specs;
  new.cross_brand  := v_cross.brand;
  new.cross_string := v_cross.name;
  new.cross_specs  := v_cross.specs;
  return new;
end;
$$;

revoke all on function guard_string_job_strings() from public, anon, authenticated;

drop trigger if exists trg_guard_string_job_strings on string_jobs;
create trigger trg_guard_string_job_strings
  before insert or update of main_product_id, main_brand, main_string, main_specs, main_tension,
                             cross_product_id, cross_brand, cross_string, cross_specs, cross_tension
  on string_jobs
  for each row execute function guard_string_job_strings();

-- ----------------------------------------------------------------------------
-- 7. record_sale — same as 0038, plus: a string-job line has qty 1.
--    (Owner rights and search_path as set by 0040.)
-- ----------------------------------------------------------------------------
create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_payments    jsonb,
  p_note        text
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sale_id     uuid := gen_random_uuid();
  v_line        jsonb;
  v_pay         jsonb;
  v_product     uuid;
  v_unit        uuid;
  v_serialized  boolean;
  v_job         uuid;
  v_job_status  text;
  v_job_paid    uuid;
  v_gc          uuid;
  v_qty         integer;
  v_price       numeric;
  v_line_total  numeric;
  v_subtotal    numeric := 0;
  v_taxable     numeric := 0;
  v_paid        numeric := 0;
  v_method      text;
  v_amount      numeric;
  v_bal         numeric;
  v_prev        numeric;
  v_onhand      numeric;
  v_count       integer;
  v_rate        numeric := 0;
  v_tax_string  boolean := false;
  v_block       boolean := false;
  v_tax         numeric := 0;
  v_unit_status text;
  v_unit_prod   uuid;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  select tax_rate, tax_stringing, block_oversell
    into v_rate, v_tax_string, v_block
    from settings where id = true;
  v_rate := coalesce(v_rate, 0);

  -- Lock everything whose balance or state this sale checks, in a fixed order,
  -- so a concurrent sale waits here and then sees this sale's effects.
  if v_block then
    perform 1 from products
     where id in (select nullif(l->>'product_id', '')::uuid from jsonb_array_elements(p_lines) l)
     order by id for update;
  end if;
  perform 1 from product_units
   where id in (select nullif(l->>'product_unit_id', '')::uuid from jsonb_array_elements(p_lines) l)
   order by id for update;
  perform 1 from string_jobs
   where id in (select nullif(l->>'string_job_id', '')::uuid from jsonb_array_elements(p_lines) l)
   order by id for update;
  perform 1 from gift_cards
   where id in (
     select nullif(l->>'gift_card_id', '')::uuid from jsonb_array_elements(p_lines) l
     union
     select nullif(p->>'gift_card_id', '')::uuid from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) p)
   order by id for update;
  if p_customer_id is not null and exists (
       select 1 from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) p
       where p->>'method' = 'store_credit') then
    perform 1 from customers where id = p_customer_id for update;
  end if;

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_product := nullif(v_line->>'product_id', '')::uuid;
    v_unit    := nullif(v_line->>'product_unit_id', '')::uuid;
    v_job     := nullif(v_line->>'string_job_id', '')::uuid;
    v_gc      := nullif(v_line->>'gift_card_id', '')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_qty is null or v_qty <= 0 then raise exception 'Sale line quantity must be positive'; end if;
    if v_price is null or v_price < 0 then raise exception 'Sale line price must be >= 0'; end if;
    if (case when v_product is null then 0 else 1 end)
     + (case when v_job is null then 0 else 1 end)
     + (case when v_gc is null then 0 else 1 end) <> 1 then
      raise exception 'A sale line must reference exactly one of product, string job, or gift card';
    end if;

    v_line_total := v_qty * v_price;

    if v_product is not null then
      select is_serialized into v_serialized from products where id = v_product;
      if v_serialized is null then
        raise exception 'Unknown product_id % in sale line', v_product;
      end if;

      if v_serialized then
        -- Serialized: sell one specific physical unit; no stock ledger txn.
        if v_unit is null then
          raise exception 'Product % is serialized; a product_unit_id is required', v_product;
        end if;
        if v_qty <> 1 then
          raise exception 'Serialized items sell one unit per line (qty must be 1)';
        end if;
        select status, product_id into v_unit_status, v_unit_prod
          from product_units where id = v_unit;
        if v_unit_status is null then raise exception 'Unknown product_unit_id %', v_unit; end if;
        if v_unit_prod <> v_product then raise exception 'Unit % does not belong to product %', v_unit, v_product; end if;
        if v_unit_status <> 'in_stock' then raise exception 'Unit % is not in stock (status %)', v_unit, v_unit_status; end if;

        insert into sale_lines (sale_id, product_id, product_unit_id, qty, unit_price)
        values (v_sale_id, v_product, v_unit, v_qty, v_price);
        update product_units
           set status = 'sold', sale_id = v_sale_id, customer_id = p_customer_id, updated_at = now()
         where id = v_unit;
      else
        -- Fungible: quantity ledger, optional oversell block.
        if v_block then
          select coalesce(sum(qty), 0) into v_onhand from inventory_txns where product_id = v_product;
          if v_onhand < v_qty then
            raise exception 'Not enough stock for product % (% on hand, % requested)', v_product, v_onhand, v_qty;
          end if;
        end if;
        insert into sale_lines (sale_id, product_id, qty, unit_price) values (v_sale_id, v_product, v_qty, v_price);
        insert into inventory_txns (txn_type, product_id, qty, sale_id) values ('sell', v_product, -v_qty, v_sale_id);
      end if;
      v_taxable := v_taxable + v_line_total;

    elsif v_job is not null then
      if v_qty <> 1 then
        raise exception 'A string job is charged once per line (qty must be 1)';
      end if;
      select status, paid_sale_id into v_job_status, v_job_paid from string_jobs where id = v_job;
      if not found then
        raise exception 'Unknown string_job_id % in sale line', v_job;
      end if;
      if v_job_status = 'cancelled' then
        raise exception 'String job % was cancelled and can''t be charged', v_job;
      end if;
      if v_job_paid = v_sale_id then
        raise exception 'String job % is on this ticket more than once', v_job;
      end if;
      if v_job_paid is not null then
        raise exception 'String job % is already paid (sale %)', v_job, v_job_paid;
      end if;
      insert into sale_lines (sale_id, string_job_id, qty, unit_price) values (v_sale_id, v_job, v_qty, v_price);
      update string_jobs set paid_sale_id = v_sale_id where id = v_job;
      if v_tax_string then v_taxable := v_taxable + v_line_total; end if;

    else
      if not exists (select 1 from gift_cards where id = v_gc) then
        raise exception 'Unknown gift_card_id % in sale line', v_gc;
      end if;
      select coalesce(sum(amount), 0) into v_prev from gift_card_txns where gift_card_id = v_gc;
      insert into sale_lines (sale_id, gift_card_id, qty, unit_price) values (v_sale_id, v_gc, v_qty, v_price);
      insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_line_total, 'load', v_sale_id);
      if v_prev <= 0 then update gift_cards set customer_id = p_customer_id where id = v_gc; end if;
    end if;

    v_subtotal := v_subtotal + v_line_total;
  end loop;

  v_tax := round(v_taxable * v_rate / 100.0, 2);

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;

      if v_amount is null or v_amount <= 0 then raise exception 'Payment amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid payment method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card payment needs a gift_card_id'; end if;
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal < v_amount then raise exception 'Gift card balance % is less than %', v_bal, v_amount; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount, gift_card_id) values (v_sale_id, 'gift_card', v_amount, v_gc);
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal <= 0 then update gift_cards set customer_id = null where id = v_gc; end if;
      elsif v_method = 'store_credit' then
        if p_customer_id is null then raise exception 'Store credit needs a customer on the sale'; end if;
        select coalesce(sum(amount), 0) into v_bal from store_credit_txns where customer_id = p_customer_id;
        if v_bal < v_amount then raise exception 'Store credit balance % is less than %', v_bal, v_amount; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (p_customer_id, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, 'store_credit', v_amount);
      else
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, v_method, v_amount);
      end if;

      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - (v_subtotal + v_tax)) > 0.005 then
    raise exception 'Payments (%) must equal the sale total (%)', v_paid, v_subtotal + v_tax;
  end if;

  select count(*) into v_count from sale_payments where sale_id = v_sale_id;
  update sales
     set subtotal = v_subtotal,
         tax = v_tax,
         tax_rate = v_rate,
         payment_method = case
           when v_count = 0 then null
           when v_count = 1 then (select method from sale_payments where sale_id = v_sale_id limit 1)
           else 'split'
         end
   where id = v_sale_id;

  return v_sale_id;
end;
$$;

-- ----------------------------------------------------------------------------
-- 8. Grants: signed-in staff only (as 0040/0041).
-- ----------------------------------------------------------------------------
revoke all on function advance_string_job(uuid, text)          from public, anon;
revoke all on function cancel_string_job(uuid)                 from public, anon;
revoke all on function record_sale(jsonb, uuid, jsonb, text)   from public, anon;
grant execute on function advance_string_job(uuid, text)        to authenticated;
grant execute on function cancel_string_job(uuid)               to authenticated;
grant execute on function record_sale(jsonb, uuid, jsonb, text) to authenticated;

-- >>> supabase/migrations/0043_paid_string_changes.sql
-- =============================================================================
-- 0043_paid_string_changes.sql — change the strings on a paid job and settle
--                                the difference (AceStock, commit 2b)
--
-- A job paid before it's strung can still have its strings changed. When the
-- new strings cost more or less, the difference is charged or given back in
-- the same step as the change, so a job's strings never drift from what was
-- paid:
--   • same price  → the strings just change;
--   • more        → a new sale with a "string change" line for the difference
--                   (plus stringing tax when that setting is on), paid by
--                   cash, credit and/or store credit;
--   • less        → a refund of the difference (plus the tax charged on it)
--                   against the sale(s) that paid for the job, newest first,
--                   as cash, credit and/or store credit. Each payment type can
--                   give back what that sale took that way; more needs a reason
--                   (the Phase 1B refund rule).
--
-- The difference is between the strings' catalog prices (labor + each distinct
-- string), recorded when the strings are chosen, so a discount given at the
-- register carries over and later catalog price changes don't count.
--
-- Supporting changes:
--   1. string_jobs.strings_price — the catalog price of the job's strings.
--   2. sale_lines.kind ('charge' | 'string_change') and sale_lines.taxable;
--      refund_lines.kind ('return' | 'string_change').
--   3. record_sale saves what was charged as the job's price and marks each
--      line taxed or not.
--   4. Refund tax and the payment-type rule move into shared helpers, used by
--      record_refund and by string-change give-backs. Refund tax now counts
--      only taxable refunded amounts (stringing may be untaxed).
--   5. A paid job's strings can change directly only at the same price; any
--      other change goes through change_paid_string_job.
--
-- Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Columns
-- ----------------------------------------------------------------------------
alter table string_jobs add column if not exists strings_price numeric(12, 2);

alter table sale_lines add column if not exists kind text not null default 'charge';
alter table sale_lines drop constraint if exists sale_lines_kind_check;
alter table sale_lines add constraint sale_lines_kind_check
  check (kind in ('charge', 'string_change') and (kind = 'charge' or string_job_id is not null));

alter table sale_lines add column if not exists taxable boolean;

alter table refund_lines add column if not exists kind text not null default 'return';
alter table refund_lines drop constraint if exists refund_lines_kind_check;
alter table refund_lines add constraint refund_lines_kind_check check (kind in ('return', 'string_change'));

-- ----------------------------------------------------------------------------
-- 2. The catalog price of a pair of strings: labor + each distinct string.
-- ----------------------------------------------------------------------------
create or replace function string_job_strings_price(p_main_product_id uuid, p_cross_product_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select round(
           coalesce((select stringing_labor from settings where id), 0)
         + coalesce((select sum(coalesce(p.sell_price, 0))
                       from products p
                      where p.id in (select distinct x
                                       from (values (p_main_product_id), (p_cross_product_id)) t(x)
                                      where x is not null)), 0),
         2);
$$;

revoke all on function string_job_strings_price(uuid, uuid) from public, anon;
grant execute on function string_job_strings_price(uuid, uuid) to authenticated;

-- ----------------------------------------------------------------------------
-- 3. Backfill
-- ----------------------------------------------------------------------------
-- Existing jobs: today's catalog price of their strings.
update string_jobs
   set strings_price = string_job_strings_price(main_product_id, cross_product_id)
 where strings_price is null;

-- Existing lines: products are taxed, gift card loads aren't; a stringing line
-- was taxed when its sale charged more tax than its product lines alone.
update sale_lines sl
   set taxable = case
     when sl.product_id is not null then true
     when sl.gift_card_id is not null then false
     else coalesce((
       select s.tax > round(coalesce((select sum(p.qty * p.unit_price) from sale_lines p
                                       where p.sale_id = s.id and p.product_id is not null), 0)
                            * coalesce(s.tax_rate, 0) / 100.0, 2) + 0.005
         from sales s where s.id = sl.sale_id), false)
   end
 where sl.taxable is null;

alter table sale_lines alter column taxable set default true;
alter table sale_lines alter column taxable set not null;

-- ----------------------------------------------------------------------------
-- 4. Shared refund rules
-- ----------------------------------------------------------------------------
-- Tax for a refund of p_taxable (the taxable part of it) from a sale: tax on
-- everything taxable refunded so far, rounded once, minus tax already refunded,
-- never beyond what the sale charged. p_refund_id is the refund being built
-- (its own lines and tax are left out of "so far").
create or replace function sale_refund_tax(p_sale_id uuid, p_taxable numeric, p_refund_id uuid)
returns numeric
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_rate      numeric;
  v_sale_tax  numeric;
  v_prev_sub  numeric;
  v_prev_tax  numeric;
begin
  select coalesce(tax_rate, 0), coalesce(tax, 0) into v_rate, v_sale_tax from sales where id = p_sale_id;
  select coalesce(sum(rl.qty * rl.unit_price), 0) into v_prev_sub
    from refund_lines rl
    join refunds r on r.id = rl.refund_id
    join sale_lines sl on sl.id = rl.sale_line_id
   where r.sale_id = p_sale_id and r.id is distinct from p_refund_id and sl.taxable;
  select coalesce(sum(tax), 0) into v_prev_tax
    from refunds where sale_id = p_sale_id and id is distinct from p_refund_id;
  return greatest(0, least(round((v_prev_sub + p_taxable) * v_rate / 100.0, 2), v_sale_tax) - v_prev_tax);
end;
$$;

-- What each payment type can still give back from a sale: what the sale took
-- that way, net of refunds other than p_refund_id.
create or replace function sale_refundable_by_method(p_sale_id uuid, p_refund_id uuid)
returns table (method text, refundable numeric)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select m.method,
         greatest(
           coalesce((select sum(sp.amount) from sale_payments sp
                      where sp.sale_id = p_sale_id and sp.method = m.method), 0)
         - coalesce((select sum(rp.amount) from refund_payments rp join refunds r on r.id = rp.refund_id
                      where r.sale_id = p_sale_id and r.id is distinct from p_refund_id and rp.method = m.method), 0),
           0)
    from (values ('cash'), ('credit'), ('gift_card'), ('store_credit')) as m(method);
$$;

-- The payment types a refund sends more to than the sale took that way (net of
-- earlier refunds): each is a payment-type change and needs a reason. Only
-- types this refund pays out to count, so an earlier, already-explained change
-- doesn't follow later refunds around.
create or replace function refund_method_overages(p_sale_id uuid, p_refund_id uuid)
returns text[]
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(array_agg(b.method order by b.method), '{}')
    from sale_refundable_by_method(p_sale_id, p_refund_id) b
   where (select coalesce(sum(rp.amount), 0) from refund_payments rp
           where rp.refund_id = p_refund_id and rp.method = b.method) > b.refundable + 0.005;
$$;

revoke all on function sale_refund_tax(uuid, numeric, uuid) from public, anon;
revoke all on function sale_refundable_by_method(uuid, uuid) from public, anon;
revoke all on function refund_method_overages(uuid, uuid) from public, anon;
grant execute on function sale_refund_tax(uuid, numeric, uuid) to authenticated;
grant execute on function sale_refundable_by_method(uuid, uuid) to authenticated;
grant execute on function refund_method_overages(uuid, uuid) to authenticated;

-- ----------------------------------------------------------------------------
-- 5. What a string change would cost: a quote, used by the screen to show the
--    amount and by change_paid_string_job to charge or give it back.
--
--    { "direction": "none" | "charge" | "give_back",
--      "amount": pre-tax difference, "tax": ..., "total": ...,
--      "old_price", "new_price", "customer_id": store credit goes here,
--      "refundable": { method: amount, ... }        -- give_back only
--      "allocations": [ { sale_id, sale_line_id, amount, tax }, ... ] }  -- newest sale first
-- ----------------------------------------------------------------------------
create or replace function string_change_quote(
  p_job_id           uuid,
  p_main_product_id  uuid,
  p_cross_product_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_job        string_jobs%rowtype;
  v_customer   uuid;
  v_old        numeric;
  v_new        numeric;
  v_diff       numeric;
  v_rate       numeric;
  v_tax_string boolean;
  v_tax        numeric;
  v_left       numeric;
  v_portion    numeric;
  v_portion_tx numeric;
  v_sale       record;
  v_allocs     jsonb := '[]'::jsonb;
  v_given      numeric := 0;
  v_given_tax  numeric := 0;
  v_refundable jsonb := '{}'::jsonb;
begin
  perform require_staff();

  select * into v_job from string_jobs where id = p_job_id;
  if not found then
    raise exception 'Unknown string job %', p_job_id;
  end if;
  if v_job.paid_sale_id is null or v_job.status <> 'entered' then
    raise exception 'Only a paid job that hasn''t been strung yet can change strings this way';
  end if;
  if p_main_product_id is null or p_cross_product_id is null then
    raise exception 'Choose the mains and crosses strings from the catalog';
  end if;

  -- Store credit goes to whoever paid for the job, else the racquet's owner.
  select coalesce(s.customer_id, r.customer_id) into v_customer
    from string_jobs j
    join customer_rackets r on r.id = j.customer_racket_id
    left join sales s on s.id = j.paid_sale_id
   where j.id = p_job_id;

  v_old  := coalesce(v_job.strings_price, string_job_strings_price(v_job.main_product_id, v_job.cross_product_id));
  v_new  := string_job_strings_price(p_main_product_id, p_cross_product_id);
  v_diff := v_new - v_old;

  if v_diff = 0 then
    return jsonb_build_object('direction', 'none', 'amount', 0, 'tax', 0, 'total', 0,
                              'old_price', v_old, 'new_price', v_new, 'customer_id', v_customer);
  end if;

  if v_diff > 0 then
    select coalesce(tax_rate, 0), coalesce(tax_stringing, false) into v_rate, v_tax_string from settings where id;
    v_tax := case when v_tax_string then round(v_diff * v_rate / 100.0, 2) else 0 end;
    return jsonb_build_object('direction', 'charge', 'amount', v_diff, 'tax', v_tax, 'total', v_diff + v_tax,
                              'old_price', v_old, 'new_price', v_new, 'customer_id', v_customer);
  end if;

  -- Give back -v_diff from the sales that paid for the job, newest first, never
  -- more than a sale took for this job (net of earlier give-backs).
  v_left := -v_diff;
  for v_sale in
    select sl.sale_id,
           (array_agg(sl.id order by sl.created_at desc))[1] as sale_line_id,
           bool_or(sl.taxable) as taxable,
           sum(sl.qty * sl.unit_price)
             - coalesce((select sum(rl.qty * rl.unit_price) from refund_lines rl
                          where rl.kind = 'string_change'
                            and rl.sale_line_id in (select x.id from sale_lines x
                                                     where x.sale_id = sl.sale_id and x.string_job_id = p_job_id)), 0)
             as job_net
      from sale_lines sl
      join sales s on s.id = sl.sale_id
     where sl.string_job_id = p_job_id
     group by sl.sale_id, s.sold_at
     order by s.sold_at desc
  loop
    exit when v_left <= 0;
    v_portion := least(v_left, greatest(v_sale.job_net, 0));
    continue when v_portion <= 0;
    v_portion_tx := sale_refund_tax(v_sale.sale_id, case when v_sale.taxable then v_portion else 0 end, null);
    v_allocs := v_allocs || jsonb_build_object('sale_id', v_sale.sale_id, 'sale_line_id', v_sale.sale_line_id,
                                               'amount', v_portion, 'tax', v_portion_tx);
    v_given := v_given + v_portion;
    v_given_tax := v_given_tax + v_portion_tx;
    v_left := v_left - v_portion;

    -- What each payment type can give back, summed over the sales used.
    select v_refundable || coalesce(jsonb_object_agg(b.method, coalesce((v_refundable->>b.method)::numeric, 0) + b.refundable), '{}'::jsonb)
      into v_refundable
      from sale_refundable_by_method(v_sale.sale_id, null) b;
  end loop;

  return jsonb_build_object('direction', 'give_back', 'amount', v_given, 'tax', v_given_tax,
                            'total', v_given + v_given_tax, 'old_price', v_old, 'new_price', v_new,
                            'customer_id', v_customer, 'refundable', v_refundable, 'allocations', v_allocs);
end;
$$;

revoke all on function string_change_quote(uuid, uuid, uuid) from public, anon;
grant execute on function string_change_quote(uuid, uuid, uuid) to authenticated;

-- ----------------------------------------------------------------------------
-- 6. change_paid_string_job — change a paid, not-yet-strung job's strings and
--    settle the difference in one step. Returns
--    { direction, amount, tax, total, sale_id | refund_ids }.
-- ----------------------------------------------------------------------------
create or replace function change_paid_string_job(
  p_job_id           uuid,
  p_main_product_id  uuid,
  p_cross_product_id uuid,
  p_main_tension     numeric,
  p_cross_tension    numeric,
  p_payments         jsonb,
  p_reason           text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_quote      jsonb;
  v_direction  text;
  v_amount     numeric;
  v_tax        numeric;
  v_total      numeric;
  v_customer   uuid;
  v_pay        jsonb;
  v_methods    text[] := '{}';
  v_amounts    numeric[] := '{}';
  v_paid       numeric := 0;
  v_i          integer;
  v_sale_id    uuid;
  v_rate       numeric;
  v_taxable    boolean;
  v_count      integer;
  v_balance    numeric;
  v_alloc      jsonb;
  v_refund_id  uuid;
  v_refund_ids uuid[] := '{}';
  v_sale_cust  uuid;
  v_need       numeric;
  v_take       numeric;
  v_changed    text[];
begin
  perform require_staff();

  -- Lock the job, then the sales that paid for it (refunds of a sale run one
  -- at a time), so the quote below can't be raced.
  perform 1 from string_jobs where id = p_job_id for update;
  if not found then
    raise exception 'Unknown string job %', p_job_id;
  end if;
  perform 1 from sales
   where id in (select sale_id from sale_lines where string_job_id = p_job_id)
   order by id for update;

  v_quote     := string_change_quote(p_job_id, p_main_product_id, p_cross_product_id);
  v_direction := v_quote->>'direction';
  v_amount    := (v_quote->>'amount')::numeric;
  v_tax       := (v_quote->>'tax')::numeric;
  v_total     := (v_quote->>'total')::numeric;
  v_customer  := (v_quote->>'customer_id')::uuid;

  -- Payments: cash, credit and/or store credit, adding up to the total.
  for v_pay in select * from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb))
  loop
    if (v_pay->>'amount')::numeric is null or (v_pay->>'amount')::numeric <= 0 then
      raise exception 'Payment amount must be positive';
    end if;
    if (v_pay->>'method') is null or (v_pay->>'method') not in ('cash', 'credit', 'store_credit') then
      raise exception 'A string change is paid or given back as cash, credit or store credit';
    end if;
    v_methods := v_methods || (v_pay->>'method');
    v_amounts := v_amounts || (v_pay->>'amount')::numeric;
    v_paid := v_paid + (v_pay->>'amount')::numeric;
  end loop;
  if abs(v_paid - v_total) > 0.005 then
    raise exception 'Payments (%) must equal the string change total (%)', v_paid, v_total;
  end if;
  if 'store_credit' = any (v_methods) and v_customer is null then
    raise exception 'Store credit needs a customer';
  end if;

  -- Change the strings. The entry rules apply (catalog strings, tensions,
  -- availability); the flag lets this paid job's price move by the difference.
  perform set_config('acestock.string_change_job', p_job_id::text, true);
  update string_jobs
     set main_product_id  = p_main_product_id,
         cross_product_id = p_cross_product_id,
         main_tension     = p_main_tension,
         cross_tension    = p_cross_tension,
         price = coalesce(price, 0) + case v_direction when 'charge' then v_amount
                                                       when 'give_back' then -v_amount
                                                       else 0 end
   where id = p_job_id;
  perform set_config('acestock.string_change_job', '', true);

  if v_direction = 'charge' then
    if 'store_credit' = any (v_methods) then
      perform 1 from customers where id = v_customer for update;
      select coalesce(sum(amount), 0) into v_balance from store_credit_txns where customer_id = v_customer;
      if v_balance < (select coalesce(sum(a), 0) from unnest(v_amounts, v_methods) as u(a, m) where m = 'store_credit') then
        raise exception 'Store credit balance % is less than the store credit used', v_balance;
      end if;
    end if;

    select coalesce(tax_rate, 0), coalesce(tax_stringing, false) into v_rate, v_taxable from settings where id;
    v_sale_id := gen_random_uuid();
    insert into sales (id, customer_id, subtotal, tax, tax_rate, note)
    values (v_sale_id, v_customer, v_amount, v_tax, v_rate, 'String change');
    insert into sale_lines (sale_id, string_job_id, qty, unit_price, kind, taxable)
    values (v_sale_id, p_job_id, 1, v_amount, 'string_change', v_taxable);

    for v_i in 1 .. coalesce(array_length(v_methods, 1), 0)
    loop
      insert into sale_payments (sale_id, method, amount) values (v_sale_id, v_methods[v_i], v_amounts[v_i]);
      if v_methods[v_i] = 'store_credit' then
        insert into store_credit_txns (customer_id, amount, reason, sale_id)
        values (v_customer, -v_amounts[v_i], 'redeem', v_sale_id);
      end if;
    end loop;

    select count(*) into v_count from sale_payments where sale_id = v_sale_id;
    update sales
       set payment_method = case when v_count = 1
                                 then (select method from sale_payments where sale_id = v_sale_id limit 1)
                                 else 'split' end
     where id = v_sale_id;

    return jsonb_build_object('direction', 'charge', 'amount', v_amount, 'tax', v_tax, 'total', v_total,
                              'sale_id', v_sale_id);
  end if;

  if v_direction = 'give_back' then
    -- One refund per paying sale (newest first); the payments are spread over
    -- them in the order given.
    v_i := 1;
    for v_alloc in select * from jsonb_array_elements(v_quote->'allocations')
    loop
      v_refund_id := gen_random_uuid();
      select customer_id into v_sale_cust from sales where id = (v_alloc->>'sale_id')::uuid;
      insert into refunds (id, sale_id, subtotal, tax, reason)
      values (v_refund_id, (v_alloc->>'sale_id')::uuid, (v_alloc->>'amount')::numeric, (v_alloc->>'tax')::numeric,
              'String change');
      insert into refund_lines (refund_id, sale_line_id, qty, unit_price, kind)
      values (v_refund_id, (v_alloc->>'sale_line_id')::uuid, 1, (v_alloc->>'amount')::numeric, 'string_change');

      v_need := (v_alloc->>'amount')::numeric + (v_alloc->>'tax')::numeric;
      while v_need > 0.005 and v_i <= array_length(v_methods, 1)
      loop
        v_take := least(v_need, v_amounts[v_i]);
        insert into refund_payments (refund_id, method, amount) values (v_refund_id, v_methods[v_i], v_take);
        if v_methods[v_i] = 'store_credit' then
          insert into store_credit_txns (customer_id, amount, reason, sale_id)
          values (coalesce(v_sale_cust, v_customer), v_take, 'refund', (v_alloc->>'sale_id')::uuid);
        end if;
        v_need := v_need - v_take;
        v_amounts[v_i] := v_amounts[v_i] - v_take;
        if v_amounts[v_i] <= 0.005 then
          v_i := v_i + 1;
        end if;
      end loop;

      v_changed := refund_method_overages((v_alloc->>'sale_id')::uuid, v_refund_id);
      if cardinality(v_changed) > 0 then
        if coalesce(trim(p_reason), '') = '' then
          raise exception 'Giving back more as % than the sale took that way is a payment-type change; give a reason',
            array_to_string(v_changed, ', ');
        end if;
        update refunds set method_change_reason = trim(p_reason) where id = v_refund_id;
      end if;
      v_refund_ids := v_refund_ids || v_refund_id;
    end loop;

    return jsonb_build_object('direction', 'give_back', 'amount', v_amount, 'tax', v_tax, 'total', v_total,
                              'refund_ids', to_jsonb(v_refund_ids));
  end if;

  return jsonb_build_object('direction', 'none', 'amount', 0, 'tax', 0, 'total', 0);
end;
$$;

revoke all on function change_paid_string_job(uuid, uuid, uuid, numeric, numeric, jsonb, text) from public, anon;
grant execute on function change_paid_string_job(uuid, uuid, uuid, numeric, numeric, jsonb, text) to authenticated;

-- ----------------------------------------------------------------------------
-- 7. A paid job's price changes only through change_paid_string_job.
--    (Same as 0038 otherwise.)
-- ----------------------------------------------------------------------------
create or replace function guard_paid_string_job()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if old.paid_sale_id is not null then
    if new.paid_sale_id is distinct from old.paid_sale_id then
      raise exception 'String job % is already paid by sale %', old.id, old.paid_sale_id;
    end if;
    if new.price is distinct from old.price
       and coalesce(current_setting('acestock.string_change_job', true), '') <> old.id::text then
      raise exception 'The price of a paid string job can''t be changed';
    end if;
  end if;
  return new;
end;
$$;

-- ----------------------------------------------------------------------------
-- 8. The entry rules (0042) also record the strings' catalog price, and keep a
--    paid job's strings at the price that was paid unless the change goes
--    through change_paid_string_job.
-- ----------------------------------------------------------------------------
create or replace function guard_string_job_strings()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_main          record;
  v_cross         record;
  v_check_main    boolean;
  v_check_cross   boolean;
  v_strings_moved boolean;
  v_new_price     numeric;
  v_old_price     numeric;
begin
  -- Only entered jobs, and only writes by a signed-in user. A strung job's
  -- strings are refused by trg_guard_strung_job_strings.
  if auth.uid() is null or new.status <> 'entered' then
    return new;
  end if;

  if new.main_product_id is null or new.cross_product_id is null then
    raise exception 'Choose the mains and crosses strings from the catalog';
  end if;
  if new.main_tension is null or new.cross_tension is null then
    raise exception 'Enter the mains and crosses tension';
  end if;

  -- Availability is checked for strings the job doesn't already hold.
  v_check_main := tg_op = 'INSERT'
    or (new.main_product_id is distinct from old.main_product_id
        and new.main_product_id is distinct from old.cross_product_id);
  v_check_cross := new.cross_product_id <> new.main_product_id
    and (tg_op = 'INSERT'
         or (new.cross_product_id is distinct from old.main_product_id
             and new.cross_product_id is distinct from old.cross_product_id));

  -- Each call locks its string; take them in id order so two registers
  -- choosing the same pair of strings can't deadlock.
  if new.cross_product_id < new.main_product_id then
    select * into v_cross from string_job_side(new.cross_product_id, new.id, v_check_cross, 'crosses');
    select * into v_main  from string_job_side(new.main_product_id,  new.id, v_check_main,  'mains');
  else
    select * into v_main  from string_job_side(new.main_product_id,  new.id, v_check_main,  'mains');
    select * into v_cross from string_job_side(new.cross_product_id, new.id, v_check_cross, 'crosses');
  end if;

  new.main_brand   := v_main.brand;
  new.main_string  := v_main.name;
  new.main_specs   := v_main.specs;
  new.cross_brand  := v_cross.brand;
  new.cross_string := v_cross.name;
  new.cross_specs  := v_cross.specs;

  -- Record the strings' catalog price when they're chosen (not on a
  -- tension-only edit, so later catalog price changes don't count).
  v_strings_moved := tg_op = 'INSERT'
    or (new.main_product_id, new.cross_product_id) is distinct from (old.main_product_id, old.cross_product_id);
  if v_strings_moved then
    v_new_price := string_job_strings_price(new.main_product_id, new.cross_product_id);
    if tg_op = 'UPDATE' and old.paid_sale_id is not null
       and coalesce(current_setting('acestock.string_change_job', true), '') <> old.id::text then
      v_old_price := coalesce(old.strings_price, string_job_strings_price(old.main_product_id, old.cross_product_id));
      if v_new_price <> v_old_price then
        raise exception 'This job was paid for strings costing $%; the new strings cost $%. Use String change to settle the difference',
          to_char(v_old_price, 'FM999999990.00'), to_char(v_new_price, 'FM999999990.00');
      end if;
    end if;
    new.strings_price := v_new_price;
  end if;
  return new;
end;
$$;

revoke all on function guard_paid_string_job() from public, anon, authenticated;
revoke all on function guard_string_job_strings() from public, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 9. record_sale — same as 0042, plus: a paid job's price becomes what was
--    charged, and each line records whether it was taxed.
-- ----------------------------------------------------------------------------
create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_payments    jsonb,
  p_note        text
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sale_id     uuid := gen_random_uuid();
  v_line        jsonb;
  v_pay         jsonb;
  v_product     uuid;
  v_unit        uuid;
  v_serialized  boolean;
  v_job         uuid;
  v_job_status  text;
  v_job_paid    uuid;
  v_gc          uuid;
  v_qty         integer;
  v_price       numeric;
  v_line_total  numeric;
  v_subtotal    numeric := 0;
  v_taxable     numeric := 0;
  v_paid        numeric := 0;
  v_method      text;
  v_amount      numeric;
  v_bal         numeric;
  v_prev        numeric;
  v_onhand      numeric;
  v_count       integer;
  v_rate        numeric := 0;
  v_tax_string  boolean := false;
  v_block       boolean := false;
  v_tax         numeric := 0;
  v_unit_status text;
  v_unit_prod   uuid;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  select tax_rate, tax_stringing, block_oversell
    into v_rate, v_tax_string, v_block
    from settings where id = true;
  v_rate := coalesce(v_rate, 0);

  -- Lock everything whose balance or state this sale checks, in a fixed order,
  -- so a concurrent sale waits here and then sees this sale's effects.
  if v_block then
    perform 1 from products
     where id in (select nullif(l->>'product_id', '')::uuid from jsonb_array_elements(p_lines) l)
     order by id for update;
  end if;
  perform 1 from product_units
   where id in (select nullif(l->>'product_unit_id', '')::uuid from jsonb_array_elements(p_lines) l)
   order by id for update;
  perform 1 from string_jobs
   where id in (select nullif(l->>'string_job_id', '')::uuid from jsonb_array_elements(p_lines) l)
   order by id for update;
  perform 1 from gift_cards
   where id in (
     select nullif(l->>'gift_card_id', '')::uuid from jsonb_array_elements(p_lines) l
     union
     select nullif(p->>'gift_card_id', '')::uuid from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) p)
   order by id for update;
  if p_customer_id is not null and exists (
       select 1 from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) p
       where p->>'method' = 'store_credit') then
    perform 1 from customers where id = p_customer_id for update;
  end if;

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_product := nullif(v_line->>'product_id', '')::uuid;
    v_unit    := nullif(v_line->>'product_unit_id', '')::uuid;
    v_job     := nullif(v_line->>'string_job_id', '')::uuid;
    v_gc      := nullif(v_line->>'gift_card_id', '')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_qty is null or v_qty <= 0 then raise exception 'Sale line quantity must be positive'; end if;
    if v_price is null or v_price < 0 then raise exception 'Sale line price must be >= 0'; end if;
    if (case when v_product is null then 0 else 1 end)
     + (case when v_job is null then 0 else 1 end)
     + (case when v_gc is null then 0 else 1 end) <> 1 then
      raise exception 'A sale line must reference exactly one of product, string job, or gift card';
    end if;

    v_line_total := v_qty * v_price;

    if v_product is not null then
      select is_serialized into v_serialized from products where id = v_product;
      if v_serialized is null then
        raise exception 'Unknown product_id % in sale line', v_product;
      end if;

      if v_serialized then
        -- Serialized: sell one specific physical unit; no stock ledger txn.
        if v_unit is null then
          raise exception 'Product % is serialized; a product_unit_id is required', v_product;
        end if;
        if v_qty <> 1 then
          raise exception 'Serialized items sell one unit per line (qty must be 1)';
        end if;
        select status, product_id into v_unit_status, v_unit_prod
          from product_units where id = v_unit;
        if v_unit_status is null then raise exception 'Unknown product_unit_id %', v_unit; end if;
        if v_unit_prod <> v_product then raise exception 'Unit % does not belong to product %', v_unit, v_product; end if;
        if v_unit_status <> 'in_stock' then raise exception 'Unit % is not in stock (status %)', v_unit, v_unit_status; end if;

        insert into sale_lines (sale_id, product_id, product_unit_id, qty, unit_price, taxable)
        values (v_sale_id, v_product, v_unit, v_qty, v_price, true);
        update product_units
           set status = 'sold', sale_id = v_sale_id, customer_id = p_customer_id, updated_at = now()
         where id = v_unit;
      else
        -- Fungible: quantity ledger, optional oversell block.
        if v_block then
          select coalesce(sum(qty), 0) into v_onhand from inventory_txns where product_id = v_product;
          if v_onhand < v_qty then
            raise exception 'Not enough stock for product % (% on hand, % requested)', v_product, v_onhand, v_qty;
          end if;
        end if;
        insert into sale_lines (sale_id, product_id, qty, unit_price, taxable) values (v_sale_id, v_product, v_qty, v_price, true);
        insert into inventory_txns (txn_type, product_id, qty, sale_id) values ('sell', v_product, -v_qty, v_sale_id);
      end if;
      v_taxable := v_taxable + v_line_total;

    elsif v_job is not null then
      if v_qty <> 1 then
        raise exception 'A string job is charged once per line (qty must be 1)';
      end if;
      select status, paid_sale_id into v_job_status, v_job_paid from string_jobs where id = v_job;
      if not found then
        raise exception 'Unknown string_job_id % in sale line', v_job;
      end if;
      if v_job_status = 'cancelled' then
        raise exception 'String job % was cancelled and can''t be charged', v_job;
      end if;
      if v_job_paid = v_sale_id then
        raise exception 'String job % is on this ticket more than once', v_job;
      end if;
      if v_job_paid is not null then
        raise exception 'String job % is already paid (sale %)', v_job, v_job_paid;
      end if;
      insert into sale_lines (sale_id, string_job_id, qty, unit_price, taxable)
      values (v_sale_id, v_job, v_qty, v_price, v_tax_string);
      -- The job's price becomes what was actually charged (a register discount sticks).
      update string_jobs set paid_sale_id = v_sale_id, price = v_price where id = v_job;
      if v_tax_string then v_taxable := v_taxable + v_line_total; end if;

    else
      if not exists (select 1 from gift_cards where id = v_gc) then
        raise exception 'Unknown gift_card_id % in sale line', v_gc;
      end if;
      select coalesce(sum(amount), 0) into v_prev from gift_card_txns where gift_card_id = v_gc;
      insert into sale_lines (sale_id, gift_card_id, qty, unit_price, taxable) values (v_sale_id, v_gc, v_qty, v_price, false);
      insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_line_total, 'load', v_sale_id);
      if v_prev <= 0 then update gift_cards set customer_id = p_customer_id where id = v_gc; end if;
    end if;

    v_subtotal := v_subtotal + v_line_total;
  end loop;

  v_tax := round(v_taxable * v_rate / 100.0, 2);

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;

      if v_amount is null or v_amount <= 0 then raise exception 'Payment amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid payment method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card payment needs a gift_card_id'; end if;
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal < v_amount then raise exception 'Gift card balance % is less than %', v_bal, v_amount; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount, gift_card_id) values (v_sale_id, 'gift_card', v_amount, v_gc);
        select coalesce(sum(amount), 0) into v_bal from gift_card_txns where gift_card_id = v_gc;
        if v_bal <= 0 then update gift_cards set customer_id = null where id = v_gc; end if;
      elsif v_method = 'store_credit' then
        if p_customer_id is null then raise exception 'Store credit needs a customer on the sale'; end if;
        select coalesce(sum(amount), 0) into v_bal from store_credit_txns where customer_id = p_customer_id;
        if v_bal < v_amount then raise exception 'Store credit balance % is less than %', v_bal, v_amount; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (p_customer_id, -v_amount, 'redeem', v_sale_id);
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, 'store_credit', v_amount);
      else
        insert into sale_payments (sale_id, method, amount) values (v_sale_id, v_method, v_amount);
      end if;

      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - (v_subtotal + v_tax)) > 0.005 then
    raise exception 'Payments (%) must equal the sale total (%)', v_paid, v_subtotal + v_tax;
  end if;

  select count(*) into v_count from sale_payments where sale_id = v_sale_id;
  update sales
     set subtotal = v_subtotal,
         tax = v_tax,
         tax_rate = v_rate,
         payment_method = case
           when v_count = 0 then null
           when v_count = 1 then (select method from sale_payments where sale_id = v_sale_id limit 1)
           else 'split'
         end
   where id = v_sale_id;

  return v_sale_id;
end;
$$;

-- ----------------------------------------------------------------------------
-- 10. record_refund — same as 0038 (owner rights per 0040), plus: tax and the
--     payment-type rule come from the shared helpers, so tax counts only
--     taxable refunded amounts; returned quantities count product returns only.
-- ----------------------------------------------------------------------------
create or replace function record_refund(
  p_sale_id              uuid,
  p_lines                jsonb,
  p_payments             jsonb,
  p_reason               text,
  p_note                 text,
  p_method_change_reason text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_refund_id  uuid := gen_random_uuid();
  v_customer   uuid;
  v_rate       numeric := 0;
  v_sale_tax   numeric := 0;
  v_line       jsonb;
  v_pay        jsonb;
  v_sl_id      uuid;
  v_qty        integer;
  v_sl         record;
  v_returned   integer;
  v_sub        numeric := 0;
  v_tax        numeric := 0;
  v_total      numeric := 0;
  v_paid       numeric := 0;
  v_method     text;
  v_amount     numeric;
  v_gc         uuid;
  v_changed    text[];
begin
  -- Locking the sale serializes refunds of the same sale, so remaining
  -- quantities, tax and per-method amounts below can't be raced.
  select customer_id, coalesce(tax_rate, 0), coalesce(tax, 0)
    into v_customer, v_rate, v_sale_tax
    from sales where id = p_sale_id
    for update;
  if not found then raise exception 'Unknown sale %', p_sale_id; end if;
  if p_lines is null or jsonb_array_length(p_lines) = 0 then raise exception 'A refund needs at least one line'; end if;

  insert into refunds (id, sale_id, reason, note)
  values (v_refund_id, p_sale_id, nullif(trim(p_reason), ''), nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_sl_id := (v_line->>'sale_line_id')::uuid;
    v_qty   := (v_line->>'qty')::integer;
    if v_qty is null or v_qty <= 0 then raise exception 'Return quantity must be positive'; end if;

    select * into v_sl from sale_lines where id = v_sl_id and sale_id = p_sale_id;
    if not found then raise exception 'Line % is not part of sale %', v_sl_id, p_sale_id; end if;
    if v_sl.product_id is null then raise exception 'Only product lines can be returned'; end if;
    if v_sl.product_unit_id is not null then
      raise exception 'Returning individual (serialized) items is not supported yet';
    end if;

    select coalesce(sum(rl.qty), 0) into v_returned from refund_lines rl where rl.sale_line_id = v_sl_id and rl.kind = 'return';
    if v_qty > v_sl.qty - v_returned then
      raise exception 'Cannot return % of line (only % remaining)', v_qty, v_sl.qty - v_returned;
    end if;

    insert into refund_lines (refund_id, sale_line_id, qty, unit_price)
    values (v_refund_id, v_sl_id, v_qty, v_sl.unit_price);

    -- Returned stock goes back on hand.
    insert into inventory_txns (txn_type, product_id, qty, sale_id)
    values ('return', v_sl.product_id, v_qty, p_sale_id);

    v_sub := v_sub + v_qty * v_sl.unit_price;
  end loop;

  -- Tax on everything taxable refunded so far (rounded once), minus tax
  -- already refunded, never beyond what the sale charged. Products are taxed.
  v_tax   := sale_refund_tax(p_sale_id, v_sub, v_refund_id);
  v_total := v_sub + v_tax;
  update refunds set subtotal = v_sub, tax = v_tax where id = v_refund_id;

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments)
    loop
      v_method := v_pay->>'method';
      v_amount := (v_pay->>'amount')::numeric;
      v_gc     := nullif(v_pay->>'gift_card_id', '')::uuid;
      if v_amount is null or v_amount <= 0 then raise exception 'Refund amount must be positive'; end if;
      if v_method not in ('cash', 'credit', 'gift_card', 'store_credit') then raise exception 'Invalid refund method "%"', v_method; end if;

      if v_method = 'gift_card' then
        if v_gc is null then raise exception 'Gift card refund needs a gift_card_id'; end if;
        insert into gift_card_txns (gift_card_id, amount, reason, sale_id) values (v_gc, v_amount, 'refund', p_sale_id);
      elsif v_method = 'store_credit' then
        if v_customer is null then raise exception 'Store credit refund needs a customer on the sale'; end if;
        insert into store_credit_txns (customer_id, amount, reason, sale_id) values (v_customer, v_amount, 'refund', p_sale_id);
      end if;

      insert into refund_payments (refund_id, method, amount, gift_card_id) values (v_refund_id, v_method, v_amount, v_gc);
      v_paid := v_paid + v_amount;
    end loop;
  end if;

  if abs(v_paid - v_total) > 0.005 then
    raise exception 'Refund payments (%) must equal the refund total (%)', v_paid, v_total;
  end if;

  -- A payment type this refund sends more to than the sale took that way (net
  -- of earlier refunds) is a payment-type change and needs a reason.
  v_changed := refund_method_overages(p_sale_id, v_refund_id);

  if cardinality(v_changed) > 0 then
    if coalesce(trim(p_method_change_reason), '') = '' then
      raise exception 'Refunding more to % than the sale took that way is a payment-type change; give a reason',
        array_to_string(v_changed, ', ');
    end if;
    update refunds set method_change_reason = trim(p_method_change_reason) where id = v_refund_id;
  end if;

  return v_refund_id;
end;
$$;

-- ----------------------------------------------------------------------------
-- 11. Grants: signed-in staff only (as 0040/0041).
-- ----------------------------------------------------------------------------
revoke all on function record_sale(jsonb, uuid, jsonb, text) from public, anon;
revoke all on function record_refund(uuid, jsonb, jsonb, text, text, text) from public, anon;
grant execute on function record_sale(jsonb, uuid, jsonb, text) to authenticated;
grant execute on function record_refund(uuid, jsonb, jsonb, text, text, text) to authenticated;

-- >>> supabase/migrations/0044_staff_only_helpers.sql
-- =============================================================================
-- 0044_staff_only_helpers.sql — owner-rights helpers are staff-only
--                               (AceStock, commit 2c)
--
-- 0043 added four helper functions that run with owner rights (so row-level
-- security doesn't apply inside them) and were callable by any signed-in
-- account, including one still waiting for approval:
--   • sale_refund_tax, sale_refundable_by_method, refund_method_overages —
--     given a sale's id, they reveal what it took by payment type and its tax;
--   • string_job_strings_price — a pair of strings' price.
-- They change nothing, but "only approved staff can read the shop's data"
-- (0041) should hold for every function.
--
-- Now:
--   1. The three refund helpers can't be called from the app or API at all.
--      They're only used inside record_refund, string_change_quote and
--      change_paid_string_job, which run with owner rights and still can.
--   2. string_job_strings_price stays callable (the job-entry trigger, which
--      runs as the signed-in user, needs it) but starts with require_staff().
--
-- The rule from here on (see supabase/README.md): an owner-rights function is
-- either granted to signed-in users and calls require_staff() (or only writes,
-- which the 0041 trigger refuses for non-staff), or isn't granted at all.
--
-- No data changes. Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Internal refund helpers: not callable from the app or API.
-- ----------------------------------------------------------------------------
revoke all on function sale_refund_tax(uuid, numeric, uuid)    from public, anon, authenticated;
revoke all on function sale_refundable_by_method(uuid, uuid)   from public, anon, authenticated;
revoke all on function refund_method_overages(uuid, uuid)      from public, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 2. string_job_strings_price — same as 0043, plus: staff only.
-- ----------------------------------------------------------------------------
create or replace function string_job_strings_price(p_main_product_id uuid, p_cross_product_id uuid)
returns numeric
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform require_staff();

  return round(
           coalesce((select stringing_labor from settings where id), 0)
         + coalesce((select sum(coalesce(p.sell_price, 0))
                       from products p
                      where p.id in (select distinct x
                                       from (values (p_main_product_id), (p_cross_product_id)) t(x)
                                      where x is not null)), 0),
         2);
end;
$$;

revoke all on function string_job_strings_price(uuid, uuid) from public, anon;
grant execute on function string_job_strings_price(uuid, uuid) to authenticated;

-- >>> supabase/migrations/0045_inventory_rules.sql
-- =============================================================================
-- 0045_inventory_rules.sql — unit tracking, barcodes and stock adjustments
--                            (AceStock, foundation code review #4, #16, #19, #31)
--
-- Before:
--   • Any staff member could switch a product's "track individual units" off;
--     the category's setting was only applied when the category changed. A
--     racquet switched off could be sold as ordinary stock while its units
--     stayed in stock, and so sold again by scanning a unit (#4).
--   • A code could mean two things: a unit received under a product's UPC (or
--     a racquet tag or gift card code) was found as the other thing and could
--     never be scanned, and the UPC-A and EAN-13 forms of one code could both
--     be stored and were found at random (#16).
--   • adjust_stock didn't lock the product or check a floor: "−999" worked even
--     with "block overselling" on, and could race a sale (#19).
--   • receive_stock / adjust_stock accepted unit-tracked products, whose stock
--     count ignores those entries (#31).
--
-- Now:
--   1. A product's unit tracking always comes from its category. A product
--      with stock history can't move to a category with the other setting,
--      and a category's setting can't change while its products have history.
--   2. Products: staff create and edit them; only admins delete them. Nobody
--      signed in can TRUNCATE a table (the API can't either; this closes it).
--   3. A code is used by at most one of: a product UPC, a unit barcode, an
--      active racquet tag, a gift card code — UPC-A and EAN-13 forms counting
--      as the same code. The code is locked while it's claimed, so two
--      registers can't take it at once. Barcode lookup prefers the exact form.
--   4. adjust_stock locks the product; with "block overselling" on, it can't
--      take on-hand stock below zero.
--   5. receive_stock and adjust_stock refuse unit-tracked products.
--
-- Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Unit tracking comes from the category.
-- ----------------------------------------------------------------------------
-- Whether a product has stock history: ledger rows, units, or sale lines.
create or replace function product_has_stock_history(p_product_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (select 1 from inventory_txns where product_id = p_product_id)
      or exists (select 1 from product_units  where product_id = p_product_id)
      or exists (select 1 from sale_lines     where product_id = p_product_id);
$$;

revoke all on function product_has_stock_history(uuid) from public, anon, authenticated;

-- Replaces 0033's trigger function: applied on every insert and on any change
-- to the category or the flag, whatever the client sent.
create or replace function apply_serialized_default()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  new.is_serialized := coalesce((select c.serialized_default from categories c where c.id = new.category_id), false);

  if tg_op = 'UPDATE' and new.is_serialized <> old.is_serialized and product_has_stock_history(old.id) then
    raise exception '% has stock history, so it can''t switch to % tracking',
      trim(coalesce(old.brand || ' ', '') || old.name),
      case when new.is_serialized then 'unit' else 'counted' end;
  end if;
  return new;
end;
$$;

revoke all on function apply_serialized_default() from public, anon, authenticated;

