-- >>> supabase/migrations/0047_settings_limits.sql
-- =============================================================================
-- 0047_settings_limits.sql — limits on shop settings
--                            (AceStock, foundation code review #11)
--
-- Before:
--   • Any number could be saved as a setting: a negative or 150% tax rate, a
--     negative stringing labor charge or reorder point. The web app's checks
--     were the only guard, and "8.25%" was saved as 0% tax.
--
-- Now:
--   1. The tax rate is between 0 and 100, the stringing labor charge is 0 or
--      more, and the default reorder point is empty or 0 or more. Anything
--      else is refused with a message naming the setting.
--
-- Re-runnable.
-- =============================================================================

create or replace function guard_settings()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.tax_rate < 0 or new.tax_rate > 100 then
    raise exception 'Tax rate must be between 0 and 100 (got %)', new.tax_rate;
  end if;
  if new.stringing_labor < 0 then
    raise exception 'Stringing labor can''t be negative (got %)', new.stringing_labor;
  end if;
  if new.default_reorder_point < 0 then
    raise exception 'Default reorder point can''t be negative (got %)', new.default_reorder_point;
  end if;
  return new;
end;
$$;

revoke all on function guard_settings() from public, anon, authenticated;

drop trigger if exists trg_guard_settings on settings;
create trigger trg_guard_settings
  before insert or update on settings
  for each row execute function guard_settings();

-- >>> supabase/migrations/0048_sales_summary.sql
-- =============================================================================
-- 0048_sales_summary.sql — gift cards counted once, items net of returns
--                          (AceStock, foundation code review #24)
--
-- Before:
--   • Gross receipts included gift card loads, so a $50 card sold and later
--     spent on $50 of goods added $100 of sales.
--   • "Items sold" counted everything rung up, ignoring returns.
--
-- Now:
--   1. gross is products and stringing only. A gift card counts as a sale when
--      it's spent (the goods it buys are in gross), not when it's sold.
--   2. New gift_cards_sold: the value loaded onto gift cards in the period,
--      reported on its own (money taken in that's owed back as goods).
--   3. net stays "money actually taken in": gross + tax − refunds + gift cards
--      sold, so it still equals the tender totals. Gift card loads can't be
--      returned (0030), so refunds never include them.
--   4. num_items is product quantities sold in the period, minus product
--      quantities returned in the period.
--
-- The return type gains a column, so the function is dropped and recreated;
-- it still runs with the caller's permissions (security invoker), so the
-- staff-only row rules decide what it sees, and only signed-in users can call
-- it. Re-runnable.
-- =============================================================================

drop function if exists sales_summary(timestamptz, timestamptz);

create function sales_summary(p_from timestamptz, p_to timestamptz)
returns table (
  gross           numeric,
  tax             numeric,
  refunds         numeric,
  net             numeric,
  card            numeric,
  cash            numeric,
  check_amt       numeric,
  store_credit    numeric,
  gift_card       numeric,
  num_customers   integer,
  num_tickets     integer,
  num_items       integer,
  gift_cards_sold numeric
)
language sql
stable
set search_path = public, pg_temp
as $$
  with s as (
    select id, tax, customer_id from sales where sold_at >= p_from and sold_at < p_to
  ),
  lines as (
    select sl.qty, sl.unit_price, sl.product_id, sl.gift_card_id
    from sale_lines sl join s on s.id = sl.sale_id
  ),
  pay as (select sp.method, sp.amount from sale_payments sp join s on s.id = sp.sale_id),
  r as (select id, subtotal, tax from refunds where refunded_at >= p_from and refunded_at < p_to),
  rpay as (select rp.method, rp.amount from refund_payments rp join r on r.id = rp.refund_id),
  returned_items as (
    select rl.qty
    from refund_lines rl
    join r on r.id = rl.refund_id
    join sale_lines sl on sl.id = rl.sale_line_id
    where sl.product_id is not null
  ),
  totals as (
    select
      coalesce((select sum(qty * unit_price) from lines where gift_card_id is null), 0) as gross,
      coalesce((select sum(qty * unit_price) from lines where gift_card_id is not null), 0) as gift_cards_sold,
      coalesce((select sum(tax) from s), 0)                                              as tax,
      coalesce((select sum(subtotal + tax) from r), 0)                                   as refunds
  )
  select
    t.gross,
    t.tax,
    t.refunds,
    t.gross + t.tax - t.refunds + t.gift_cards_sold                                             as net,
    coalesce((select sum(amount) from pay where method = 'credit'), 0)
      - coalesce((select sum(amount) from rpay where method = 'credit'), 0)                     as card,
    coalesce((select sum(amount) from pay where method = 'cash'), 0)
      - coalesce((select sum(amount) from rpay where method = 'cash'), 0)                       as cash,
    0::numeric                                                                                  as check_amt,
    coalesce((select sum(amount) from pay where method = 'store_credit'), 0)
      - coalesce((select sum(amount) from rpay where method = 'store_credit'), 0)               as store_credit,
    coalesce((select sum(amount) from pay where method = 'gift_card'), 0)
      - coalesce((select sum(amount) from rpay where method = 'gift_card'), 0)                  as gift_card,
    (select count(distinct customer_id) from s where customer_id is not null)::int              as num_customers,
    (select count(*) from s)::int                                                               as num_tickets,
    (coalesce((select sum(qty) from lines where product_id is not null), 0)
      - coalesce((select sum(qty) from returned_items), 0))::int                                as num_items,
    t.gift_cards_sold
  from totals t;
$$;

revoke all on function sales_summary(timestamptz, timestamptz) from public, anon;
grant execute on function sales_summary(timestamptz, timestamptz) to authenticated;

-- >>> supabase/migrations/0049_stock_quantities.sql
-- =============================================================================
-- 0049_stock_quantities.sql — stock quantities in whole or half units
--                              (AceStock, foundation code review #29)
--
-- Before:
--   • Receive and Adjust took any quantity, so typos like 1.37 or 0.0001 were
--     stored and the on-hand count stopped being a count.
--
-- Now:
--   1. A received or adjusted quantity is a whole number or a half (2, 2.5).
--      Halves are allowed because the stock imported from the old system
--      already counts string in half sets; existing quantities are untouched.
--   2. receive_stock and adjust_stock are the same as their latest versions
--      (0046 and 0045) plus that check at the start.
--
-- Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Internal helper: a quantity in whole or half units.
-- ----------------------------------------------------------------------------
create or replace function require_half_units(p_qty numeric, p_label text)
returns void
language plpgsql
immutable
set search_path = public, pg_temp
as $$
begin
  if p_qty is not null and p_qty * 2 <> trunc(p_qty * 2) then
    raise exception '% % must be a whole number or a half, like 2 or 2.5', p_label, trim_scale(p_qty);
  end if;
end;
$$;

revoke all on function require_half_units(numeric, text) from public, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 2. The two functions that take a stock quantity.
-- ----------------------------------------------------------------------------
create or replace function receive_stock(
  p_product_id uuid,
  p_qty        numeric,
  p_unit_cost  numeric,
  p_location   text,
  p_note       text
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id         uuid := gen_random_uuid();
  v_serialized boolean;
  v_name       text;
begin
  perform require_cents(p_unit_cost, 'Unit cost');
  perform require_half_units(p_qty, 'Quantity');
  if p_qty is null or p_qty <= 0 then
    raise exception 'Receive quantity must be positive';
  end if;
  select is_serialized, trim(coalesce(brand || ' ', '') || name) into v_serialized, v_name
    from products where id = p_product_id;
  if not found then
    raise exception 'Unknown product_id %', p_product_id;
  end if;
  if v_serialized then
    raise exception '% is tracked by unit; receive each one with its own barcode', v_name;
  end if;
  insert into inventory_txns (id, txn_type, product_id, qty, unit_cost, location, note)
  values (v_id, 'receive', p_product_id, p_qty, p_unit_cost, nullif(trim(p_location),''), nullif(trim(p_note),''));
  return v_id;
end;
$$;

create or replace function adjust_stock(p_product_id uuid, p_qty numeric, p_note text)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id         uuid := gen_random_uuid();
  v_serialized boolean;
  v_name       text;
  v_on_hand    numeric;
begin
  perform require_half_units(p_qty, 'Quantity');
  if p_qty is null or p_qty = 0 then
    raise exception 'Adjustment quantity must be non-zero';
  end if;
  -- Lock the product, so a sale of the same item waits (and vice versa).
  select is_serialized, trim(coalesce(brand || ' ', '') || name) into v_serialized, v_name
    from products where id = p_product_id
    for update;
  if not found then
    raise exception 'Unknown product_id %', p_product_id;
  end if;
  if v_serialized then
    raise exception '% is tracked by unit; its stock is the units in stock, not an adjustable count', v_name;
  end if;

  if p_qty < 0 and coalesce((select block_oversell from settings where id), false) then
    select coalesce(sum(qty), 0) into v_on_hand from inventory_txns where product_id = p_product_id;
    if v_on_hand + p_qty < 0 then
      raise exception 'Only % of % on hand; this would take it to %',
        trim_scale(v_on_hand), v_name, trim_scale(v_on_hand + p_qty);
    end if;
  end if;

  insert into inventory_txns (id, txn_type, product_id, qty, note)
  values (v_id, 'adjust', p_product_id, p_qty, nullif(trim(p_note),''));
  return v_id;
end;
$$;

revoke all on function receive_stock(uuid, numeric, numeric, text, text) from public, anon;
revoke all on function adjust_stock(uuid, numeric, text) from public, anon;
grant execute on function receive_stock(uuid, numeric, numeric, text, text) to authenticated;
grant execute on function adjust_stock(uuid, numeric, text) to authenticated;

-- >>> supabase/migrations/0050_real_numbers.sql
-- =============================================================================
-- 0050_real_numbers.sql — amounts and quantities must be real numbers
--                         (AceStock, polish review #1)
--
-- Before:
--   • Postgres numbers can be NaN ("not a number"), and NaN = NaN, so the
--     require_cents and require_half_units checks let it through. A NaN stock
--     quantity or gift card amount was stored for good, and every total built
--     on it (stock on hand, card balance) became NaN too.
--   • Infinity also passed the checks (the columns then refused it with a
--     raw error).
--
-- Now:
--   1. require_cents and require_half_units refuse NaN and infinity with a
--      message naming the field. Every function that takes an amount or a
--      quantity already calls one of them (0046, 0049).
--   2. Every stored number column refuses NaN, so direct table saves (a
--      product's price, a string job's tension) are covered too. Infinity
--      can't be stored in these columns at all.
--
-- AceStock-Test had no NaN values when this was written. Re-runnable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. The amount and quantity checks.
-- ----------------------------------------------------------------------------
-- require_cents — same as 0046, plus: a real number.
create or replace function require_cents(p_amount numeric, p_label text)
returns void
language plpgsql
immutable
set search_path = public, pg_temp
as $$
begin
  if p_amount in ('NaN', 'Infinity', '-Infinity') then
    raise exception '% must be a number (got %)', p_label, p_amount;
  end if;
  if p_amount is not null and p_amount <> round(p_amount, 2) then
    raise exception '% % has more than 2 decimal places', p_label, trim_scale(p_amount);
  end if;
end;
$$;

-- require_half_units — same as 0049, plus: a real number.
create or replace function require_half_units(p_qty numeric, p_label text)
returns void
language plpgsql
immutable
set search_path = public, pg_temp
as $$
begin
  if p_qty in ('NaN', 'Infinity', '-Infinity') then
    raise exception '% must be a number (got %)', p_label, p_qty;
  end if;
  if p_qty is not null and p_qty * 2 <> trunc(p_qty * 2) then
    raise exception '% % must be a whole number or a half, like 2 or 2.5', p_label, trim_scale(p_qty);
  end if;
end;
$$;

revoke all on function require_cents(numeric, text) from public, anon, authenticated;
revoke all on function require_half_units(numeric, text) from public, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 2. No NaN in any stored number.
-- ----------------------------------------------------------------------------
